"use client";

import { useState, useTransition } from "react";
import { checkIn, checkOut } from "@/lib/actions/attendance";
import type { MyTodayStatus } from "@/lib/actions/attendance";
import { useRouter } from "next/navigation";

interface Props {
  todayRecord: MyTodayStatus;
}

function formatTime(date: string | null | undefined): string {
  if (!date) return "—";
  return new Date(date).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
}

function formatHours(checkIn: string | null | undefined, checkOut: string | null | undefined): string {
  if (!checkIn) return "0h 0m";
  const end = checkOut ? new Date(checkOut) : new Date();
  const ms = end.getTime() - new Date(checkIn).getTime();
  const h = Math.floor(ms / 3_600_000);
  const m = Math.floor((ms % 3_600_000) / 60_000);
  return `${h}h ${m}m`;
}

export function AttendanceWidget({ todayRecord }: Props) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [error, setError] = useState("");

  const isClockedIn = !!todayRecord?.checkIn && !todayRecord?.checkOut;
  const isCheckedOut = !!todayRecord?.checkOut;

  function handleToggle() {
    setError("");
    startTransition(async () => {
      try {
        if (isClockedIn) {
          await checkOut();
        } else {
          await checkIn();
        }
        router.refresh();
      } catch (e) {
        setError(e instanceof Error ? e.message : "Action failed");
      }
    });
  }

  return (
    <div className="flex h-full flex-col card-p">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-emerald-light dark:bg-emerald-dark/20">
            <svg className="size-4 text-emerald" viewBox="0 0 24 24" fill="none">
              <path d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </div>
          <h3 className="section-title">Attendance</h3>
        </div>
        <span className={`rounded-full px-2 py-0.5 text-[10px] font-semibold ${
          isClockedIn
            ? "bg-emerald-light text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald"
            : isCheckedOut
            ? "bg-primary-50 text-primary-600 dark:bg-primary-900/20 dark:text-primary-300"
            : "bg-rose-light text-rose-dark dark:bg-rose-dark/20 dark:text-rose"
        }`}>
          {isClockedIn ? "● Present" : isCheckedOut ? "● Done" : "● Not In"}
        </span>
      </div>

      {/* Shift info */}
      <div className="mt-3 rounded-lg bg-gray-2 px-3 py-2 dark:bg-dark-3">
        <p className="text-muted">Today&apos;s Shift</p>
        <p className="text-body-medium font-semibold">9:00 AM – 6:00 PM</p>
      </div>

      {error && (
        <p className="mt-2 text-xs text-rose-600 dark:text-rose-400">{error}</p>
      )}

      {/* Clock in/out button */}
      <div className="mt-4 flex items-center justify-between gap-3">
        <div>
          <p className="text-muted">
            {isClockedIn || isCheckedOut ? "Clocked in at" : "Not clocked in"}
          </p>
          <p className="text-body font-bold">
            {formatTime(todayRecord?.checkIn)}
          </p>
          {(isClockedIn || isCheckedOut) && (
            <p className="text-muted">
              Working: <span className="font-medium text-dark dark:text-white">
                {formatHours(todayRecord?.checkIn, todayRecord?.checkOut)}
              </span>
            </p>
          )}
        </div>
        {!isCheckedOut && (
          <button
            onClick={handleToggle}
            disabled={isPending}
            className={`flex h-14 w-14 flex-col items-center justify-center rounded-xl text-[10px] font-bold text-white shadow-floating transition-all active:scale-95 disabled:opacity-60 ${
              isClockedIn ? "bg-rose hover:bg-rose-dark" : "bg-emerald hover:bg-emerald-dark"
            }`}
          >
            <svg className="mb-0.5 size-5" viewBox="0 0 24 24" fill="none">
              <path d="M5.636 5.636a9 9 0 1012.728 0M12 3v9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
            {isPending ? "…" : isClockedIn ? "OUT" : "IN"}
          </button>
        )}
      </div>

      {/* Weekly mini chart placeholder */}
      <div className="mt-4 divider pt-4">
        <p className="mb-2 text-muted font-medium">This Week</p>
        <div className="flex items-end gap-1.5">
          {["Mon", "Tue", "Wed", "Thu", "Fri"].map((day, i) => {
            const isToday = new Date().getDay() === i + 1;
            return (
              <div key={day} className="flex flex-1 flex-col items-center gap-1">
                <div className="relative w-full overflow-hidden rounded-t-sm" style={{ height: 36 }}>
                  <div
                    className={`absolute bottom-0 left-0 right-0 rounded-t-sm ${
                      isToday && (isClockedIn || isCheckedOut) ? "bg-emerald" : "bg-gray-3 dark:bg-dark-3"
                    }`}
                    style={{ height: isToday && (isClockedIn || isCheckedOut) ? "70%" : "20%" }}
                  />
                </div>
                <span className="text-muted text-[10px]">{day}</span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import type { CelebrationItem } from "@/lib/actions/celebrations";

interface Props {
  celebrations: CelebrationItem[];
}

export function BirthdayStrip({ celebrations }: Readonly<Props>) {
  const [wished, setWished] = useState<Set<string>>(new Set());
  const { toast, setToast } = useToast();

  const handleWish = (id: string, name: string) => {
    setWished((prev) => new Set(prev).add(id));
    setToast(`Wish sent to ${name}! 🎉`);
  };

  if (celebrations.length === 0) {
    return (
      <div className="card-p">
        <h3 className="section-title">Celebrations this week</h3>
        <p className="mt-3 text-sm text-dark-5 dark:text-dark-6">No upcoming anniversaries this week.</p>
      </div>
    );
  }

  return (
    <div className="card-p">
      <div className="flex items-center justify-between">
        <h3 className="section-title">Celebrations this week</h3>
        <span className="rounded-full bg-amber-light px-2 py-0.5 text-[10px] font-bold text-amber-dark dark:bg-amber-dark/20 dark:text-amber">
          {celebrations.length} upcoming
        </span>
      </div>

      <div className="mt-4 flex flex-wrap gap-3">
        {celebrations.map((person) => (
          <div
            key={person.id}
            className="flex items-center gap-2.5 rounded-xl border border-gray-3 px-3 py-2.5 dark:border-dark-3"
          >
            <Image
              src={person.avatarUrl ?? "/images/user/user-03.png"}
              width={36}
              height={36}
              alt={person.name}
              className="rounded-full object-cover"
            />
            <div>
              <p className="text-xs font-semibold text-dark dark:text-white">{person.name}</p>
              <p className="text-[10px] text-dark-5 dark:text-dark-6">{person.label}</p>
            </div>
            {wished.has(person.id) ? (
              <button
                disabled
                className="ml-1 rounded-lg bg-emerald-50 px-2.5 py-1.5 text-[10px] font-semibold text-emerald-600 dark:bg-emerald-900/20 dark:text-emerald-300 cursor-default"
              >
                Wished ✓
              </button>
            ) : (
              <button
                onClick={() => handleWish(person.id, person.name)}
                className="ml-1 rounded-lg bg-primary-50 px-2.5 py-1.5 text-[10px] font-semibold text-primary-600 transition-colors hover:bg-primary-100 dark:bg-primary-900/20 dark:text-primary-300 dark:hover:bg-primary-900/30"
              >
                Wish
              </button>
            )}
          </div>
        ))}
      </div>

      <Toast message={toast} />
    </div>
  );
}

import Link from "next/link";
import type { CalendarData } from "@/lib/actions/reports";

const TYPE_STYLE: Record<string, { bar: string; badge: string; label: string }> = {
  leave: {
    bar: "bg-amber-dark",
    badge: "bg-amber-light text-amber-dark dark:bg-amber-dark/20 dark:text-amber",
    label: "Leave",
  },
  task: {
    bar: "bg-rose-dark",
    badge: "bg-rose-light text-rose-dark dark:bg-rose-dark/20 dark:text-rose",
    label: "Due",
  },
};

interface Props {
  calendarData: CalendarData;
}

function getCurrentWeekDays(): { label: string; date: number; isToday: boolean }[] {
  const now = new Date();
  const dayOfWeek = now.getDay();
  const diffToMon = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
  const monday = new Date(now);
  monday.setDate(now.getDate() + diffToMon);

  const DAY_LABELS = ["M", "T", "W", "T", "F", "S", "S"];
  return DAY_LABELS.map((label, i) => {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    return {
      label,
      date: d.getDate(),
      isToday: d.toDateString() === now.toDateString(),
    };
  });
}

export function CalendarPreview({ calendarData }: Readonly<Props>) {
  const weekDays = getCurrentWeekDays();
  const todayStr = new Date().toDateString();

  const todayLeaves = calendarData.leaveEvents.filter((e) => {
    const start = new Date(e.startDate);
    const end = new Date(e.endDate);
    const now = new Date();
    return start <= now && now <= end && e.status === "APPROVED";
  });

  const todayTasks = calendarData.taskEvents.filter((e) => {
    if (!e.dueDate) return false;
    return new Date(e.dueDate).toDateString() === todayStr && e.status !== "DONE";
  });

  const events = [
    ...todayLeaves.map((e) => ({
      title: e.title,
      time: "All day",
      type: "leave" as const,
    })),
    ...todayTasks.map((e) => ({
      title: e.title,
      time: `Due today · ${e.priority}`,
      type: "task" as const,
    })),
  ];

  return (
    <div className="flex h-full flex-col card-p">
      <div className="flex items-center justify-between">
        <h3 className="section-title">Today&apos;s Schedule</h3>
        <Link href="/calendar" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">
          Calendar
        </Link>
      </div>

      <div className="mt-3 flex gap-1">
        {weekDays.map((d, i) => (
          <div
            key={i}
            className={`flex flex-1 flex-col items-center rounded-lg py-1.5 text-[10px] font-medium ${
              d.isToday ? "bg-primary-600 text-white" : "text-dark-5 dark:text-dark-6"
            }`}
          >
            <span>{d.label}</span>
            <span className={`mt-0.5 font-bold ${d.isToday ? "text-white" : "text-dark dark:text-white"}`}>
              {d.date}
            </span>
          </div>
        ))}
      </div>

      <ul className="mt-4 flex-1 space-y-2.5 overflow-y-auto">
        {events.length === 0 ? (
          <li className="py-4 text-center text-xs text-dark-5 dark:text-dark-6">No events today.</li>
        ) : (
          events.map((ev, i) => {
            const style = TYPE_STYLE[ev.type];
            return (
              <li key={i} className="flex items-start gap-2.5">
                <div className={`mt-0.5 w-0.5 self-stretch shrink-0 rounded-full ${style.bar}`} />
                <div className="min-w-0 flex-1">
                  <p className="truncate text-xs font-semibold text-dark dark:text-white">{ev.title}</p>
                  <span className="text-[10px] text-dark-5 dark:text-dark-6">{ev.time}</span>
                </div>
                <span className={`shrink-0 rounded px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-wide ${style.badge}`}>
                  {style.label}
                </span>
              </li>
            );
          })
        )}
      </ul>
    </div>
  );
}

import Link from "next/link";
import type { Channel } from "@/lib/actions/collaboration";
import type { SerializedMeeting } from "@/lib/actions/meetings";

interface Props {
  channels: Channel[];
  liveMeetings: SerializedMeeting[];
}

function relativeTime(dateStr: string | null): string {
  if (!dateStr) return "";
  const diff = Math.floor((Date.now() - new Date(dateStr).getTime()) / 60_000);
  if (diff < 1) return "Just now";
  if (diff < 60) return `${diff}m`;
  const hrs = Math.floor(diff / 60);
  if (hrs < 24) return `${hrs}h`;
  return `${Math.floor(hrs / 24)}d`;
}

export function CollaborationPreview({ channels, liveMeetings }: Readonly<Props>) {
  const displayChannels = channels.slice(0, 4);

  return (
    <div className="flex h-full flex-col card-p">
      <div className="flex items-center justify-between">
        <h3 className="section-title">Collaboration</h3>
        <Link href="/collaboration" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">
          Open
        </Link>
      </div>

      {liveMeetings.length > 0 && (
        <div className="mt-3 flex flex-wrap gap-2">
          {liveMeetings.slice(0, 2).map((m) => (
            <div
              key={m.id}
              className="flex items-center gap-1.5 rounded-lg border border-emerald-light bg-emerald-light px-2.5 py-1.5 dark:border-emerald-dark/30 dark:bg-emerald-dark/10"
            >
              <span className="inline-block h-1.5 w-1.5 animate-pulse rounded-full bg-emerald" />
              <span className="text-[11px] font-semibold text-emerald-dark dark:text-emerald">{m.title}</span>
              <span className="text-[10px] text-dark-5 dark:text-dark-6">{m.participants.length} live</span>
            </div>
          ))}
        </div>
      )}

      <ul className="mt-3 flex-1 divide-y divide-gray-3 overflow-y-auto dark:divide-dark-3">
        {displayChannels.length === 0 ? (
          <li className="py-4 text-center text-xs text-dark-5 dark:text-dark-6">No channels yet.</li>
        ) : (
          displayChannels.map((ch) => (
            <li key={ch.id}>
              <Link href="/collaboration/messages" className="flex items-center gap-3 py-2.5 hover:opacity-80">
                <div className="flex size-9 shrink-0 items-center justify-center rounded-full bg-primary-50 dark:bg-primary-900/20">
                  <span className="text-sm font-bold text-primary-600 dark:text-primary-300">#</span>
                </div>

                <div className="min-w-0 flex-1">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-semibold text-dark dark:text-white">
                      {ch.name}
                    </span>
                    <span className="text-[10px] text-dark-5 dark:text-dark-6">
                      {relativeTime(ch.lastMessageAt)}
                    </span>
                  </div>
                  <p className="mt-0.5 truncate text-[11px] text-dark-5 dark:text-dark-6">
                    {ch.lastMessage ?? "No messages yet"}
                  </p>
                </div>

                {ch.messageCount > 0 && (
                  <span className="ml-1 flex min-w-[18px] items-center justify-center rounded-full bg-primary-600 px-1 py-0.5 text-[10px] font-bold text-white">
                    {ch.messageCount > 99 ? "99+" : ch.messageCount}
                  </span>
                )}
              </Link>
            </li>
          ))
        )}
      </ul>

      <div className="mt-3 flex items-center gap-2 rounded-lg border border-gray-3 px-3 py-2 dark:border-dark-3">
        <svg className="size-4 shrink-0 text-dark-5" viewBox="0 0 24 24" fill="none">
          <path d="M21.731 2.269a2.625 2.625 0 00-3.712 0l-1.157 1.157 3.712 3.712 1.157-1.157a2.625 2.625 0 000-3.712zM19.513 8.199l-3.712-3.712-12.15 12.15a5.25 5.25 0 00-1.32 2.214l-.8 2.685a.75.75 0 00.933.933l2.685-.8a5.25 5.25 0 002.214-1.32L19.513 8.2z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
        <span className="flex-1 text-muted">New message...</span>
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useSession } from "next-auth/react";

const QUICK_ACTIONS = [
  {
    label: "Clock In",
    href: "/attendance",
    icon: (
      <svg className="size-4" viewBox="0 0 24 24" fill="none">
        <path d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
    color: "bg-emerald text-white hover:bg-emerald-dark",
  },
  {
    label: "Apply Leave",
    href: "/leave",
    icon: (
      <svg className="size-4" viewBox="0 0 24 24" fill="none">
        <path d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
    color: "bg-primary-100 text-primary-700 hover:bg-primary-200 dark:bg-primary-900/30 dark:text-primary-300 dark:hover:bg-primary-900/50",
  },
  {
    label: "New Task",
    href: "/tasks",
    icon: (
      <svg className="size-4" viewBox="0 0 24 24" fill="none">
        <path d="M12 4.5v15m7.5-7.5h-15" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
    color: "bg-gray-2 text-dark-5 hover:bg-gray-3 dark:bg-dark-3 dark:text-dark-6 dark:hover:bg-dark-4",
  },
];

function getGreeting() {
  const hour = new Date().getHours();
  if (hour < 12) return "Good morning";
  if (hour < 17) return "Good afternoon";
  return "Good evening";
}

function formatDate() {
  return new Date().toLocaleDateString("en-US", {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  });
}

export function GreetingHeader() {
  const { data: session } = useSession();
  const name = session?.user?.name ?? session?.user?.email?.split("@")[0] ?? "there";
  const role = session?.user?.role?.replace(/_/g, " ").toLowerCase() ?? "employee";
  const org = session?.user?.orgName ?? "Monja";

  return (
    <div className="card-p md:p-6">
      <div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between">
        {/* Left: greeting */}
        <div className="space-y-1">
          <p className="text-muted font-medium">
            {formatDate()}
          </p>
          <h2 className="page-title md:text-2xl capitalize">
            {getGreeting()}, {name}
          </h2>
          <p className="text-sm text-dark-5 dark:text-dark-6 capitalize">
            {role} · {org}
          </p>
        </div>

        {/* Right: quick actions */}
        <div className="flex shrink-0 flex-wrap gap-2">
          {QUICK_ACTIONS.map((a) => (
            <Link
              key={a.label}
              href={a.href}
              className={`flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-xs font-semibold transition-colors ${a.color}`}
            >
              {a.icon}
              {a.label}
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
}

import Link from "next/link";
import type { SerializedLeaveBalance } from "@/lib/actions/leave";

const LEAVE_COLORS: Record<string, string> = {
  ANNUAL: "bg-primary-500",
  SICK: "bg-amber",
  CASUAL: "bg-emerald",
  MATERNITY: "bg-rose-400",
  PATERNITY: "bg-violet-DEFAULT",
  OTHER: "bg-sky-500",
  UNPAID: "bg-gray-400",
};

const LEAVE_LABELS: Record<string, string> = {
  ANNUAL: "Annual Leave",
  SICK: "Sick Leave",
  CASUAL: "Casual Leave",
  MATERNITY: "Maternity Leave",
  PATERNITY: "Paternity Leave",
  UNPAID: "Unpaid Leave",
  OTHER: "Other Leave",
};

interface Props {
  balances: SerializedLeaveBalance[];
}

export function LeaveBalanceCard({ balances }: Props) {
  const totalRemaining = balances.reduce(
    (sum, b) => sum + (b.total - b.used - b.pending),
    0,
  );

  const displayBalances = balances.length > 0
    ? balances.slice(0, 4)
    : [
        { leaveType: "ANNUAL", used: 0, total: 30, pending: 0 },
        { leaveType: "SICK", used: 0, total: 10, pending: 0 },
        { leaveType: "CASUAL", used: 0, total: 10, pending: 0 },
      ];

  return (
    <div className="flex h-full flex-col card-p">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary-50 dark:bg-primary-900/20">
            <svg className="size-4 text-primary-600 dark:text-primary-400" viewBox="0 0 24 24" fill="none">
              <path d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </div>
          <h3 className="section-title">Leave Balance</h3>
        </div>
        <span className="text-muted">FY {new Date().getFullYear()}–{String(new Date().getFullYear() + 1).slice(2)}</span>
      </div>

      {/* Total highlight */}
      <div className="mt-3 rounded-lg bg-gradient-ai-soft px-3 py-2.5">
        <p className="text-muted">Total Available</p>
        <div className="flex items-baseline gap-1">
          <span className="text-2xl font-bold text-primary-600 dark:text-primary-300">{totalRemaining}</span>
          <span className="text-muted">days remaining</span>
        </div>
      </div>

      {/* Leave breakdown */}
      <div className="mt-4 flex-1 space-y-3">
        {displayBalances.map((l) => {
          const remaining = l.total - l.used - (l.pending ?? 0);
          const pct = l.total > 0 ? Math.round((remaining / l.total) * 100) : 0;
          const color = LEAVE_COLORS[l.leaveType] ?? "bg-gray-400";
          const label = LEAVE_LABELS[l.leaveType] ?? l.leaveType;
          return (
            <div key={l.leaveType}>
              <div className="mb-1 flex items-center justify-between">
                <span className="text-xs font-medium text-dark dark:text-white">{label}</span>
                <span className="text-muted">
                  <span className="font-semibold text-dark dark:text-white">{remaining}</span>
                  /{l.total}d
                </span>
              </div>
              <div className="h-1.5 overflow-hidden rounded-full bg-gray-3 dark:bg-dark-3">
                <div
                  className={`h-full rounded-full transition-all duration-700 ${color}`}
                  style={{ width: `${pct}%` }}
                />
              </div>
            </div>
          );
        })}
      </div>

      {/* CTA */}
      <Link
        href="/leave"
        className="mt-4 flex items-center justify-center gap-1.5 rounded-lg border border-primary-200 py-2 text-xs font-semibold text-primary-600 transition-colors hover:bg-primary-50 dark:border-primary-800 dark:text-primary-400 dark:hover:bg-primary-900/20"
      >
        <svg className="size-3.5" viewBox="0 0 24 24" fill="none">
          <path d="M12 4.5v15m7.5-7.5h-15" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
        Apply Leave
      </Link>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter, usePathname } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import type { SerializedAuditLog } from "@/lib/actions/audit";

const EVENT_TYPES = ["All", "employee", "leave", "payroll", "auth", "system"] as const;

const severityColors: Record<string, string> = {
  Info: "badge-ai",
  Warning: "badge-warning",
  Error: "badge-error",
  Critical: "badge-error bg-rose-600 text-white dark:bg-rose-600 dark:text-white",
};

interface Props {
  logs: SerializedAuditLog[];
  from: string;
  to: string;
  type: string;
}

export function AuditClient({ logs, from, to, type }: Props) {
  const router = useRouter();
  const pathname = usePathname();
  const [, startTransition] = useTransition();
  const [fromDate, setFromDate] = useState(from);
  const [toDate, setToDate] = useState(to);
  const [activeFilter, setActiveFilter] = useState(type);
  const { toast, setToast } = useToast();

  function applyFilters(newFrom: string, newTo: string, newType: string) {
    const params = new URLSearchParams({ from: newFrom, to: newTo, type: newType });
    startTransition(() => {
      router.push(`${pathname}?${params.toString()}`);
    });
  }

  function handleDateChange(field: "from" | "to", value: string) {
    if (field === "from") {
      setFromDate(value);
      applyFilters(value, toDate, activeFilter);
    } else {
      setToDate(value);
      applyFilters(fromDate, value, activeFilter);
    }
  }

  function handleTypeFilter(t: string) {
    setActiveFilter(t);
    applyFilters(fromDate, toDate, t);
  }

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Audit Logs</h1>
          <p className="mt-0.5 text-muted">
            Complete activity trail — {logs.length} event{logs.length !== 1 ? "s" : ""} found
          </p>
        </div>
        <div className="flex items-center gap-2">
          <input
            type="date"
            value={fromDate}
            onChange={(e) => handleDateChange("from", e.target.value)}
            className="input-field h-9"
          />
          <span className="text-muted">to</span>
          <input
            type="date"
            value={toDate}
            onChange={(e) => handleDateChange("to", e.target.value)}
            className="input-field h-9"
          />
          <button
            onClick={() => {
              const header = "Date,User,Action,Resource,Details,IP,Severity";
              const rows = logs.map((l) =>
                [
                  new Date(l.createdAt).toISOString(),
                  l.userEmail,
                  l.action,
                  l.resource,
                  (l.details ?? "").replace(/,/g, ";"),
                  l.ipAddress ?? "",
                  l.severity,
                ].join(",")
              );
              const csv = [header, ...rows].join("\n");
              const blob = new Blob([csv], { type: "text/csv" });
              const url = URL.createObjectURL(blob);
              const a = document.createElement("a");
              a.href = url;
              a.download = `audit-log-${fromDate}-to-${toDate}.csv`;
              a.click();
              URL.revokeObjectURL(url);
              setToast("Audit log exported!");
            }}
            className="btn-primary flex items-center gap-1.5"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export
          </button>
        </div>
      </div>

      {/* Event Type Filter */}
      <div className="flex flex-wrap gap-2">
        {EVENT_TYPES.map((t) => (
          <button
            key={t}
            onClick={() => handleTypeFilter(t)}
            className={`rounded-lg px-4 py-2 text-sm font-medium capitalize transition-colors ${
              activeFilter === t
                ? "bg-primary-600 text-white"
                : "btn-secondary"
            }`}
          >
            {t === "All" ? "All" : t}
          </button>
        ))}
      </div>

      {/* Audit Table */}
      <div className="card overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="thead-row">
                <th className="th">Timestamp</th>
                <th className="th">User</th>
                <th className="th">Action</th>
                <th className="th">Resource</th>
                <th className="th">IP Address</th>
                <th className="th">Severity</th>
              </tr>
            </thead>
            <tbody>
              {logs.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-5 py-8 text-center text-muted">
                    No audit events found for the selected period
                  </td>
                </tr>
              )}
              {logs.map((log) => (
                <tr key={log.id} className="tr-body">
                  <td className="td font-mono text-xs whitespace-nowrap">
                    {new Date(log.createdAt).toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit", second: "2-digit" })}
                  </td>
                  <td className="td font-medium whitespace-nowrap">
                    {log.userEmail}
                  </td>
                  <td className="td">
                    <span className="text-body">{log.action}</span>
                  </td>
                  <td className="td text-muted">{log.resource}</td>
                  <td className="td font-mono text-xs text-muted">
                    {log.ipAddress ?? "—"}
                  </td>
                  <td className="td">
                    <span className={severityColors[log.severity] ?? severityColors.Info}>
                      {log.severity}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState } from "react";

const PLAN_OPTIONS = ["BASIC", "PRO", "PRO_PLUS", "PRO_MAX"] as const;
const PLAN_LABELS: Record<string, string> = { BASIC: "Basic", PRO: "Pro", PRO_PLUS: "Pro+", PRO_MAX: "Pro Max" };

