        </form>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  createOrganization,
  updateOrgPlan,
  deleteOrganization,
} from "@/lib/actions/organizations";
import { CreateOrgModal } from "./create-org-modal";

type Org = {
  id: string;
  name: string;
  slug: string;
  plan: string;
  logoUrl: string | null;
  address: string | null;
  createdAt: string;
  userCount: number;
  employeeCount: number;
  subscriptionStatus: string | null;
  subscriptionEnds: string | null;
};

const PLAN_OPTIONS = ["BASIC", "PRO", "PRO_PLUS", "PRO_MAX"] as const;

const PLAN_LABELS: Record<string, string> = {
  BASIC: "Basic",
  PRO: "Pro",
  PRO_PLUS: "Pro+",
  PRO_MAX: "Pro Max",
};

const PLAN_COLORS: Record<string, string> = {
  BASIC: "bg-gray-2 text-dark-5 dark:bg-dark-3 dark:text-dark-6",
  PRO: "bg-sky-50 text-sky-dark dark:bg-sky-dark/10 dark:text-sky",
  PRO_PLUS: "bg-primary-50 text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
  PRO_MAX: "bg-violet-light text-violet-dark dark:bg-violet-dark/20 dark:text-violet-300",
};

export function OrganizationsClient({ orgs: initial }: Readonly<{ orgs: Org[] }>) {
  const router = useRouter();
  const [orgs, setOrgs] = useState(initial);
  const [showCreate, setShowCreate] = useState(false);

  useEffect(() => {
    setOrgs(initial);
  }, [initial]);
  const [error, setError] = useState("");
  const [isPending, startTransition] = useTransition();

  async function handleCreate(form: { name: string; slug: string; plan: string; adminEmail: string; adminPassword: string; adminName: string }) {
    setError("");
    return new Promise<void>((resolve, reject) => {
      startTransition(async () => {
        try {
          await createOrganization({
            ...form,
            plan: form.plan as "BASIC" | "PRO" | "PRO_PLUS" | "PRO_MAX",
          });
          setShowCreate(false);
          router.refresh();
          resolve();
        } catch (err) {
          setError(err instanceof Error ? err.message : "Failed to create organization");
          reject(err);
        }
      });
    });
  }

  function handlePlanChange(orgId: string, plan: string) {
    startTransition(async () => {
      try {
        await updateOrgPlan({ orgId, plan: plan as "BASIC" | "PRO" | "PRO_PLUS" | "PRO_MAX" });
        setOrgs((prev) => prev.map((o) => (o.id === orgId ? { ...o, plan } : o)));
      } catch (err) {
        alert(err instanceof Error ? err.message : "Failed to update plan");
      }
    });
  }

  function handleDelete(orgId: string, orgName: string) {
    if (!confirm(`Delete "${orgName}"? This will permanently remove all data for this organization.`)) return;
    startTransition(async () => {
      try {
        await deleteOrganization(orgId);
        setOrgs((prev) => prev.filter((o) => o.id !== orgId));
      } catch (err) {
        alert(err instanceof Error ? err.message : "Failed to delete organization");
      }
    });
  }

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Organizations</h1>
          <p className="mt-0.5 text-muted">{orgs.length} organization{orgs.length !== 1 ? "s" : ""} on platform</p>
        </div>
        <button
          onClick={() => setShowCreate(true)}
          className="btn-primary"
        >
          + New Organization
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        {PLAN_OPTIONS.map((plan) => {
          const count = orgs.filter((o) => o.plan === plan).length;
          return (
            <div key={plan} className="stat-card">
              <p className="stat-label">{PLAN_LABELS[plan]}</p>
              <p className="stat-value mt-1">{count}</p>
            </div>
          );
        })}
      </div>

      {/* Orgs table */}
      <div className="rounded-xl bg-white shadow-card dark:bg-dark-2 dark:border dark:border-dark-3 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-2 dark:border-dark-3 bg-gray-1 dark:bg-dark-3/50">
                <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Organization</th>
                <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Slug</th>
                <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Plan</th>
                <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Users</th>
                <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Created</th>
                <th className="px-5 py-3 text-left text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Actions</th>
              </tr>
            </thead>
            <tbody>
              {orgs.map((org) => (
                <tr key={org.id} className="border-b border-gray-2 dark:border-dark-3 last:border-0 hover:bg-gray-1 dark:hover:bg-dark-3/30 transition-colors">
                  <td className="px-5 py-3.5">
                    <p className="font-medium text-dark dark:text-white">{org.name}</p>
                    <p className="text-[11px] text-dark-5 dark:text-dark-6">{org.employeeCount} employees</p>
                  </td>
                  <td className="px-5 py-3.5 font-mono text-xs text-dark-5 dark:text-dark-6">{org.slug}</td>
                  <td className="px-5 py-3.5">
                    <select
                      value={org.plan}
                      disabled={isPending}
                      onChange={(e) => handlePlanChange(org.id, e.target.value)}
                      className={`rounded-full border-0 px-2.5 py-1 text-[11px] font-semibold focus:ring-1 focus:ring-primary-300 ${PLAN_COLORS[org.plan]}`}
                    >
                      {PLAN_OPTIONS.map((p) => (
                        <option key={p} value={p}>{PLAN_LABELS[p]}</option>
                      ))}
                    </select>
                  </td>
                  <td className="px-5 py-3.5 text-dark dark:text-white">{org.userCount}</td>
                  <td className="px-5 py-3.5 text-dark-5 dark:text-dark-6">
                    {new Date(org.createdAt).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                  </td>
                  <td className="px-5 py-3.5">
                    <button
                      onClick={() => handleDelete(org.id, org.name)}
                      disabled={isPending}
                      className="text-xs font-medium text-rose-600 hover:text-rose-700 disabled:opacity-50"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
              {orgs.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-5 py-8 text-center text-sm text-dark-5 dark:text-dark-6">No organizations yet</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showCreate && (
        <CreateOrgModal
          onClose={() => { setShowCreate(false); setError(""); }}
          onCreate={handleCreate}
          error={error}
          isPending={isPending}
        />
      )}
    </div>
  );
}

"use client";

import { useState } from "react";

interface Props {
  onSave: () => void;
}

export function PasswordPolicyCard({ onSave }: Readonly<Props>) {
  const [minLength, setMinLength] = useState(8);
  const [maxAge, setMaxAge] = useState(90);
  const [historyCount, setHistoryCount] = useState(5);
  const [lockoutAttempts, setLockoutAttempts] = useState(5);
  const [requireUppercase, setRequireUppercase] = useState(true);
  const [requireLowercase, setRequireLowercase] = useState(true);
  const [requireNumbers, setRequireNumbers] = useState(true);
  const [requireSymbols, setRequireSymbols] = useState(true);
  const [disallowCommon, setDisallowCommon] = useState(true);

  return (
    <div className="card-p">
      <div className="flex items-center justify-between mb-4">
        <h2 className="section-title">Password Policy</h2>
        <button onClick={onSave} className="btn-primary">Save Changes</button>
      </div>
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        <div>
          <label className="label-field">Minimum Password Length</label>
          <input type="number" value={minLength} onChange={(e) => setMinLength(Number(e.target.value))} className="input-field h-9 w-full" />
        </div>
        <div>
          <label className="label-field">Password Expiry (days)</label>
          <input type="number" value={maxAge} onChange={(e) => setMaxAge(Number(e.target.value))} className="input-field h-9 w-full" />
        </div>
        <div>
          <label className="label-field">Password History (prevent reuse)</label>
          <input type="number" value={historyCount} onChange={(e) => setHistoryCount(Number(e.target.value))} className="input-field h-9 w-full" />
        </div>
        <div>
          <label className="label-field">Max Login Attempts</label>
          <input type="number" value={lockoutAttempts} onChange={(e) => setLockoutAttempts(Number(e.target.value))} className="input-field h-9 w-full" />
        </div>
      </div>
      <div className="mt-4 space-y-3">
        {[
          { label: "Require uppercase letters", value: requireUppercase, setter: setRequireUppercase },
          { label: "Require lowercase letters", value: requireLowercase, setter: setRequireLowercase },
          { label: "Require numbers", value: requireNumbers, setter: setRequireNumbers },
          { label: "Require special characters (!@#$)", value: requireSymbols, setter: setRequireSymbols },
          { label: "Disallow common passwords", value: disallowCommon, setter: setDisallowCommon },
        ].map((item) => (
          <label key={item.label} className="flex items-center gap-3 cursor-pointer">
            <input type="checkbox" checked={item.value} onChange={(e) => item.setter(e.target.checked)} className="h-4 w-4 rounded border-gray-3 accent-primary-600" />
            <span className="text-body">{item.label}</span>
          </label>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { updateUserRole, toggleUserActive } from "@/lib/actions/admin";

type UserRole = "SUPER_ADMIN" | "HR_ADMIN" | "MANAGER" | "EMPLOYEE";

type OrgUser = {
  id: string;
  email: string;
  role: UserRole;
  isActive: boolean;
  createdAt: string;
  lastLoginAt: string | null;
  name: string;
  avatarUrl: string | null;
  department: string;
  title: string;
};

const ROLE_LABELS: Record<UserRole, string> = {
  SUPER_ADMIN: "Super Admin",
  HR_ADMIN: "HR Admin",
  MANAGER: "Manager",
  EMPLOYEE: "Employee",
};

const ROLE_COLORS: Record<UserRole, string> = {
  SUPER_ADMIN: "badge-error",
  HR_ADMIN: "badge-ai",
  MANAGER: "badge-warning",
  EMPLOYEE: "badge-success",
};

function getInitials(name: string) {
  return name.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 2);
}

function formatDate(iso: string | null) {
  if (!iso) return "Never";
  const d = new Date(iso);
  const diff = Date.now() - d.getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "Just now";
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

export function AdminUsersClient({ users }: Readonly<{ users: OrgUser[] }>) {
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState<UserRole | "All">("All");
  const [showInviteModal, setShowInviteModal] = useState(false);
  const { toast, setToast } = useToast();
  const router = useRouter();

  const filtered = users.filter((u) => {
    const matchSearch = !search
      || u.name.toLowerCase().includes(search.toLowerCase())
      || u.email.toLowerCase().includes(search.toLowerCase());
    const matchRole = roleFilter === "All" || u.role === roleFilter;
    return matchSearch && matchRole;
  });

  async function handleRoleChange(userId: string, newRole: UserRole) {
    try {
      await updateUserRole({ userId, role: newRole });
      setToast("Role updated successfully.");
      router.refresh();
    } catch {
      setToast("Failed to update role.");
    }
  }

  async function handleToggleActive(userId: string, isActive: boolean) {
    try {
      await toggleUserActive(userId);
      setToast(isActive ? "User deactivated." : "User activated.");
      router.refresh();
    } catch {
      setToast("Failed to update user status.");
    }
  }

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">User Management</h1>
          <p className="mt-0.5 text-muted">{users.length} users · Manage roles and access</p>
        </div>
        <button
          onClick={() => setShowInviteModal(true)}
          className="btn-primary"
        >
          + Invite User
        </button>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-3">
        <input
          type="text"
          placeholder="Search by name or email..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="input-field w-full sm:w-64"
        />
        <select
          value={roleFilter}
          onChange={(e) => setRoleFilter(e.target.value as UserRole | "All")}
          className="input-field"
        >
          <option value="All">All Roles</option>
          <option value="SUPER_ADMIN">Super Admin</option>
          <option value="HR_ADMIN">HR Admin</option>
          <option value="MANAGER">Manager</option>
          <option value="EMPLOYEE">Employee</option>
        </select>
      </div>

      {/* Users Table */}
      <div className="card overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="thead-row">
                <th className="th">User</th>
                <th className="th">Role</th>
                <th className="th">Department</th>
                <th className="th">Status</th>
                <th className="th">Last Active</th>
                <th className="th text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((u) => (
                <tr key={u.id} className="tr-body">
                  <td className="td">
                    <div className="flex items-center gap-3">
                      {u.avatarUrl ? (
                        <Image
                          src={u.avatarUrl}
                          alt={u.name}
                          width={32}
                          height={32}
                          className="h-8 w-8 rounded-full object-cover"
                        />
                      ) : (
                        <span className="flex h-8 w-8 items-center justify-center rounded-full bg-primary-100 text-xs font-bold text-primary-600 dark:bg-primary-900/30 dark:text-primary-300">
                          {getInitials(u.name)}
                        </span>
                      )}
                      <div>
                        <p className="text-body-medium">{u.name}</p>
                        <p className="text-muted">{u.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="td">
                    <select
                      value={u.role}
                      onChange={(e) => handleRoleChange(u.id, e.target.value as UserRole)}
                      className="input-field py-1 text-xs"
                    >
                      <option value="SUPER_ADMIN">Super Admin</option>
                      <option value="HR_ADMIN">HR Admin</option>
                      <option value="MANAGER">Manager</option>
                      <option value="EMPLOYEE">Employee</option>
                    </select>
                  </td>
                  <td className="td text-muted">{u.department}</td>
                  <td className="td">
                    <span className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${u.isActive ? "badge-success" : "badge-error"}`}>
                      {u.isActive ? "Active" : "Inactive"}
                    </span>
                  </td>
                  <td className="td text-muted">{formatDate(u.lastLoginAt)}</td>
                  <td className="td text-right">
                    <button
                      onClick={() => handleToggleActive(u.id, u.isActive)}
                      className={`rounded px-2.5 py-1 text-xs font-semibold transition-colors ${
                        u.isActive
                          ? "bg-rose-light text-rose-dark hover:bg-rose-dark hover:text-white"
                          : "bg-emerald-light text-emerald-dark hover:bg-emerald-dark hover:text-white"
                      }`}
                    >
                      {u.isActive ? "Deactivate" : "Activate"}
                    </button>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-5 py-8 text-center text-muted">
                    No users match your filter.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Invite Modal */}
      {showInviteModal && (
        <div className="modal-overlay">
          <div className="modal-panel w-full max-w-md">
            <div className="modal-header">
              <h2 className="text-lg font-bold text-dark dark:text-white">Invite User</h2>
              <button onClick={() => setShowInviteModal(false)} className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
                <svg className="size-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <div className="p-6">
              <p className="text-muted mb-4">
                User invitations are managed through the employee onboarding flow. Create an employee profile first, then they&apos;ll receive login credentials.
              </p>
              <div className="flex justify-end gap-3">
                <button onClick={() => setShowInviteModal(false)} className="btn-secondary">
                  Close
                </button>
                <a href="/employees" className="btn-primary">
                  Go to Employees
                </a>
              </div>
            </div>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { toggleWorkflow, createWorkflow } from "@/lib/actions/admin";
import type { Workflow } from "@/lib/actions/admin";

function formatDate(iso: string | null) {
  if (!iso) return "Never run";
  return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit" });
}

export function WorkflowsClient({ workflows }: Readonly<{ workflows: Workflow[] }>) {
  const { toast, setToast } = useToast();
  const router = useRouter();
  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState({ name: "", description: "", trigger: "" });

  async function handleToggle(id: string) {
    try {
      await toggleWorkflow(id);
      router.refresh();
    } catch {
      setToast("Failed to toggle workflow.");
    }
  }

  async function handleCreate(e: React.FormEvent) {
    e.preventDefault();
    try {
      await createWorkflow({ name: form.name, description: form.description, trigger: form.trigger });
      setShowModal(false);
      setForm({ name: "", description: "", trigger: "" });
      setToast("Workflow created!");
      router.refresh();
    } catch {
      setToast("Failed to create workflow.");
    }
  }

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Workflows</h1>
          <p className="mt-0.5 text-muted">Automate HR processes and notifications</p>
        </div>
        <button
          onClick={() => setShowModal(true)}
          className="btn-primary flex items-center gap-2"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          New Workflow
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        {[
          { label: "Total Workflows", value: workflows.length, color: "text-dark dark:text-white" },
          { label: "Active", value: workflows.filter((w) => w.isEnabled).length, color: "text-emerald-dark dark:text-emerald" },
          { label: "Total Runs", value: workflows.reduce((a, w) => a + w.runsCount, 0), color: "text-primary-600 dark:text-primary-300" },
          { label: "Disabled", value: workflows.filter((w) => !w.isEnabled).length, color: "text-rose-dark dark:text-rose" },
        ].map((stat) => (
          <div key={stat.label} className="stat-card">
            <p className="stat-label">{stat.label}</p>
            <p className={`stat-value ${stat.color}`}>{stat.value}</p>
          </div>
        ))}
      </div>

      {/* Workflows List */}
      {workflows.length === 0 ? (
        <div className="card p-10 text-center">
          <p className="empty-state-text mb-3">No workflows yet.</p>
          <button
            onClick={() => setShowModal(true)}
            className="btn-primary"
          >
            Create First Workflow
          </button>
        </div>
      ) : (
        <div className="space-y-3">
          {workflows.map((wf) => (
            <div key={wf.id} className="card-p">
              <div className="flex items-start justify-between gap-4">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <h3 className="section-title">{wf.name}</h3>
                    <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${wf.isEnabled ? "bg-emerald-light text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald" : "bg-gray-100 text-gray-500 dark:bg-dark-3 dark:text-dark-6"}`}>
                      {wf.isEnabled ? "Active" : "Disabled"}
                    </span>
                  </div>
                  {wf.description && (
                    <p className="mt-1 empty-state-text">{wf.description}</p>
                  )}
                  <div className="mt-2 flex flex-wrap gap-3 text-muted">
                    <span>Trigger: <strong className="text-dark dark:text-white">{wf.trigger}</strong></span>
                    <span>Runs: <strong className="text-dark dark:text-white">{wf.runsCount}</strong></span>
                    <span>Last run: <strong className="text-dark dark:text-white">{formatDate(wf.lastRunAt)}</strong></span>
                  </div>
                </div>
                <button
                  onClick={() => handleToggle(wf.id)}
                  className={`shrink-0 rounded-lg px-3 py-1.5 text-xs font-semibold transition-colors ${
                    wf.isEnabled
                      ? "bg-rose-light text-rose-dark hover:bg-rose-dark hover:text-white"
                      : "bg-emerald-light text-emerald-dark hover:bg-emerald-dark hover:text-white"
                  }`}
                >
                  {wf.isEnabled ? "Disable" : "Enable"}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Create Modal */}
      {showModal && (
        <div className="modal-overlay">
          <div className="modal-panel w-full max-w-lg">
            <div className="modal-header">
              <h2 className="text-lg font-bold text-dark dark:text-white">New Workflow</h2>
              <button onClick={() => setShowModal(false)} className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
                <svg className="size-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <form onSubmit={handleCreate} className="space-y-4 p-6">
              <div>
                <label className="label-field">Name <span className="text-rose-500">*</span></label>
                <input
                  required
                  type="text"
                  placeholder="e.g. Leave Approval Flow"
                  value={form.name}
                  onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
                  className="input-field w-full"
                />
              </div>
              <div>
                <label className="label-field">Description</label>
                <textarea
                  rows={2}
                  value={form.description}
                  onChange={(e) => setForm((p) => ({ ...p, description: e.target.value }))}
                  className="input-field w-full resize-none"
                />
              </div>
              <div>
                <label className="label-field">Trigger <span className="text-rose-500">*</span></label>
                <input
                  required
                  type="text"
                  placeholder="e.g. Leave request submitted"
                  value={form.trigger}
                  onChange={(e) => setForm((p) => ({ ...p, trigger: e.target.value }))}
                  className="input-field w-full"
                />
              </div>
              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)} className="btn-secondary">
                  Cancel
                </button>
                <button type="submit" className="btn-primary">
                  Create
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import { AI_GRADIENT, AI_ICON_PATH, SUGGESTIONS } from "../_data/ai-data";
import { MessageContent } from "./ai-message-content";

type Message = {
  id: string;
  role: "user" | "assistant";
  content: string;
};

interface Props {
  context: string;
  userName: string;
}

export function AIChat({ context, userName }: Props) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [isStreaming, setIsStreaming] = useState(false);
  const [showWelcome, setShowWelcome] = useState(true);
  const [activeConv, setActiveConv] = useState(-1);
  const bottomRef = useRef<HTMLDivElement>(null);
  const abortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const send = useCallback(async (text?: string) => {
    const msg = (text ?? input).trim();
    if (!msg || isStreaming) return;

    setShowWelcome(false);
    setInput("");

    const userMsg: Message = { id: crypto.randomUUID(), role: "user", content: msg };
    const aiMsg: Message = { id: crypto.randomUUID(), role: "assistant", content: "" };

    setMessages((prev) => [...prev, userMsg, aiMsg]);
    setIsStreaming(true);

    const history = [...messages, userMsg].map((m) => ({
      role: m.role,
      content: m.content,
    }));

    abortRef.current = new AbortController();

    try {
      const res = await fetch("/api/ai/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ messages: history, context }),
        signal: abortRef.current.signal,
      });

      if (!res.ok || !res.body) throw new Error("Request failed");

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let accumulated = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        accumulated += decoder.decode(value, { stream: true });
        const snapshot = accumulated;
        setMessages((prev) =>
          prev.map((m) => (m.id === aiMsg.id ? { ...m, content: snapshot } : m))
        );
      }
    } catch (err) {
      if ((err as Error).name !== "AbortError") {
        setMessages((prev) =>
          prev.map((m) =>
            m.id === aiMsg.id
              ? { ...m, content: "Sorry, I ran into an error. Please try again." }
              : m
          )
        );
      }
    } finally {
      setIsStreaming(false);
    }
  }, [input, isStreaming, messages, context]);

  function startNew() {
    abortRef.current?.abort();
    setMessages([]);
    setShowWelcome(true);
    setActiveConv(-1);
    setIsStreaming(false);
  }

  return (
    <div className="flex h-[calc(100vh-160px)] overflow-hidden rounded-xl shadow-card">
      {/* Sidebar */}
      <div className="w-60 shrink-0 border-r border-gray-3 bg-white dark:border-dark-3 dark:bg-dark-2 flex flex-col">
        <div className="p-4 border-b border-gray-3 dark:border-dark-3">
          <div className="flex items-center gap-2 mb-3">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg text-white" style={{ background: AI_GRADIENT }}>
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={AI_ICON_PATH} />
              </svg>
            </div>
            <span className="text-sm font-semibold text-dark dark:text-white">AI Assistant</span>
          </div>
          <button onClick={startNew} className="w-full rounded-lg bg-primary-600 px-3 py-2 text-sm font-semibold text-white hover:bg-primary-700">
            + New Conversation
          </button>
        </div>
        <div className="flex-1 overflow-y-auto p-2">
          <p className="px-2 py-1 text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Recent</p>
          <p className="px-3 py-2 text-xs text-dark-5 dark:text-dark-6">No recent conversations.</p>
        </div>
      </div>

      {/* Main Chat */}
      <div className="flex flex-1 flex-col bg-gray-1 dark:bg-[#111827] overflow-hidden">
        {/* Header */}
        <div className="border-b border-gray-3 dark:border-dark-3 bg-white dark:bg-dark-2 px-5 py-3.5 flex items-center gap-3 shrink-0">
          <div className="flex h-9 w-9 items-center justify-center rounded-xl text-white shrink-0" style={{ background: AI_GRADIENT }}>
            <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={AI_ICON_PATH} />
            </svg>
          </div>
          <div>
            <p className="text-sm font-semibold text-dark dark:text-white">Monja AI</p>
            <p className="text-xs text-dark-5 dark:text-dark-6">Powered by Claude · Always learning</p>
          </div>
          <div className="ml-auto flex items-center gap-1.5">
            <span className="h-2 w-2 rounded-full bg-emerald-500" />
            <span className="text-xs text-emerald-500">Online</span>
          </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-5 space-y-4">
          {showWelcome && (
            <div className="flex flex-col items-center justify-center h-full py-10">
              <div className="flex h-16 w-16 items-center justify-center rounded-2xl text-white mb-4" style={{ background: AI_GRADIENT }}>
                <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={AI_ICON_PATH} />
                </svg>
              </div>
              <h2 className="text-xl font-bold text-dark dark:text-white mb-1">Hello, {userName}!</h2>
              <p className="text-sm text-dark-5 dark:text-dark-6 mb-8">What can I help you with today?</p>
              <div className="grid grid-cols-2 gap-3 w-full max-w-lg">
                {SUGGESTIONS.map((s) => (
                  <button key={s.label} onClick={() => send(s.label)} className="rounded-xl bg-white dark:bg-dark-2 p-4 text-left border border-gray-3 dark:border-dark-3 hover:border-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/10 transition-all">
                    <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary-50 dark:bg-primary-900/20 mb-2">
                      <svg className="h-4 w-4 text-primary-600 dark:text-primary-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={s.icon} />
                      </svg>
                    </div>
                    <p className="text-xs font-medium text-dark dark:text-white">{s.label}</p>
                  </button>
                ))}
              </div>
            </div>
          )}

          {!showWelcome && messages.map((msg) => (
            <div key={msg.id} className={`flex gap-3 ${msg.role === "user" ? "flex-row-reverse" : "flex-row"}`}>
              {msg.role === "assistant" && (
                <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-xl text-white mt-0.5" style={{ background: AI_GRADIENT }}>
                  <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={AI_ICON_PATH} />
                  </svg>
                </div>
              )}
              <div className={`max-w-[72%] rounded-xl px-4 py-3 ${
                msg.role === "user"
                  ? "bg-primary-600 text-white rounded-tr-sm"
                  : "bg-white dark:bg-dark-2 border-l-4 border-primary-500 rounded-tl-sm shadow-sm"
              }`}>
                {msg.role === "user" ? (
                  <p className="text-sm text-white">{msg.content}</p>
                ) : msg.content ? (
                  <div className="text-dark dark:text-white">
                    <MessageContent content={msg.content} />
                  </div>
                ) : (
                  <div className="flex items-center gap-1 py-1">
                    <span className="h-2 w-2 rounded-full bg-primary-400 animate-bounce" style={{ animationDelay: "0ms" }} />
                    <span className="h-2 w-2 rounded-full bg-primary-400 animate-bounce" style={{ animationDelay: "150ms" }} />
                    <span className="h-2 w-2 rounded-full bg-primary-400 animate-bounce" style={{ animationDelay: "300ms" }} />
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={bottomRef} />
        </div>

        {/* Input */}
        <div className="border-t border-gray-3 dark:border-dark-3 bg-white dark:bg-dark-2 p-4 shrink-0">
          <div className="flex items-end gap-2 rounded-xl border border-gray-3 dark:border-dark-3 bg-gray-1 dark:bg-dark-3 px-3 py-2">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); } }}
              placeholder="Ask anything about HR, payroll, attendance, policies…"
              rows={1}
              disabled={isStreaming}
              className="flex-1 resize-none bg-transparent text-sm text-dark dark:text-white placeholder-dark-5 dark:placeholder-dark-6 outline-none disabled:opacity-60"
            />
            <button
              onClick={() => send()}
              disabled={!input.trim() || isStreaming}
              className="rounded-lg bg-primary-600 p-1.5 text-white hover:bg-primary-700 disabled:opacity-40 shrink-0"
            >
              {isStreaming ? (
                <svg className="h-5 w-5 animate-spin" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
                </svg>
              ) : (
                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
