                <path
                  d="M13.19 8.688a4.5 4.5 0 011.242 7.244l-4.5 4.5a4.5 4.5 0 01-6.364-6.364l1.757-1.757m13.35-.622l1.757-1.757a4.5 4.5 0 00-6.364-6.364l-4.5 4.5a4.5 4.5 0 001.242 7.244"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
            <button
              onClick={() => setToast("File attachment coming soon!")}
              className="flex size-7 items-center justify-center rounded text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
            >
              <svg className="size-4" viewBox="0 0 24 24" fill="none">
                <path
                  d="M18.375 12.739l-7.693 7.693a4.5 4.5 0 01-6.364-6.364l10.94-10.94A3 3 0 1119.5 7.372L8.552 18.32m.009-.01l-.01.01m5.699-9.941l-7.81 7.81a1.5 1.5 0 002.112 2.13"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
          </div>

          {/* Input row */}
          <div className="flex items-center gap-3 px-3 py-2.5">
            <Image
              src="/images/user/user-01.png"
              alt="You"
              width={28}
              height={28}
              className="size-7 flex-shrink-0 rounded-full"
            />
            <input
              type="text"
              placeholder={`Message #${channel.name}`}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && input.trim()) {
                  setInput("");
                }
              }}
              className="flex-1 bg-transparent text-sm text-dark outline-none placeholder-dark-5 dark:text-white dark:placeholder-dark-6"
            />
            <div className="relative flex items-center gap-1">
              {/* Emoji picker */}
              <button
                onClick={() => setShowEmoji((v) => !v)}
                className="flex size-7 items-center justify-center rounded text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
              >
                <svg className="size-4" viewBox="0 0 24 24" fill="none">
                  <path
                    d="M15.182 15.182a4.5 4.5 0 01-6.364 0M21 12a9 9 0 11-18 0 9 9 0 0118 0zM9.75 9.75c0 .414-.168.75-.375.75S9 10.164 9 9.75 9.168 9 9.375 9s.375.336.375.75zm-.375 0h.008v.015h-.008V9.75zm5.625 0c0 .414-.168.75-.375.75s-.375-.336-.375-.75.168-.75.375-.75.375.336.375.75zm-.375 0h.008v.015h-.008V9.75z"
                    stroke="currentColor"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </button>
              {showEmoji && (
                <div className="absolute bottom-9 right-0 z-10 flex flex-wrap gap-1 rounded-xl border border-gray-3 bg-white p-2 shadow-lg dark:border-dark-3 dark:bg-dark-2" style={{ width: "192px" }}>
                  {emojis.map((emoji) => (
                    <button
                      key={emoji}
                      onClick={() => {
                        setInput((prev) => prev + emoji);
                        setShowEmoji(false);
                      }}
                      className="flex size-8 items-center justify-center rounded text-lg hover:bg-gray-2 dark:hover:bg-dark-3"
                    >
                      {emoji}
                    </button>
                  ))}
                </div>
              )}
              <button
                onClick={() => setToast("File attachment coming soon!")}
                className="flex size-7 items-center justify-center rounded text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
              >
                <svg className="size-4" viewBox="0 0 24 24" fill="none">
                  <path
                    d="M18.375 12.739l-7.693 7.693a4.5 4.5 0 01-6.364-6.364l10.94-10.94A3 3 0 1119.5 7.372L8.552 18.32m.009-.01l-.01.01m5.699-9.941l-7.81 7.81a1.5 1.5 0 002.112 2.13"
                    stroke="currentColor"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </button>
              <button
                onClick={() => {
                  if (input.trim()) {
                    setInput("");
                  }
                }}
                className={`ml-1 flex size-8 items-center justify-center rounded-lg transition-colors ${
                  input.trim()
                    ? "bg-primary-600 text-white hover:bg-primary-700"
                    : "bg-gray-3 text-dark-5 dark:bg-dark-3 dark:text-dark-6"
                }`}
              >
                <svg className="size-4" viewBox="0 0 24 24" fill="none">
                  <path
                    d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5"
                    stroke="currentColor"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </button>
            </div>
          </div>
        </div>
      </div>

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState } from "react";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import Link from "next/link";
import { sendMessage, createChannel } from "@/lib/actions/collaboration";
import { useRouter } from "next/navigation";
import { NewMessageModal } from "./new-message-modal";
import { CreateChannelModal } from "./create-channel-modal";
import { StartMeetingModal } from "./start-meeting-modal";

type Channel = {
  id: string;
  name: string;
  isPrivate: boolean;
  messageCount: number;
  lastMessage: string | null;
  lastMessageAt: Date | string | null;
};

type Stats = { channelCount: number; messagesToday: number };

function formatTime(date: Date | string | null) {
  if (!date) return "";
  const d = new Date(date);
  const diff = Date.now() - d.getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "Just now";
  if (mins < 60) return `${mins}m`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h`;
  return `${Math.floor(hrs / 24)}d`;
}

export function CollaborationPageClient({ channels, stats }: Readonly<{ channels: Channel[]; stats: Stats }>) {
  const { toast, setToast } = useToast();
  const router = useRouter();
  const [showNewMessageModal, setShowNewMessageModal] = useState(false);
  const [showMeetingModal, setShowMeetingModal] = useState(false);
  const [showChannelModal, setShowChannelModal] = useState(false);

  async function handleSendMessage(channelId: string, body: string) {
    try {
      await sendMessage({ channelId, content: body });
      setShowNewMessageModal(false);
      setToast("Message sent!");
      router.refresh();
    } catch {
      setToast("Failed to send message.");
    }
  }

  async function handleCreateChannel(name: string) {
    try {
      await createChannel(name);
      setShowChannelModal(false);
      setToast("Channel created!");
      router.refresh();
    } catch {
      setToast("Failed to create channel.");
    }
  }

  const card = "rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3";

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <nav className="mb-1 flex items-center gap-1.5 text-sm text-dark-5 dark:text-dark-6">
            <Link href="/dashboard" className="hover:text-primary-600">Dashboard</Link>
            <span>/</span>
            <span className="text-dark dark:text-white">Collaboration</span>
          </nav>
          <h1 className="text-2xl font-bold text-dark dark:text-white">Collaboration</h1>
          <p className="mt-0.5 text-sm text-dark-5 dark:text-dark-6">Stay connected with your team</p>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setShowNewMessageModal(true)} className="rounded-lg border border-gray-3 bg-white px-4 py-2 text-sm font-medium text-dark hover:bg-gray-2 dark:border-dark-3 dark:bg-dark-2 dark:text-white">
            New Message
          </button>
          <button onClick={() => setShowMeetingModal(true)} className="rounded-lg bg-primary-600 px-4 py-2 text-sm font-semibold text-white hover:bg-primary-700">
            Start Meeting
          </button>
        </div>
      </div>

      {/* KPI Row */}
      <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
        <div className={card}>
          <p className="text-sm font-medium text-dark-5 dark:text-dark-6">Active Channels</p>
          <p className="mt-2 text-3xl font-bold text-dark dark:text-white">{stats.channelCount}</p>
          <p className="mt-1 text-xs text-dark-5 dark:text-dark-6">team channels</p>
        </div>
        <div className={card}>
          <p className="text-sm font-medium text-dark-5 dark:text-dark-6">Messages Today</p>
          <p className="mt-2 text-3xl font-bold text-dark dark:text-white">{stats.messagesToday}</p>
          <p className="mt-1 text-xs text-dark-5 dark:text-dark-6">across all channels</p>
        </div>
        <div className={card}>
          <p className="text-sm font-medium text-dark-5 dark:text-dark-6">Total Messages</p>
          <p className="mt-2 text-3xl font-bold text-dark dark:text-white">{channels.reduce((a, c) => a + c.messageCount, 0)}</p>
          <p className="mt-1 text-xs text-dark-5 dark:text-dark-6">all time</p>
        </div>
        <div className={card}>
          <p className="text-sm font-medium text-dark-5 dark:text-dark-6">Meetings Today</p>
          <p className="mt-2 text-3xl font-bold text-dark dark:text-white">—</p>
          <p className="mt-1 text-xs text-dark-5 dark:text-dark-6">
            <Link href="/collaboration/meetings" className="text-primary-600 hover:underline">Schedule one →</Link>
          </p>
        </div>
      </div>

      {/* Channels List */}
      <div className={card}>
        <div className="flex items-center justify-between pb-4">
          <h2 className="text-base font-semibold text-dark dark:text-white">Channels ({channels.length})</h2>
          <button onClick={() => setShowChannelModal(true)} className="text-sm font-medium text-primary-600 hover:underline">
            + New Channel
          </button>
        </div>

        {channels.length === 0 ? (
          <div className="text-center py-6">
            <p className="text-sm text-dark-5 dark:text-dark-6 mb-3">No channels yet.</p>
            <button onClick={() => setShowChannelModal(true)} className="rounded-lg bg-primary-600 px-4 py-2 text-sm font-semibold text-white hover:bg-primary-700">
              Create First Channel
            </button>
          </div>
        ) : (
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {channels.map((ch) => (
              <div key={ch.id}
                className="rounded-lg border border-gray-2 p-3 dark:border-dark-3 hover:bg-gray-1 dark:hover:bg-dark-3/40 transition-colors cursor-pointer"
                onClick={() => setShowNewMessageModal(true)}
              >
                <div className="flex items-center gap-2 mb-1">
                  <span className="flex h-7 w-7 items-center justify-center rounded-md bg-gray-100 text-xs font-bold text-dark-5 dark:bg-dark-3 dark:text-dark-6">#</span>
                  <p className="text-sm font-semibold text-dark dark:text-white">#{ch.name}</p>
                  {ch.isPrivate && (
                    <span className="ml-auto rounded-full bg-amber-light px-1.5 py-0.5 text-[10px] font-medium text-amber-dark">Private</span>
                  )}
                </div>
                {ch.lastMessage && (
                  <p className="text-xs text-dark-5 dark:text-dark-6 truncate">{ch.lastMessage}</p>
                )}
                <div className="mt-1.5 flex items-center justify-between">
                  <span className="text-[10px] text-dark-5 dark:text-dark-6">{ch.messageCount} messages</span>
                  {ch.lastMessageAt && (
                    <span className="text-[10px] text-dark-5 dark:text-dark-6">{formatTime(ch.lastMessageAt)}</span>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}

        <div className="pt-4 border-t border-gray-2 dark:border-dark-3 mt-4">
          <Link href="/collaboration/messages" className="text-sm font-medium text-primary-600 hover:underline">
            Open Messages →
          </Link>
        </div>
      </div>

      {showNewMessageModal && (
        <NewMessageModal
          channels={channels}
          onSend={handleSendMessage}
          onClose={() => setShowNewMessageModal(false)}
        />
      )}

      {showChannelModal && (
        <CreateChannelModal
          onCreate={handleCreateChannel}
          onClose={() => setShowChannelModal(false)}
        />
      )}

      {showMeetingModal && (
        <StartMeetingModal
          onStart={() => { setShowMeetingModal(false); setToast("Meeting started! Share the link with your team."); }}
          onClose={() => setShowMeetingModal(false)}
        />
      )}

      <Toast message={toast} />
    </div>
  );
}

import Image from "next/image";
import type { Message } from "./collaboration-data";

interface MessageItemProps {
  message: Message;
}

export function MessageItem({ message }: MessageItemProps) {
  return (
    <div className="group flex gap-3 rounded-lg px-2 py-2 transition-colors hover:bg-gray-1 dark:hover:bg-dark-3/40">
      <Image
        src={message.avatar}
        alt={message.author}
        width={36}
        height={36}
        className="mt-0.5 size-9 flex-shrink-0 rounded-full"
      />
      <div className="min-w-0 flex-1">
        <div className="flex items-baseline gap-2">
          <span className="text-sm font-semibold text-dark dark:text-white">
            {message.author}
          </span>
          <span className="text-xs text-dark-5 dark:text-dark-6">
            {message.timestamp}
          </span>
        </div>
        <p className="mt-0.5 text-sm leading-relaxed text-dark-4 dark:text-dark-7">
          {message.text}
        </p>

        {/* File attachment */}
        {message.attachment && (
          <div className="mt-2 inline-flex items-center gap-3 rounded-lg border border-gray-3 bg-gray-1 px-3 py-2.5 dark:border-dark-3 dark:bg-dark-3">
            <div className="flex size-9 flex-shrink-0 items-center justify-center rounded-lg bg-rose-light dark:bg-rose-dark/20">
              <svg
                className="size-5 text-rose-dark"
                viewBox="0 0 24 24"
                fill="none"
              >
                <path
                  d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m2.25 0H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </div>
            <div>
              <p className="text-sm font-medium text-dark dark:text-white">
                {message.attachment.name}
              </p>
              <p className="text-xs text-dark-5 dark:text-dark-6">
                {message.attachment.type} · {message.attachment.size}
              </p>
            </div>
            <button className="ml-2 flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-3 dark:text-dark-6 dark:hover:bg-dark-2">
              <svg className="size-4" viewBox="0 0 24 24" fill="none">
                <path
                  d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5M16.5 12L12 16.5m0 0L7.5 12m4.5 4.5V3"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
          </div>
        )}

        {/* Reactions */}
        {message.reactions && message.reactions.length > 0 && (
          <div className="mt-2 flex flex-wrap gap-1.5">
            {message.reactions.map((r, i) => (
              <button
                key={i}
                className="flex items-center gap-1 rounded-full border border-gray-3 bg-gray-1 px-2 py-0.5 text-xs hover:bg-gray-2 dark:border-dark-3 dark:bg-dark-3 dark:hover:bg-dark-2"
              >
                <span>{r.emoji}</span>
                <span className="font-medium text-dark-5 dark:text-dark-6">
                  {r.count}
                </span>
              </button>
            ))}
            <button className="flex size-6 items-center justify-center rounded-full border border-gray-3 bg-gray-1 text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:bg-dark-3 dark:hover:bg-dark-2">
              <span className="text-xs">+</span>
            </button>
          </div>
        )}

        {/* Thread count */}
        {message.threadCount && message.threadCount > 0 && (
          <button className="mt-1.5 flex items-center gap-1.5 text-xs font-medium text-primary-600 hover:underline dark:text-primary-300">
            <svg className="size-3.5" viewBox="0 0 24 24" fill="none">
              <path
                d="M20.25 8.511c.884.284 1.5 1.128 1.5 2.097v4.286c0 1.136-.847 2.1-1.98 2.193-.34.027-.68.052-1.02.072v3.091l-3-3c-1.354 0-2.694-.055-4.02-.163a2.115 2.115 0 01-.825-.242m9.345-8.334a2.126 2.126 0 00-.476-.095 48.64 48.64 0 00-8.048 0c-1.131.094-1.976 1.057-1.976 2.192v4.286c0 .837.46 1.58 1.155 1.951m9.345-8.334V6.637c0-1.621-1.152-3.026-2.76-3.235A48.455 48.455 0 0011.25 3c-2.115 0-4.198.137-6.24.402-1.608.209-2.76 1.614-2.76 3.235v6.226c0 1.621 1.152 3.026 2.76 3.235.577.075 1.157.14 1.74.194V21l4.155-4.155"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
            {message.threadCount} replies
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";

type Channel = { id: string; name: string };

interface Props {
  channels: Channel[];
  onSend: (channelId: string, body: string) => Promise<void>;
  onClose: () => void;
}

export function NewMessageModal({ channels, onSend, onClose }: Readonly<Props>) {
  const [selectedChannelId, setSelectedChannelId] = useState<string>("");
  const [msgBody, setMsgBody] = useState("");

  async function handleSend() {
    if (!selectedChannelId || !msgBody.trim()) return;
    await onSend(selectedChannelId, msgBody.trim());
    setSelectedChannelId("");
    setMsgBody("");
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-modal dark:bg-dark-2">
        <h2 className="mb-4 text-lg font-bold text-dark dark:text-white">New Message</h2>
        <div className="space-y-4">
          <div>
            <label className="mb-1.5 block text-sm font-medium text-dark dark:text-white">Channel</label>
            <select
              value={selectedChannelId}
              onChange={(e) => setSelectedChannelId(e.target.value)}
              className="w-full rounded-lg border border-gray-3 bg-gray-2 px-3 py-2 text-sm outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white"
            >
              <option value="">Select a channel...</option>
              {channels.map((ch) => (
                <option key={ch.id} value={ch.id}>#{ch.name}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="mb-1.5 block text-sm font-medium text-dark dark:text-white">Message</label>
            <textarea
              rows={3}
              value={msgBody}
              onChange={(e) => setMsgBody(e.target.value)}
              className="w-full rounded-lg border border-gray-3 bg-gray-2 px-3 py-2 text-sm outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white dark:placeholder-dark-6 resize-none"
            />
          </div>
        </div>
        <div className="mt-5 flex gap-3">
          <button onClick={onClose} className="flex-1 rounded-xl border border-gray-3 px-4 py-2.5 text-sm font-semibold text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6 dark:hover:bg-dark-3">
            Cancel
          </button>
          <button
            onClick={handleSend}
            disabled={!selectedChannelId || !msgBody.trim()}
            className="flex-1 rounded-xl bg-primary-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary-700 disabled:opacity-50"
          >
            Send
          </button>
        </div>
      </div>
    </div>
  );
}

import Image from "next/image";
import type { SerializedMeeting } from "@/lib/actions/meetings";

const TYPE_COLORS: Record<string, string> = {
  "All-Hands": "bg-primary-50 text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
  "Team": "bg-violet-light text-violet-dark dark:bg-violet-dark/20 dark:text-violet-300",
  "1:1": "bg-emerald-light text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
