}

interface Props {
  meeting: SerializedMeeting;
  dateLabel: string;
  timeLabel: string;
  durationLabel: string;
  onJoin: () => void;
  onDetails: () => void;
}

export function MeetingCard({ meeting, dateLabel, timeLabel, durationLabel, onJoin, onDetails }: Readonly<Props>) {
