          </div>
          {overflow > 0 && <span className="ml-1 text-muted">+{overflow}</span>}
          {meeting.participants.length === 0 && <span className="text-muted text-xs">No participants</span>}
        </div>
        <span className="rounded bg-gray-100 px-1.5 py-0.5 text-xs font-semibold text-dark-5 dark:bg-dark-3 dark:text-dark-6">
          {meeting.platform}
        </span>
      </div>

      {meeting.agenda && (
        <p className="mb-3 truncate text-xs text-dark-5 dark:text-dark-6">{meeting.agenda}</p>
      )}

      <div className="flex gap-2">
        <button
          onClick={onJoin}
          className={`flex-1 rounded-lg px-3 py-1.5 text-sm font-semibold transition-colors ${meeting.isLive ? "bg-emerald-dark text-white hover:opacity-90" : "bg-primary-600 text-white hover:bg-primary-700"}`}
        >
          {meeting.isLive ? "Join Now" : "Join"}
        </button>
        <button onClick={onDetails} className="btn-secondary px-3 py-1.5 text-sm">Details</button>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { MeetingCard } from "./meeting-card";
import { ScheduleMeetingModal } from "./schedule-meeting-modal";
import type { SerializedMeeting, MeetingEmployee } from "@/lib/actions/meetings";

type TabKey = "upcoming" | "live" | "past";
const TAB_KEYS: TabKey[] = ["upcoming", "live", "past"];

interface Props {
  meetings: SerializedMeeting[];
  employees: MeetingEmployee[];
}

export function MeetingsPageClient({ meetings, employees }: Readonly<Props>) {
  const router = useRouter();
  const [tab, setTab] = useState<TabKey>("upcoming");
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const { toast, setToast } = useToast();

  const liveMeetings = meetings.filter((m) => m.isLive);
  const upcomingMeetings = meetings.filter((m) => !m.isLive && !m.isPast);
  const pastMeetings = meetings.filter((m) => m.isPast);

  const displayMeetings =
    tab === "upcoming" ? upcomingMeetings :
    tab === "live" ? liveMeetings :
    pastMeetings;

  const TAB_META: Record<TabKey, { label: string; count: number }> = {
    upcoming: { label: "Upcoming", count: upcomingMeetings.length },
    live: { label: "Live", count: liveMeetings.length },
    past: { label: "Past", count: pastMeetings.length },
  };

  function formatScheduledAt(iso: string) {
    const d = new Date(iso);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const meetingDay = new Date(d);
    meetingDay.setHours(0, 0, 0, 0);

    let dateLabel: string;
    if (meetingDay.getTime() === today.getTime()) dateLabel = "Today";
    else if (meetingDay.getTime() === tomorrow.getTime()) dateLabel = "Tomorrow";
    else dateLabel = d.toLocaleDateString("en-US", { month: "short", day: "numeric" });

    const timeLabel = d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
    return { dateLabel, timeLabel };
  }

  function durationLabel(mins: number) {
    if (mins < 60) return `${mins}m`;
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return m > 0 ? `${h}h ${m}m` : `${h}h`;
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <h1 className="page-title">Meetings</h1>
          <p className="text-muted">Schedule, join, and manage your meetings</p>
        </div>
        <button onClick={() => setShowScheduleModal(true)} className="btn-primary">+ Schedule Meeting</button>
      </div>

      {liveMeetings.length > 0 && (
        <div className="overflow-hidden rounded-xl bg-gradient-success p-4 text-white shadow-card">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-2">
              <span className="flex size-7 items-center justify-center rounded-full bg-white/20">
                <span className="size-2.5 animate-pulse rounded-full bg-white" />
              </span>
              <div>
                <p className="text-sm font-semibold">{liveMeetings.length} meeting{liveMeetings.length !== 1 ? "s" : ""} in progress</p>
                <p className="text-xs text-white/80">{liveMeetings.map((m) => m.title).join(" · ")}</p>
              </div>
            </div>
            <div className="flex gap-2">
              {liveMeetings.map((m) => (
                <button
                  key={m.id}
                  onClick={() => {
                    if (m.meetingUrl) {
                      window.open(m.meetingUrl, "_blank", "noopener,noreferrer");
                    } else {
                      setToast("No meeting link available — ask the organizer to add one");
                    }
                  }}
                  className="rounded-lg bg-white/20 px-3 py-1.5 text-sm font-semibold text-white hover:bg-white/30"
                >
                  Join {m.title.split(" ")[0]}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      <div className="flex gap-1 rounded-xl bg-white p-1 shadow-card dark:bg-dark-2">
        {TAB_KEYS.map((key) => {
          const { label, count } = TAB_META[key];
          return (
            <button
              key={key}
              onClick={() => setTab(key)}
              className={`flex flex-1 items-center justify-center gap-2 rounded-lg px-4 py-2 text-sm font-medium transition-colors ${tab === key ? "bg-primary-600 text-white shadow-sm" : "text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"}`}
            >
              {label}
              {key === "live" && count > 0 && (
                <span className={`rounded-full px-1.5 py-0.5 text-xs font-bold ${tab === key ? "bg-white/20 text-white" : "bg-emerald-dark text-white"}`}>{count}</span>
              )}
            </button>
          );
        })}
      </div>

      {displayMeetings.length === 0 ? (
        <div className="card-p p-10 text-center">
          <p className="text-muted">No {tab} meetings.</p>
          {tab === "upcoming" && (
            <button onClick={() => setShowScheduleModal(true)} className="mt-3 btn-primary">Schedule a Meeting</button>
          )}
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {displayMeetings.map((meeting) => {
            const { dateLabel, timeLabel } = formatScheduledAt(meeting.scheduledAt);
            return (
              <MeetingCard
                key={meeting.id}
                meeting={meeting}
                dateLabel={dateLabel}
                timeLabel={timeLabel}
                durationLabel={durationLabel(meeting.durationMins)}
                onJoin={() => {
                  if (meeting.meetingUrl) {
                    window.open(meeting.meetingUrl, "_blank", "noopener,noreferrer");
                  } else {
                    setToast("No meeting link — add one when scheduling");
                  }
                }}
                onDetails={() => setToast("Opening meeting details...")}
              />
            );
          })}
        </div>
      )}

      {showScheduleModal && (
        <ScheduleMeetingModal
          employees={employees}
          onClose={() => setShowScheduleModal(false)}
          onSchedule={() => {
            setShowScheduleModal(false);
            setToast("Meeting scheduled successfully!");
            router.refresh();
          }}
        />
      )}

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState, useTransition, useMemo } from "react";
import Image from "next/image";
import { createMeeting } from "@/lib/actions/meetings";
import type { MeetingEmployee } from "@/lib/actions/meetings";

const DURATION_OPTIONS = [
  { label: "15 min", value: 15 },
  { label: "30 min", value: 30 },
  { label: "45 min", value: 45 },
  { label: "1 hour", value: 60 },
  { label: "1.5 hours", value: 90 },
  { label: "2 hours", value: 120 },
];

const MEETING_TYPES = ["Team", "All-Hands", "1:1", "Interview", "Review"];
const PLATFORMS = ["Zoom", "Google Meet", "Microsoft Teams", "In-person"];

function getInitials(name: string) {
  return name.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 2);
}

interface Props {
  employees: MeetingEmployee[];
  onClose: () => void;
  onSchedule: () => void;
}

export function ScheduleMeetingModal({ employees, onClose, onSchedule }: Readonly<Props>) {
  const [title, setTitle] = useState("");
  const [type, setType] = useState("Team");
  const [date, setDate] = useState("");
  const [time, setTime] = useState("");
  const [durationMins, setDurationMins] = useState(30);
  const [platform, setPlatform] = useState("Zoom");
  const [meetingUrl, setMeetingUrl] = useState("");
  const [agenda, setAgenda] = useState("");
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");
  const [isPending, startTransition] = useTransition();

  const filteredEmployees = useMemo(
    () => employees.filter((e) =>
      e.name.toLowerCase().includes(search.toLowerCase()) ||
      (e.department?.toLowerCase().includes(search.toLowerCase()) ?? false)
    ),
    [employees, search]
  );

  function toggleEmployee(id: string) {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  function handleSubmit() {
    if (!title.trim()) { setError("Meeting title is required."); return; }
    if (!date) { setError("Please select a date."); return; }
    if (!time) { setError("Please select a time."); return; }
    if (selectedIds.size === 0) { setError("Add at least one participant."); return; }
    setError("");

    startTransition(async () => {
      try {
        await createMeeting({
          title: title.trim(),
          type,
          date,
          time,
          durationMins,
          platform,
          meetingUrl: meetingUrl.trim() || undefined,
          agenda: agenda.trim() || undefined,
          participantIds: Array.from(selectedIds),
        });
        onSchedule();
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to schedule meeting");
      }
    });
  }

  const selectedEmployees = employees.filter((e) => selectedIds.has(e.id));

  return (
    <div className="modal-overlay" onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="modal-panel w-full max-w-2xl p-6">
        <div className="mb-5 flex items-center justify-between">
          <h2 className="section-title">Schedule Meeting</h2>
          <button onClick={onClose} className="flex size-7 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
            <svg className="size-4" viewBox="0 0 24 24" fill="none">
              <path d="M6 18L18 6M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </button>
        </div>

        <div className="grid gap-6 md:grid-cols-2">
          {/* Left — Meeting details */}
          <div className="space-y-4">
            <div>
              <label className="label-field">Title <span className="text-rose-dark">*</span></label>
              <input type="text" placeholder="e.g. Team Sync, 1:1 with Sarah..." value={title} onChange={(e) => setTitle(e.target.value)} className="input-field" />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="label-field">Type</label>
                <select value={type} onChange={(e) => setType(e.target.value)} className="input-field">
                  {MEETING_TYPES.map((t) => <option key={t}>{t}</option>)}
                </select>
              </div>
              <div>
                <label className="label-field">Platform</label>
                <select value={platform} onChange={(e) => setPlatform(e.target.value)} className="input-field">
                  {PLATFORMS.map((p) => <option key={p}>{p}</option>)}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="label-field">Date <span className="text-rose-dark">*</span></label>
                <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="input-field" />
              </div>
              <div>
                <label className="label-field">Time <span className="text-rose-dark">*</span></label>
                <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="input-field" />
              </div>
            </div>

            <div>
              <label className="label-field">Duration</label>
              <select value={durationMins} onChange={(e) => setDurationMins(Number(e.target.value))} className="input-field">
                {DURATION_OPTIONS.map((d) => <option key={d.value} value={d.value}>{d.label}</option>)}
              </select>
            </div>

            <div>
              <label className="label-field">Meeting Link <span className="font-normal text-muted">(optional)</span></label>
              <input type="url" placeholder="https://zoom.us/j/..." value={meetingUrl} onChange={(e) => setMeetingUrl(e.target.value)} className="input-field" />
            </div>

            <div>
              <label className="label-field">Agenda <span className="font-normal text-muted">(optional)</span></label>
              <textarea rows={2} placeholder="What will be discussed?" value={agenda} onChange={(e) => setAgenda(e.target.value)} className="input-field resize-none" />
            </div>
          </div>

          {/* Right — Participants */}
          <div className="flex flex-col gap-3">
            <div>
              <label className="label-field">Participants <span className="text-rose-dark">*</span></label>
              <div className="relative">
                <svg className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-dark-5" viewBox="0 0 24 24" fill="none">
                  <path d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
                <input
                  type="text"
                  placeholder="Search employees..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="input-field pl-8"
                />
              </div>
            </div>

            <div className="h-52 overflow-y-auto rounded-lg border border-gray-3 dark:border-dark-3">
              {filteredEmployees.length === 0 ? (
                <p className="py-4 text-center text-xs text-dark-5 dark:text-dark-6">No employees found.</p>
              ) : (
                filteredEmployees.map((emp) => {
                  const isSelected = selectedIds.has(emp.id);
                  return (
                    <button
                      key={emp.id}
                      type="button"
                      onClick={() => toggleEmployee(emp.id)}
                      className={`flex w-full items-center gap-3 px-3 py-2 text-left transition-colors ${isSelected ? "bg-primary-50 dark:bg-primary-900/20" : "hover:bg-gray-1 dark:hover:bg-dark-3"}`}
                    >
                      {emp.avatarUrl ? (
                        <Image src={emp.avatarUrl} alt={emp.name} width={28} height={28} className="size-7 shrink-0 rounded-full object-cover" />
                      ) : (
                        <div className="flex size-7 shrink-0 items-center justify-center rounded-full bg-primary-100 text-xs font-bold text-primary-700 dark:bg-primary-900/30 dark:text-primary-300">
                          {getInitials(emp.name)}
                        </div>
                      )}
                      <div className="min-w-0 flex-1">
                        <p className={`truncate text-xs font-medium ${isSelected ? "text-primary-600 dark:text-primary-300" : "text-dark dark:text-white"}`}>{emp.name}</p>
                        <p className="truncate text-[11px] text-dark-5 dark:text-dark-6">{emp.title}{emp.department ? ` · ${emp.department}` : ""}</p>
                      </div>
                      {isSelected && (
                        <svg className="size-4 shrink-0 text-primary-600 dark:text-primary-300" viewBox="0 0 24 24" fill="none">
                          <path d="M4.5 12.75l6 6 9-13.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                        </svg>
                      )}
                    </button>
                  );
                })
              )}
            </div>

            {selectedEmployees.length > 0 && (
              <div>
                <p className="mb-1.5 text-xs font-medium text-dark-5 dark:text-dark-6">{selectedEmployees.length} selected</p>
                <div className="flex flex-wrap gap-1.5">
                  {selectedEmployees.map((e) => (
                    <span key={e.id} className="flex items-center gap-1 rounded-full bg-primary-50 px-2 py-0.5 text-xs font-medium text-primary-600 dark:bg-primary-900/20 dark:text-primary-300">
                      {e.name.split(" ")[0]}
                      <button type="button" onClick={() => toggleEmployee(e.id)} className="ml-0.5 text-primary-400 hover:text-primary-600">×</button>
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {error && <p className="mt-3 text-xs text-rose-600 dark:text-rose">{error}</p>}

        <div className="mt-5 flex justify-end gap-2">
          <button onClick={onClose} className="btn-secondary" disabled={isPending}>Cancel</button>
          <button onClick={handleSubmit} disabled={isPending} className="btn-primary disabled:opacity-60">
            {isPending ? "Scheduling…" : "Schedule Meeting"}
          </button>
        </div>
      </div>
    </div>
  );
}

