interface ComposerProps {
  inputRef: React.RefObject<HTMLInputElement | null>;
  placeholder: string;
  input: string;
  onInputChange: (v: string) => void;
  onKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => void;
  onEmoji: () => void;
  onAttach: () => void;
  onSend: () => void;
}

function Composer({
  inputRef,
  placeholder,
  input,
  onInputChange,
  onKeyDown,
  onEmoji,
  onAttach,
  onSend,
}: Readonly<ComposerProps>) {
  return (
    <div className="border-t border-gray-3 bg-white p-4 dark:border-dark-3 dark:bg-dark-2">
      <div className="overflow-hidden rounded-xl border border-gray-3 dark:border-dark-3">
        <div className="flex items-center gap-3 px-4 py-3">
          <input
            ref={inputRef}
            type="text"
            placeholder={placeholder}
            value={input}
            onChange={(e) => onInputChange(e.target.value)}
            onKeyDown={onKeyDown}
            className="flex-1 bg-transparent text-sm text-dark outline-none placeholder-dark-5 dark:text-white dark:placeholder-dark-6"
          />
          <div className="flex items-center gap-1">
            <button onClick={onEmoji} className="flex size-7 items-center justify-center rounded text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
              <svg className="size-4" viewBox="0 0 24 24" fill="none">
                <path d="M15.182 15.182a4.5 4.5 0 01-6.364 0M21 12a9 9 0 11-18 0 9 9 0 0118 0zM9.75 9.75c0 .414-.168.75-.375.75S9 10.164 9 9.75 9.168 9 9.375 9s.375.336.375.75zm-.375 0h.008v.015h-.008V9.75zm5.625 0c0 .414-.168.75-.375.75s-.375-.336-.375-.75.168-.75.375-.75.375.336.375.75zm-.375 0h.008v.015h-.008V9.75z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
            <button onClick={onAttach} className="flex size-7 items-center justify-center rounded text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
              <svg className="size-4" viewBox="0 0 24 24" fill="none">
                <path d="M18.375 12.739l-7.693 7.693a4.5 4.5 0 01-6.364-6.364l10.94-10.94A3 3 0 1119.5 7.372L8.552 18.32m.009-.01l-.01.01m5.699-9.941l-7.81 7.81a1.5 1.5 0 002.112 2.13" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
            <button
              onClick={onSend}
              disabled={!input.trim()}
              className={`ml-1 flex size-8 items-center justify-center rounded-lg transition-colors ${input.trim() ? "bg-primary-600 text-white hover:bg-primary-700" : "bg-gray-3 text-dark-5 dark:bg-dark-3 dark:text-dark-6"}`}
            >
              <svg className="size-4" viewBox="0 0 24 24" fill="none">
                <path d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function DmChatAreaContent({
  mode,
  channel,
  conversation,
  messages,
  senderPop,
  setSenderPop,
  bottomRef,
  inputRef,
  placeholder,
  input,
  onInputChange,
  onCall,
  onSearch,
  onEmoji,
  onAttach,
  onSend,
  onStartDm,
  onCallUser,
  onKeyDown,
}: Readonly<DmChatAreaContentProps>) {
  const headerName = mode === "dm" ? conversation?.otherUserName : channel?.name;
  const headerSub = getHeaderSub(mode, channel?.isPrivate);
  const headerAvatar = mode === "dm" ? conversation?.otherUserAvatar : null;

  return (
    <div className="flex flex-1 flex-col overflow-hidden">
      <ChatHeader
        mode={mode}
        headerName={headerName}
        headerSub={headerSub}
        headerAvatar={headerAvatar}
        onCall={onCall}
        onSearch={onSearch}
        onSearchFocus={() => inputRef.current?.focus()}
      />

      <MessagesPane
        mode={mode}
        messages={messages}
        channelName={channel?.name}
        conversationName={conversation?.otherUserName}
        senderPop={senderPop}
        setSenderPop={setSenderPop}
        onStartDm={onStartDm}
        onCallUser={onCallUser}
        bottomRef={bottomRef}
      />

      <Composer
        inputRef={inputRef}
        placeholder={placeholder}
        input={input}
        onInputChange={onInputChange}
        onKeyDown={onKeyDown}
        onEmoji={onEmoji}
        onAttach={onAttach}
        onSend={onSend}
      />
    </div>
  );
}


export function DmChatArea({
  mode,
  channel,
  conversation,
  messages,
  input,
  onInputChange,
  onSend,
  onCall,
  onSearch,
  onEmoji,
  onAttach,
  onStartDm,
  onCallUser,
}: Readonly<Props>) {
  const inputRef = useRef<HTMLInputElement>(null);
  const bottomRef = useRef<HTMLDivElement>(null);
  const [senderPop, setSenderPop] = useState<SenderPopup | null>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages.length]);

  const isEmpty = mode === "channel" ? !channel : !conversation;

  if (isEmpty) {
    return (
      <div className="flex flex-1 items-center justify-center bg-white dark:bg-dark-2">
        <p className="text-sm text-dark-5 dark:text-dark-6">Select a channel or conversation to start messaging.</p>
      </div>
    );
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      onSend();
    }
  }

  const placeholder = getComposerPlaceholder(mode, channel?.name, conversation?.otherUserName);

  return (
    <DmChatAreaContent
      mode={mode}
      channel={channel}
      conversation={conversation}
      messages={messages}
      senderPop={senderPop}
      setSenderPop={setSenderPop}
      bottomRef={bottomRef}
      inputRef={inputRef}
      placeholder={placeholder}
      input={input}
      onInputChange={onInputChange}
      onCall={onCall}
      onSearch={onSearch}
      onEmoji={onEmoji}
      onAttach={onAttach}
      onSend={onSend}
      onStartDm={onStartDm}
      onCallUser={onCallUser}
      onKeyDown={handleKeyDown}
    />
  );
}

import Image from "next/image";
import type { Dispatch, SetStateAction } from "react";
import type { ChannelMessage } from "@/lib/actions/messages";
import type { DmMessage } from "@/lib/actions/dm";

export type ReadReceipt = {
  userId: string;
  name: string;
  avatar: string | null;
  readAt: string;
};

export type AnyMessage = (ChannelMessage | DmMessage) & { readBy?: ReadReceipt[] };

export interface SenderPopup {
  msgId: string;
  userId: string;
  name: string;
}

interface MessageBubbleProps {
  msg: AnyMessage;
  mode: "channel" | "dm";
  senderPop: SenderPopup | null;
  setSenderPop: Dispatch<SetStateAction<SenderPopup | null>>;
  onStartDm?: (userId: string, name: string) => void;
  onCallUser?: (userId: string, name: string, type: "audio" | "video") => void;
}

function formatTime(iso: string) {
  return new Date(iso).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
}

function formatTimestamp(iso: string) {
  const d = new Date(iso);
  const now = new Date();
  const time = formatTime(iso);

  if (d.toDateString() === now.toDateString()) return time;

  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  if (d.toDateString() === yesterday.toDateString()) return `Yesterday, ${time}`;

  if (d.getFullYear() === now.getFullYear()) {
    return d.toLocaleDateString("en-US", { month: "short", day: "numeric" }) + `, ${time}`;
  }
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) + `, ${time}`;
}

function getInitials(name: string) {
  return name.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 2);
}

function ReadAvatars({ readBy }: Readonly<{ readBy?: ReadReceipt[] }>) {
  const receipts = (readBy ?? []).filter((receipt, index, list) => list.findIndex((item) => item.userId === receipt.userId) === index);
  if (receipts.length === 0) return null;

  return (
    <div className="mt-1 flex items-center -space-x-1.5">
      {receipts.slice(0, 3).map((receipt) => (
        receipt.avatar ? (
          <Image
            key={receipt.userId}
            src={receipt.avatar}
            alt={receipt.name}
            width={16}
            height={16}
            className="size-4 rounded-full border border-white object-cover dark:border-dark-2"
            title={receipt.name}
          />
        ) : (
          <div
            key={receipt.userId}
            className="flex size-4 items-center justify-center rounded-full border border-white bg-primary-100 text-[8px] font-bold text-primary-700 dark:border-dark-2 dark:bg-primary-900/40 dark:text-primary-300"
            title={receipt.name}
          >
            {getInitials(receipt.name)}
          </div>
        )
      ))}
      {receipts.length > 3 && (
        <span className="ml-1 text-[10px] font-medium text-dark-5 dark:text-dark-6">+{receipts.length - 3}</span>
      )}
    </div>
  );
}

export function MessageBubble({ msg, mode, senderPop, setSenderPop, onStartDm, onCallUser }: Readonly<MessageBubbleProps>) {
  const canClickSender = mode === "channel" && !msg.isMe && !!onStartDm;

  function handleAvatarClick(e: { stopPropagation(): void }) {
    if (!canClickSender) return;
    e.stopPropagation();
    setSenderPop((prev) => prev?.msgId === msg.id ? null : { msgId: msg.id, userId: msg.senderId, name: msg.senderName });
  }

  return (
    <div className={`flex gap-3 py-1 ${msg.isMe ? "flex-row-reverse" : ""}`}>
      <div className="relative mt-0.5 shrink-0">
        {msg.senderAvatar ? (
          <Image
            src={msg.senderAvatar}
            alt={msg.senderName}
            width={32}
            height={32}
            className={`size-8 rounded-full object-cover ${canClickSender ? "cursor-pointer ring-2 ring-transparent hover:ring-primary-400 transition-all" : ""}`}
            onClick={handleAvatarClick}
          />
        ) : (
          <button
            type="button"
            aria-label={`Open actions for ${msg.senderName}`}
            className={`flex size-8 items-center justify-center rounded-full bg-primary-100 text-xs font-bold text-primary-700 dark:bg-primary-900/30 dark:text-primary-300 ${canClickSender ? "cursor-pointer hover:ring-2 hover:ring-primary-400 transition-all" : ""}`}
            onClick={handleAvatarClick}
          >
            {getInitials(msg.senderName)}
          </button>
        )}
        {senderPop?.msgId === msg.id && (
          <div className="absolute left-9 top-0 z-30 flex items-center gap-0.5 rounded-xl border border-gray-3 bg-white px-1.5 py-1.5 shadow-card dark:border-dark-3 dark:bg-dark-2">
            <p className="mr-1 max-w-[80px] truncate px-1 text-xs font-semibold text-dark dark:text-white">{senderPop.name.split(" ")[0]}</p>
            <button
              title="Send message"
              onClick={() => { onStartDm?.(senderPop.userId, senderPop.name); setSenderPop(null); }}
              className="flex size-7 items-center justify-center rounded-lg text-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/20"
            >
              <svg className="size-4" viewBox="0 0 24 24" fill="none"><path d="M8.625 12a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0H8.25m4.125 0a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0H12m4.125 0a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0h-.375M21 12c0 4.556-4.03 8.25-9 8.25a9.764 9.764 0 01-2.555-.337A5.972 5.972 0 015.41 20.97a5.969 5.969 0 01-.474-.065 4.48 4.48 0 00.978-2.025c.09-.457-.133-.901-.467-1.226C3.93 16.178 3 14.189 3 12c0-4.556 4.03-8.25 9-8.25s9 3.694 9 8.25z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
            </button>
            <button
              title="Audio call"
              onClick={() => { onCallUser?.(senderPop.userId, senderPop.name, "audio"); setSenderPop(null); }}
              className="flex size-7 items-center justify-center rounded-lg text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20"
            >
              <svg className="size-4" viewBox="0 0 24 24" fill="none"><path d="M2.25 6.75c0 8.284 6.716 15 15 15h2.25a2.25 2.25 0 002.25-2.25v-1.372c0-.516-.351-.966-.852-1.091l-4.423-1.106c-.44-.11-.902.055-1.173.417l-.97 1.293c-.282.376-.769.542-1.21.38a12.035 12.035 0 01-7.143-7.143c-.162-.441.004-.928.38-1.21l1.293-.97c.363-.271.527-.734.417-1.173L6.963 3.102a1.125 1.125 0 00-1.091-.852H4.5A2.25 2.25 0 002.25 4.5v2.25z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
            </button>
            <button
              title="Video call"
              onClick={() => { onCallUser?.(senderPop.userId, senderPop.name, "video"); setSenderPop(null); }}
              className="flex size-7 items-center justify-center rounded-lg text-violet-600 hover:bg-violet-50 dark:hover:bg-violet-900/20"
            >
              <svg className="size-4" viewBox="0 0 24 24" fill="none"><path d="M15.75 10.5l4.72-4.72a.75.75 0 011.28.53v11.38a.75.75 0 01-1.28.53l-4.72-4.72M4.5 18.75h9a2.25 2.25 0 002.25-2.25v-9a2.25 2.25 0 00-2.25-2.25h-9A2.25 2.25 0 002.25 7.5v9a2.25 2.25 0 002.25 2.25z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
            </button>
          </div>
        )}
      </div>
      <div className={`max-w-sm flex flex-col gap-0.5 ${msg.isMe ? "items-end" : "items-start"}`}>
        <p className="text-xs text-dark-5 dark:text-dark-6">{msg.isMe ? "You" : msg.senderName}</p>
        <div className={`rounded-xl px-3.5 py-2.5 text-sm leading-relaxed ${msg.isMe ? "bg-primary-600 text-white" : "bg-gray-1 text-dark-4 dark:bg-dark-3 dark:text-dark-7"}`}>
          {msg.content}
        </div>
        <div className="flex items-center gap-1">
          <span className="text-[11px] text-dark-5 dark:text-dark-6">{formatTimestamp(msg.createdAt)}</span>
          {msg.readBy && <ReadAvatars readBy={msg.readBy} />}
        </div>
      </div>
    </div>
  );
}

"use client";

import Image from "next/image";
import type { ChannelItem } from "@/lib/actions/messages";
import type { DmConversation, DmUser } from "@/lib/actions/dm";

export type SidebarMode = "channel" | "dm";

interface Props {
  channels: ChannelItem[];
  conversations: DmConversation[];
  allUsers: DmUser[];
  activeChannelId: string | null;
  activeDmId: string | null;
  mode: SidebarMode;
  search: string;
  onSelectChannel: (id: string) => void;
  onSelectDm: (id: string) => void;
  onSearch: (value: string) => void;
  onNewDm: () => void;
  onStartDmWithUser: (userId: string, name: string, avatar: string | null) => void;
}

function formatTime(iso: string | null) {
  if (!iso) return "";
  const d = new Date(iso);
  const now = new Date();
  const diffDays = Math.floor((now.getTime() - d.getTime()) / 86400000);
  if (diffDays === 0) return d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
  if (diffDays === 1) return "Yesterday";
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function getInitials(name: string) {
  return name.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 2);
}

export function DmSidebar({
  channels,
  conversations,
  allUsers,
  activeChannelId,
  activeDmId,
  search,
  onSelectChannel,
  onSelectDm,
  onSearch,
  onNewDm,
  onStartDmWithUser,
}: Readonly<Props>) {
  const q = search.toLowerCase().trim();

  const filteredChannels = q
    ? channels.filter((ch) => ch.name.toLowerCase().includes(q))
    : channels;

  const filteredConvos = q
    ? conversations.filter((c) => c.otherUserName.toLowerCase().includes(q))
    : conversations;

  // Show employees from allUsers who don't already have a conversation, when searching
  const existingUserIds = new Set(conversations.map((c) => c.otherUserId));
  const searchableUsers = q
    ? allUsers.filter((u) => u.name.toLowerCase().includes(q) && !existingUserIds.has(u.userId))
    : [];

  return (
    <aside className="flex w-72 flex-shrink-0 flex-col border-r border-gray-3 bg-white dark:border-dark-3 dark:bg-dark-2">
      <div className="flex items-center justify-between border-b border-gray-3 px-4 py-3.5 dark:border-dark-3">
        <span className="text-body font-bold">Messages</span>
        <button
          onClick={onNewDm}
          title="New direct message"
          className="flex size-7 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
        >
          <svg className="size-4" viewBox="0 0 24 24" fill="none">
            <path d="M12 5v14m-7-7h14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          </svg>
        </button>
      </div>

      <div className="p-3">
        <div className="relative">
          <svg className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-dark-5" viewBox="0 0 24 24" fill="none">
            <path d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          <input
            placeholder="Search people or channels..."
            value={search}
            onChange={(e) => onSearch(e.target.value)}
            className="h-8 w-full rounded-lg border border-gray-3 bg-gray-2 pl-8 pr-3 text-xs outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white dark:placeholder-dark-6"
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-2 pb-4 space-y-1">
        {/* Channels section */}
        {filteredChannels.length > 0 && (
          <>
            <p className="px-2 pt-2 pb-1 text-xs font-semibold uppercase tracking-wider text-dark-5 dark:text-dark-6">
              Channels
            </p>
            {filteredChannels.map((ch) => {
              const isActive = ch.id === activeChannelId;
              return (
                <button
                  key={ch.id}
                  onClick={() => onSelectChannel(ch.id)}
                  className={`flex w-full items-center gap-3 rounded-lg px-2 py-2 text-left transition-colors ${isActive ? "bg-primary-50 dark:bg-primary-900/20" : "hover:bg-gray-2 dark:hover:bg-dark-3"}`}
                >
                  <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary-100 text-sm font-bold text-primary-700 dark:bg-primary-900/30 dark:text-primary-300">
                    #
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center justify-between">
                      <span className={`text-sm font-semibold truncate ${isActive ? "text-primary-600 dark:text-primary-300" : "text-dark dark:text-white"}`}>
                        {ch.name}
                      </span>
                      <span className="text-muted ml-1 shrink-0">{formatTime(ch.lastMessageAt)}</span>
                    </div>
                    <p className="truncate text-muted">{ch.lastMessage ?? "No messages yet"}</p>
                  </div>
                </button>
              );
            })}
          </>
        )}

        {/* Direct messages section */}
        <p className="px-2 pt-3 pb-1 text-xs font-semibold uppercase tracking-wider text-dark-5 dark:text-dark-6">
          Direct Messages
        </p>

        {/* Existing conversations */}
        {filteredConvos.map((c) => {
          const isActive = c.id === activeDmId;
          return (
            <button
              key={c.id}
              onClick={() => onSelectDm(c.id)}
              className={`flex w-full items-center gap-3 rounded-lg px-2 py-2 text-left transition-colors ${isActive ? "bg-primary-50 dark:bg-primary-900/20" : "hover:bg-gray-2 dark:hover:bg-dark-3"}`}
            >
              <div className="relative shrink-0">
                {c.otherUserAvatar ? (
                  <Image src={c.otherUserAvatar} alt={c.otherUserName} width={32} height={32} className="size-8 rounded-full object-cover" />
                ) : (
                  <div className="flex size-8 items-center justify-center rounded-full bg-violet-100 text-xs font-bold text-violet-700 dark:bg-violet-900/30 dark:text-violet-300">
                    {getInitials(c.otherUserName)}
                  </div>
                )}
                <span className="absolute bottom-0 right-0 size-2 rounded-full bg-emerald-400 ring-1 ring-white dark:ring-dark-2" />
              </div>
              <div className="min-w-0 flex-1">
                <div className="flex items-center justify-between">
                  <span className={`text-sm font-semibold truncate ${isActive ? "text-primary-600 dark:text-primary-300" : "text-dark dark:text-white"}`}>
                    {c.otherUserName}
                  </span>
                  <div className="flex items-center gap-1 ml-1 shrink-0">
                    <span className="text-muted">{formatTime(c.lastMessageAt)}</span>
                    {c.unreadCount > 0 && (
                      <span className="flex size-4 items-center justify-center rounded-full bg-primary-600 text-[10px] font-bold text-white">
                        {c.unreadCount > 9 ? "9+" : c.unreadCount}
                      </span>
                    )}
                  </div>
                </div>
                <p className="truncate text-muted">{c.lastMessage ?? "No messages yet"}</p>
              </div>
            </button>
          );
        })}

        {/* People from search who don't have a conversation yet */}
        {searchableUsers.length > 0 && (
          <>
            <p className="px-2 pt-2 pb-1 text-xs font-semibold uppercase tracking-wider text-dark-5 dark:text-dark-6">
              People
            </p>
            {searchableUsers.map((u) => (
              <button
                key={u.userId}
                onClick={() => onStartDmWithUser(u.userId, u.name, u.avatar)}
                className="flex w-full items-center gap-3 rounded-lg px-2 py-2 text-left transition-colors hover:bg-gray-2 dark:hover:bg-dark-3"
              >
                <div className="flex size-8 shrink-0 items-center justify-center rounded-full bg-violet-100 text-xs font-bold text-violet-700 dark:bg-violet-900/30 dark:text-violet-300">
                  {getInitials(u.name)}
                </div>
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-semibold text-dark dark:text-white truncate">{u.name}</p>
                  {u.jobTitle && <p className="text-xs text-dark-5 dark:text-dark-6 truncate">{u.jobTitle}</p>}
                </div>
                <span className="shrink-0 text-xs text-primary-600 dark:text-primary-400">Message</span>
              </button>
            ))}
          </>
        )}

        {/* Empty state */}
        {!q && filteredConvos.length === 0 && (
          <p className="px-2 py-3 text-center text-xs text-dark-5 dark:text-dark-6">
            No conversations yet. Click <strong>+</strong> or search for someone.
          </p>
        )}

        {q && filteredChannels.length === 0 && filteredConvos.length === 0 && searchableUsers.length === 0 && (
          <p className="px-2 py-3 text-center text-xs text-dark-5 dark:text-dark-6">No results for &ldquo;{search}&rdquo;</p>
        )}
      </div>
    </aside>
  );
}

"use client";

import { useState, useTransition, useCallback, useRef, useEffect } from "react";
import { useSession } from "next-auth/react";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { useSocket } from "@/hooks/use-socket";
import { DmSidebar } from "./dm-sidebar";
import { DmChatArea } from "./dm-chat-area";
import { IncomingCallModal, ActiveCallOverlay } from "./call-modal";
import { getChannelMessages, sendMessage, markChannelRead } from "@/lib/actions/messages";
import { getDmUsers, getDmMessages, sendDmMessage, markDmRead, getOrCreateConversation } from "@/lib/actions/dm";
import type { ChannelItem, ChannelMessage } from "@/lib/actions/messages";
import type { DmConversation, DmMessage, DmUser } from "@/lib/actions/dm";

const RTC_CONFIG: RTCConfiguration = {
  iceServers: [{ urls: "stun:stun.l.google.com:19302" }, { urls: "stun:stun1.l.google.com:19302" }],
};

type ReadReceipt = { userId: string; name: string; avatar: string | null; readAt: string };
function replaceReadReceipt(readBy: ReadReceipt[] | undefined, receipt: ReadReceipt) {
  return [...(readBy ?? []).filter((item) => item.userId !== receipt.userId), receipt];
}
interface MsgNewPayload { id: string; channelId: string; channelName: string; content: string; senderId: string; senderName: string; senderAvatar: string | null; createdAt: string; readBy?: ReadReceipt[]; }
interface DmNewPayload { id: string; conversationId: string; content: string; senderId: string; senderName: string; senderAvatar: string | null; createdAt: string; readBy?: ReadReceipt[]; }
interface DmReadPayload { conversationId: string; readById: string; lastReadMessageId: string | null; readAt: string | null; readerName: string; readerAvatar: string | null; }
interface ChannelReadPayload { channelId: string; lastReadMessageId: string | null; lastReadAt: string | null; readerId: string; readerName: string; readerAvatar: string | null; }
interface CallInvitePayload { callerId: string; callerName: string; conversationId?: string; channelId?: string; channelName?: string | null; type: "audio" | "video"; }
interface CallOfferPayload { offer: RTCSessionDescriptionInit; fromId: string; }
interface CallAnswerPayload { answer: RTCSessionDescriptionInit; }
interface IceCandidatePayload { candidate: RTCIceCandidateInit; }

// ─── Self-fetching New DM picker ───────────────────────────────────────────────
function NewDmPicker({ onSelect, onClose }: Readonly<{ onSelect: (u: DmUser) => void; onClose: () => void }>) {
  const [q, setQ] = useState("");
  const [users, setUsers] = useState<DmUser[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getDmUsers()
      .then(setUsers)
      .catch(() => setUsers([]))
      .finally(() => setLoading(false));
  }, []);

  const filtered = users.filter((u) => !q || u.name.toLowerCase().includes(q.toLowerCase()));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="w-full max-w-sm rounded-2xl bg-white p-5 shadow-modal dark:bg-dark-2">
        <div className="mb-3 flex items-center justify-between">
          <h2 className="text-base font-bold text-dark dark:text-white">New direct message</h2>
          <button onClick={onClose} className="text-dark-5 hover:text-dark dark:text-dark-6">
            <svg className="size-5" viewBox="0 0 24 24" fill="none"><path d="M6 18L18 6M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" /></svg>
          </button>
        </div>
        <input
          placeholder="Search people..."
          value={q}
          onChange={(e) => setQ(e.target.value)}
          autoFocus
          className="mb-3 h-9 w-full rounded-lg border border-gray-3 bg-gray-2 px-3 text-sm outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white"
        />
        <div className="max-h-64 overflow-y-auto space-y-0.5">
          {loading && <p className="py-4 text-center text-sm text-dark-5">Loading...</p>}
          {!loading && filtered.length === 0 && <p className="py-4 text-center text-sm text-dark-5">No people found.</p>}
          {filtered.map((u) => (
            <button key={u.userId} onClick={() => onSelect(u)} className="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-left hover:bg-gray-2 dark:hover:bg-dark-3">
              <div className="flex size-8 shrink-0 items-center justify-center rounded-full bg-violet-100 text-xs font-bold text-violet-700 dark:bg-violet-900/30 dark:text-violet-300">
                {u.name.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 2)}
              </div>
              <div>
                <p className="text-sm font-semibold text-dark dark:text-white">{u.name}</p>
                {u.jobTitle && <p className="text-xs text-dark-5 dark:text-dark-6">{u.jobTitle}</p>}
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

// ─── Props ─────────────────────────────────────────────────────────────────────
interface Props {
  channels: ChannelItem[];
  conversations: DmConversation[];
  dmUsers: DmUser[];
  initialMessages: ChannelMessage[];
  initialChannelId: string | null;
  initialDmId?: string | null;
  initialChannelParam?: string | null;
}

export function MessagesPageClient({
  channels,
  conversations: initConvos,
  dmUsers: initDmUsers,
  initialMessages,
  initialChannelId,
  initialDmId,
  initialChannelParam,
}: Readonly<Props>) {
  const { data: session } = useSession();
  const [mode, setMode] = useState<"channel" | "dm">("channel");
  const [activeChannelId, setActiveChannelId] = useState<string | null>(initialChannelId);
  const [activeDmId, setActiveDmId] = useState<string | null>(null);
  const [channelMessages, setChannelMessages] = useState<ChannelMessage[]>(initialMessages);
  const [dmMessages, setDmMessages] = useState<DmMessage[]>([]);
  const [conversations, setConversations] = useState<DmConversation[]>(initConvos);
  const [allUsers, setAllUsers] = useState<DmUser[]>(initDmUsers);
  const [input, setInput] = useState("");
  const [search, setSearch] = useState("");
  const [showNewDm, setShowNewDm] = useState(false);
  const [isPending, startTransition] = useTransition();
  const { toast, setToast } = useToast();

  // Fetch all users client-side as well (in case server-side prop was empty)
  useEffect(() => {
    if (initDmUsers.length === 0) {
      getDmUsers().then(setAllUsers).catch(() => null);
    }
  }, [initDmUsers.length]);

  // Call state
  const [incomingCall, setIncomingCall] = useState<CallInvitePayload | null>(null);
  const [activeCall, setActiveCall] = useState<{ peerId: string; peerName: string; type: "audio" | "video"; scope: "dm" | "channel" } | null>(null);
  const [isMuted, setIsMuted] = useState(false);
  const [isCamOff, setIsCamOff] = useState(false);

  const peerRef = useRef<RTCPeerConnection | null>(null);
  const localStreamRef = useRef<MediaStream | null>(null);
  const localVideoRef = useRef<HTMLVideoElement | null>(null);
  const remoteVideoRef = useRef<HTMLVideoElement | null>(null);
  const remoteAudioRef = useRef<HTMLAudioElement | null>(null);
  const callStartTimeRef = useRef<number | null>(null);
  const activeCallConvoIdRef = useRef<string | null>(null);
  const activeCallChannelIdRef = useRef<string | null>(null);
  const activeCallScopeRef = useRef<"dm" | "channel" | null>(null);
  const emitRef = useRef<(event: string, data: unknown) => void>(() => null);

  const currentUserId = session?.user?.id;
  const currentUserName = (session?.user as { name?: string } | undefined)?.name ?? session?.user?.email ?? "You";

  const activeChannel = channels.find((ch) => ch.id === activeChannelId) ?? null;
  const activeConversation = conversations.find((c) => c.id === activeDmId) ?? null;

  // ─── WebRTC ───────────────────────────────────────────────────────────────────
  function teardownCall() {
    peerRef.current?.close();
    peerRef.current = null;
    localStreamRef.current?.getTracks().forEach((t) => t.stop());
    localStreamRef.current = null;
    if (localVideoRef.current) localVideoRef.current.srcObject = null;
    if (remoteVideoRef.current) remoteVideoRef.current.srcObject = null;
    if (remoteAudioRef.current) remoteAudioRef.current.srcObject = null;
    callStartTimeRef.current = null;
    activeCallConvoIdRef.current = null;
    activeCallChannelIdRef.current = null;
    activeCallScopeRef.current = null;
    setActiveCall(null);
    setIncomingCall(null);
    setIsMuted(false);
    setIsCamOff(false);
  }

  function makePeer(peerId: string): RTCPeerConnection {
    const pc = new RTCPeerConnection(RTC_CONFIG);
    peerRef.current = pc;
    pc.onicecandidate = (e) => {
      if (e.candidate) emitRef.current("call:ice-candidate", { targetId: peerId, candidate: e.candidate.toJSON() });
    };
    pc.ontrack = (e) => {
      if (remoteVideoRef.current) remoteVideoRef.current.srcObject = e.streams[0];
      if (remoteAudioRef.current) remoteAudioRef.current.srcObject = e.streams[0];
    };
    localStreamRef.current?.getTracks().forEach((t) => pc.addTrack(t, localStreamRef.current!));
    return pc;
  }

  // ─── Socket handlers ──────────────────────────────────────────────────────────
  const handleMessageNew = useCallback((data: unknown) => {
    const p = data as MsgNewPayload;
    if (p.channelId !== activeChannelId) return;
    setChannelMessages((prev) => {
      if (prev.some((m) => m.id === p.id)) return prev;
      return [...prev, { id: p.id, content: p.content, senderId: p.senderId, senderName: p.senderName, senderAvatar: p.senderAvatar, isMe: p.senderId === currentUserId, createdAt: p.createdAt, readBy: p.readBy ?? [] }];
    });
    if (p.senderId !== currentUserId) {
      markChannelRead(p.channelId).catch(() => null);
    }
  }, [activeChannelId, currentUserId]);

  const activeDmIdRef = useRef(activeDmId);
  activeDmIdRef.current = activeDmId;

  const handleDmNew = useCallback((data: unknown) => {
    const p = data as DmNewPayload;
    const curDmId = activeDmIdRef.current;
    if (p.conversationId === curDmId) {
      setDmMessages((prev) => {
        if (prev.some((m) => m.id === p.id)) return prev;
        return [...prev, { ...p, isMe: p.senderId === currentUserId, readBy: p.readBy ?? [] }];
      });
      markDmRead(p.conversationId).catch(() => null);
    }
    const isCallStamp = p.content.startsWith('{"__call__"');
    const sidebarLastMsg = isCallStamp ? "📞 Call" : p.content;
    setConversations((prev) =>
      prev.map((c) =>
        c.id === p.conversationId
          ? { ...c, lastMessage: sidebarLastMsg, lastMessageAt: p.createdAt, unreadCount: c.id === curDmId ? 0 : c.unreadCount + 1 }
          : c,
      ),
    );
  }, [currentUserId]);

  const handleDmRead = useCallback((data: unknown) => {
    const p = data as DmReadPayload;
    if (p.conversationId === activeDmIdRef.current) {
      const receipt = { userId: p.readById, name: p.readerName, avatar: p.readerAvatar, readAt: p.readAt ?? new Date().toISOString() };
      setDmMessages((prev) => prev.map((m) => m.id === p.lastReadMessageId ? {
        ...m,
        readBy: replaceReadReceipt(m.readBy, receipt),
      } : m));
    }
    setConversations((prev) => prev.map((c) => c.id === p.conversationId ? { ...c, unreadCount: 0 } : c));
  }, []);

  const handleChannelRead = useCallback((data: unknown) => {
    const p = data as ChannelReadPayload;
    if (p.channelId !== activeChannelId) return;
    const receipt = { userId: p.readerId, name: p.readerName, avatar: p.readerAvatar, readAt: p.lastReadAt ?? new Date().toISOString() };
    setChannelMessages((prev) => prev.map((m) => m.id === p.lastReadMessageId ? {
      ...m,
      readBy: replaceReadReceipt(m.readBy, receipt),
    } : m));
  }, [activeChannelId]);

  const handleCallInvite = useCallback((data: unknown) => {
    setIncomingCall(data as CallInvitePayload);
  }, []);

  const incomingCallRef = useRef(incomingCall);
  incomingCallRef.current = incomingCall;
  const activeCallRef = useRef(activeCall);
  activeCallRef.current = activeCall;

  const handleCallAccepted = useCallback(async (data: unknown) => {
    const p = data as { calleeId: string };
    if (!activeCallRef.current) return;
    callStartTimeRef.current = Date.now();
    const pc = makePeer(p.calleeId);
    const offer = await pc.createOffer();
    await pc.setLocalDescription(offer);
    emitRef.current("call:offer", { targetId: p.calleeId, offer });

  }, []);

  const handleCallRejected = useCallback(() => {
    setToast("Call declined.");
    teardownCall();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleCallOffer = useCallback(async (data: unknown) => {
    const p = data as CallOfferPayload;
    if (!incomingCallRef.current) return;
    const pc = peerRef.current ?? makePeer(p.fromId);
    await pc.setRemoteDescription(p.offer);
    const answer = await pc.createAnswer();
    await pc.setLocalDescription(answer);
    emitRef.current("call:answer", { targetId: p.fromId, answer });

  }, []);

  const handleCallAnswer = useCallback(async (data: unknown) => {
    const p = data as CallAnswerPayload;
    await peerRef.current?.setRemoteDescription(p.answer);
  }, []);

  const handleIceCandidate = useCallback(async (data: unknown) => {
    const p = data as IceCandidatePayload;
    await peerRef.current?.addIceCandidate(p.candidate).catch(() => null);
  }, []);

  const handleCallEnd = useCallback(() => {
    setToast("Call ended.");
    teardownCall();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const { emit } = useSocket({
    "message:new": handleMessageNew,
    "dm:new": handleDmNew,
    "dm:read": handleDmRead,
    "channel:read": handleChannelRead,
    "call:invite": handleCallInvite,
    "call:accepted": handleCallAccepted,
    "call:rejected": handleCallRejected,
    "call:offer": handleCallOffer,
    "call:answer": handleCallAnswer,
    "call:ice-candidate": handleIceCandidate,
    "call:end": handleCallEnd,
  });
  emitRef.current = emit;

  // ─── Navigation ───────────────────────────────────────────────────────────────
  function handleSelectChannel(id: string) {
    setMode("channel");
    setActiveChannelId(id);
    setActiveDmId(null);
    startTransition(async () => {
      try {
        setChannelMessages(await getChannelMessages(id));
        await markChannelRead(id);
      } catch {
        setChannelMessages([]);
      }
    });
  }

  function handleSelectDm(id: string) {
    setMode("dm");
    setActiveDmId(id);
    setActiveChannelId(null);
    setConversations((prev) => prev.map((c) => c.id === id ? { ...c, unreadCount: 0 } : c));
    startTransition(async () => {
      try {
        setDmMessages(await getDmMessages(id));
        await markDmRead(id);
      } catch { setDmMessages([]); }
    });
  }

  // Handle URL params from notification deep-links (runs once on mount)
  const handledParamRef = useRef(false);
  useEffect(() => {
    if (handledParamRef.current) return;
    if (!initialDmId && !initialChannelParam) return;
    handledParamRef.current = true;
    if (initialDmId) {
      handleSelectDm(initialDmId);
    } else if (initialChannelParam) {
      handleSelectChannel(initialChannelParam);
    }

  }, [initialDmId, initialChannelParam]);

  // ─── Open / create a DM conversation ─────────────────────────────────────────
  function openDmWith(userId: string, name: string, avatar: string | null = null) {
    startTransition(async () => {
      try {
        const convo = await getOrCreateConversation(userId);
        setConversations((prev) => {
          if (prev.some((c) => c.id === convo.id)) return prev;
          return [{ id: convo.id, otherUserId: userId, otherUserName: name, otherUserAvatar: avatar, lastMessage: null, lastMessageAt: null, unreadCount: 0 }, ...prev];
        });
        handleSelectDm(convo.id);
      } catch { setToast("Failed to open conversation"); }
    });
  }

  // ─── Send ─────────────────────────────────────────────────────────────────────
  function handleSend() {
    if (!input.trim()) return;
    const content = input.trim();
    setInput("");

    if (mode === "channel" && activeChannelId) {
      startTransition(async () => {
        try {
          await sendMessage(activeChannelId, content);
          await markChannelRead(activeChannelId);
        }
        catch (err) { setToast(err instanceof Error ? err.message : "Failed to send"); setInput(content); }
      });
    } else if (mode === "dm" && activeDmId) {
      const optimistic: DmMessage = {
        id: `tmp-${Date.now()}`,
        content,
        senderId: currentUserId ?? "",
        senderName: currentUserName,
        senderAvatar: null,
        isMe: true,
        readBy: [],
        createdAt: new Date().toISOString(),
      };
      setDmMessages((prev) => [...prev, optimistic]);
      startTransition(async () => {
        try {
          const saved = await sendDmMessage(activeDmId, content);
          setDmMessages((prev) => prev.map((m) => m.id === optimistic.id ? { ...saved, isMe: true } : m));
          setConversations((prev) => prev.map((c) => c.id === activeDmId ? { ...c, lastMessage: content, lastMessageAt: saved.createdAt } : c));
        } catch (err) {
          setToast(err instanceof Error ? err.message : "Failed to send");
          setDmMessages((prev) => prev.filter((m) => m.id !== optimistic.id));
          setInput(content);
        }
      });
    }
  }

  // ─── Call helpers ─────────────────────────────────────────────────────────────
  async function initiateCall(peerId: string, peerName: string, conversationId: string, type: "audio" | "video") {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: type === "video" });
      localStreamRef.current = stream;
      if (localVideoRef.current) localVideoRef.current.srcObject = stream;
      activeCallConvoIdRef.current = conversationId;
      activeCallChannelIdRef.current = null;
      activeCallScopeRef.current = "dm";
      setActiveCall({ peerId, peerName, type, scope: "dm" });
      emit("call:invite", { calleeId: peerId, conversationId, type, callerName: currentUserName });
    } catch {
      setToast("Could not access camera/microphone");
    }
  }

  async function initiateChannelCall(channelId: string, channelName: string, type: "audio" | "video") {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: type === "video" });
      localStreamRef.current = stream;
      if (localVideoRef.current) localVideoRef.current.srcObject = stream;
      activeCallConvoIdRef.current = null;
      activeCallChannelIdRef.current = channelId;
      activeCallScopeRef.current = "channel";
      setActiveCall({ peerId: channelId, peerName: channelName, type, scope: "channel" });
      emit("call:invite", { channelId, channelName, type, callerName: currentUserName });
    } catch {
      setToast("Could not access camera/microphone");
    }
  }

  async function handleCall(type: "audio" | "video") {
    if (mode === "channel" && activeChannel) {
      await initiateChannelCall(activeChannel.id, activeChannel.name, type);
      return;
    }
    if (!activeConversation || !activeDmId) return;
    await initiateCall(activeConversation.otherUserId, activeConversation.otherUserName, activeDmId, type);
  }

  async function handleCallUser(userId: string, name: string, type: "audio" | "video") {
    startTransition(async () => {
      try {
        const convo = await getOrCreateConversation(userId);
        setConversations((prev) => {
          if (prev.some((c) => c.id === convo.id)) return prev;
          return [{ id: convo.id, otherUserId: userId, otherUserName: name, otherUserAvatar: null, lastMessage: null, lastMessageAt: null, unreadCount: 0 }, ...prev];
        });
        await initiateCall(userId, name, convo.id, type);
      } catch { setToast("Failed to start call"); }
    });
  }

  async function handleAcceptCall() {
    if (!incomingCall) return;
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: incomingCall.type === "video" });
      localStreamRef.current = stream;
      if (localVideoRef.current) localVideoRef.current.srcObject = stream;
      callStartTimeRef.current = Date.now();
      activeCallConvoIdRef.current = incomingCall.conversationId ?? null;
      activeCallChannelIdRef.current = incomingCall.channelId ?? null;
      activeCallScopeRef.current = incomingCall.channelId ? "channel" : "dm";
      makePeer(incomingCall.callerId);
      setActiveCall({ peerId: incomingCall.callerId, peerName: incomingCall.channelName ?? incomingCall.callerName, type: incomingCall.type, scope: incomingCall.channelId ? "channel" : "dm" });
      setIncomingCall(null);
      emit("call:accepted", { callerId: incomingCall.callerId, conversationId: incomingCall.conversationId, channelId: incomingCall.channelId });
    } catch {
      setToast("Could not access camera/microphone");
      setIncomingCall(null);
    }
  }

  function handleRejectCall() {
    if (!incomingCall) return;
    emit("call:rejected", {
      callerId: incomingCall.callerId,
      conversationId: incomingCall.conversationId,
      channelId: incomingCall.channelId,
      callType: incomingCall.type,
    });
    setIncomingCall(null);
  }

  function handleEndCall() {
    if (activeCall) {
      const duration = callStartTimeRef.current
        ? Math.floor((Date.now() - callStartTimeRef.current) / 1000)
        : 0;
      emit("call:end", activeCallScopeRef.current === "channel" ? {
        channelId: activeCallChannelIdRef.current,
        callType: activeCall.type,
        duration,
      } : {
        targetId: activeCall.peerId,
        conversationId: activeCallConvoIdRef.current,
        callType: activeCall.type,
        duration,
      });
    }
    teardownCall();
  }

  const displayMessages = mode === "channel" ? channelMessages : dmMessages;

  return (
    <>
      <div className="page-container">
        <div className={`flex h-[calc(100vh-10rem)] overflow-hidden rounded-xl shadow-card transition-opacity ${isPending ? "opacity-70" : ""}`}>
          <DmSidebar
            channels={channels}
            conversations={conversations}
            allUsers={allUsers}
            activeChannelId={activeChannelId}
            activeDmId={activeDmId}
            mode={mode}
            search={search}
            onSelectChannel={handleSelectChannel}
            onSelectDm={handleSelectDm}
            onSearch={setSearch}
            onNewDm={() => setShowNewDm(true)}
            onStartDmWithUser={openDmWith}
          />
          <DmChatArea
            mode={mode}
            channel={mode === "channel" ? activeChannel : null}
            conversation={mode === "dm" ? activeConversation : null}
            messages={displayMessages}
            input={input}
            onInputChange={setInput}
            onSend={handleSend}
            onCall={handleCall}
            onSearch={() => setToast("Search coming soon")}
            onEmoji={() => setToast("Emoji picker coming soon!")}
            onAttach={() => setToast("File attachment coming soon!")}
            onStartDm={(userId, name) => openDmWith(userId, name)}
            onCallUser={handleCallUser}
          />
        </div>
        <Toast message={toast} />
      </div>

      {showNewDm && (
        <NewDmPicker onSelect={(u) => { setShowNewDm(false); openDmWith(u.userId, u.name, u.avatar); }} onClose={() => setShowNewDm(false)} />
      )}

      {incomingCall && !activeCall && (
        <IncomingCallModal
          callerName={incomingCall.callerName}
          channelName={incomingCall.channelName}
          type={incomingCall.type}
          onAccept={handleAcceptCall}
          onReject={handleRejectCall}
        />
      )}

      {activeCall && (
        <ActiveCallOverlay
          peerName={activeCall.peerName}
          type={activeCall.type}
          localVideoRef={localVideoRef}
          remoteVideoRef={remoteVideoRef}
          remoteAudioRef={remoteAudioRef}
          isMuted={isMuted}
          isCamOff={isCamOff}
          onToggleMute={() => { localStreamRef.current?.getAudioTracks().forEach((t) => { t.enabled = !t.enabled; }); setIsMuted((v) => !v); }}
          onToggleCam={() => { localStreamRef.current?.getVideoTracks().forEach((t) => { t.enabled = !t.enabled; }); setIsCamOff((v) => !v); }}
          onEnd={handleEndCall}
        />
      )}
    </>
  );
}

import Link from "next/link";

type DeptCount = {
  dept: string;
  count: number;
};

type HrHeadcountAttritionProps = {
  headcount: number;
  deptHeadcount: DeptCount[];
};

export function HrHeadcountAttrition({ headcount, deptHeadcount }: HrHeadcountAttritionProps) {
  const maxCount = Math.max(...deptHeadcount.map((d) => d.count), 1);

  return (
    <div className="grid grid-cols-1 gap-4 md:grid-cols-12 md:gap-6">

      {/* Headcount by Department */}
      <div className="md:col-span-7 rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
        <div className="flex items-center justify-between mb-5">
          <h2 className="font-semibold text-dark dark:text-white">Headcount by Department</h2>
          <Link href="/reports" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">Export →</Link>
        </div>

        {deptHeadcount.length === 0 ? (
          <p className="text-sm text-dark-5 dark:text-dark-6 py-4">No departments found.</p>
        ) : (
          <>
            <div className="flex items-end gap-2 h-32 mb-3">
              {deptHeadcount.map((d, i) => {
                const heightPct = Math.max(8, Math.round((d.count / maxCount) * 100));
                const isLast = i === deptHeadcount.length - 1;
                return (
                  <div key={d.dept} className="flex flex-1 flex-col items-center gap-1">
                    <span className="text-[10px] font-semibold text-dark-5 dark:text-dark-6">{d.count}</span>
                    <div
                      className={`w-full rounded-t-md ${isLast ? "bg-primary-600" : "bg-primary-200 dark:bg-primary-900/40"}`}
                      style={{ height: `${heightPct}%` }}
                    />
                    <span className="text-[10px] text-dark-5 dark:text-dark-6 whitespace-nowrap truncate w-full text-center" title={d.dept}>
                      {d.dept.length > 8 ? d.dept.slice(0, 7) + "…" : d.dept}
                    </span>
                  </div>
                );
              })}
            </div>

            <div className="flex items-center gap-4 py-3 border-t border-b border-gray-3 dark:border-dark-3 mb-4">
              <div className="flex items-center gap-1.5">
                <span className="text-xs font-semibold text-primary-600 dark:text-primary-400">{headcount}</span>
                <span className="text-xs text-dark-5 dark:text-dark-6">Total Active</span>
              </div>
              <div className="flex items-center gap-1.5">
                <span className="text-xs font-semibold text-dark dark:text-white">{deptHeadcount.length}</span>
                <span className="text-xs text-dark-5 dark:text-dark-6">Departments</span>
              </div>
            </div>

            <h3 className="text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6 mb-2">Department Breakdown</h3>
            <div className="divide-y divide-gray-3 dark:divide-dark-3">
              {deptHeadcount.map((row) => (
                <div key={row.dept} className="flex items-center justify-between py-1.5">
                  <span className="text-xs font-medium text-dark dark:text-white">{row.dept}</span>
                  <div className="flex items-center gap-3">
                    <span className="text-xs font-semibold text-dark dark:text-white">{row.count}</span>
                    <span className="text-xs text-dark-5 dark:text-dark-6">
                      {headcount > 0 ? `${Math.round((row.count / headcount) * 100)}%` : "—"}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </>
        )}
      </div>

      {/* Attrition Summary */}
      <div className="md:col-span-5 flex flex-col gap-4">

        <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-semibold text-dark dark:text-white">Attrition Summary</h2>
            <Link href="/employees" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">
              View All →
            </Link>
          </div>
          <p className="text-sm text-dark-5 dark:text-dark-6 mb-4">
            Attrition tracking requires exit interview data. Use the employee directory to manage offboarding.
          </p>
          <div className="grid grid-cols-2 gap-2">
            {[
              { label: "Total Active", value: String(headcount) },
              { label: "Departments", value: String(deptHeadcount.length) },
              { label: "Attrition Rate", value: "—" },
              { label: "Exits YTD", value: "—" },
            ].map((stat) => (
              <div key={stat.label} className="rounded-lg bg-gray-1 dark:bg-dark-3/40 px-3 py-2">
                <p className="text-[10px] text-dark-5 dark:text-dark-6">{stat.label}</p>
                <p className="text-xs font-bold text-dark dark:text-white">{stat.value}</p>
              </div>
            ))}
          </div>
          <div className="mt-4 border-t border-gray-3 dark:border-dark-3 pt-3">
            <Link href="/employees" className="block w-full rounded-lg bg-primary-600 px-4 py-2 text-center text-sm font-semibold text-white hover:bg-primary-700">
              Manage Employees →
            </Link>
          </div>
        </div>

        <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-semibold text-dark dark:text-white">Quick Links</h2>
          </div>
          <div className="space-y-2">
            {[
              { label: "Recruitment Pipeline", href: "/recruitment" },
              { label: "Leave Approvals", href: "/leave/approvals" },
              { label: "Performance Reviews", href: "/performance/reviews" },
              { label: "Payroll Management", href: "/payroll" },
              { label: "HR Reports", href: "/reports" },
            ].map((link) => (
              <Link
                key={link.href}
                href={link.href}
                className="flex items-center justify-between rounded-lg px-3 py-2 text-xs font-medium text-dark hover:bg-gray-1 dark:text-white dark:hover:bg-dark-3/40 transition-colors"
              >
                {link.label}
                <span className="text-dark-5 dark:text-dark-6">→</span>
              </Link>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
}

import Link from "next/link";

type JobPosting = {
  id: string;
  title: string;
  department: string;
  candidateCount: number;
  type: string;
};

type OnboardingEntry = {
  id: string;
  name: string;
  department: string;
  progress: number;
  day: number;
};

type HrThreeColumnsProps = {
  jobPostings: JobPosting[];
  onboarding: OnboardingEntry[];
};

const badgeClass = {
  indigo: "bg-primary-50 text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
  emerald: "bg-emerald-light text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
  amber: "bg-amber-light text-amber-dark dark:bg-amber-dark/20 dark:text-amber",
} as const;

const complianceItems = [
  { title: "POSH Training", detail: "Track completion status", status: "Track", statusColor: "amber" as const },
  { title: "Fire Safety Drill", detail: "Schedule annual drill", status: "Upcoming", statusColor: "indigo" as const },
  { title: "IT Security Audit", detail: "Run quarterly audit", status: "Pending", statusColor: "indigo" as const },
  { title: "Annual Health Check", detail: "Coordinate with clinic", status: "Plan", statusColor: "amber" as const },
];

export function HrThreeColumns({ jobPostings, onboarding }: HrThreeColumnsProps) {
  return (
    <div className="grid grid-cols-1 gap-4 md:grid-cols-3 md:gap-6">

      {/* Recruitment Pipeline */}
      <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
        <div className="flex items-center justify-between mb-4">
          <h2 className="font-semibold text-dark dark:text-white">Open Roles · {jobPostings.length}</h2>
          <Link href="/recruitment" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">View All →</Link>
        </div>
        {jobPostings.length === 0 ? (
          <p className="text-sm text-dark-5 dark:text-dark-6 py-4">No active job postings.</p>
        ) : (
          <div className="space-y-3">
            {jobPostings.map((role) => (
              <div key={role.id} className="flex items-center justify-between gap-2">
                <div className="min-w-0 flex-1">
                  <p className="text-xs font-semibold text-dark dark:text-white truncate">{role.title}</p>
                  <div className="mt-0.5 flex items-center gap-1.5">
                    <span className={`rounded px-1.5 py-0.5 text-[10px] font-semibold ${badgeClass.indigo}`}>{role.department}</span>
                    <span className="text-[10px] text-dark-5 dark:text-dark-6">{role.candidateCount} applicant{role.candidateCount !== 1 ? "s" : ""}</span>
                  </div>
                </div>
                <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-semibold ${badgeClass.amber}`}>{role.type}</span>
              </div>
            ))}
          </div>
        )}
        <div className="mt-4 border-t border-gray-3 dark:border-dark-3 pt-3">
          <Link href="/recruitment" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">
            Manage recruitment →
          </Link>
        </div>
      </div>

      {/* Active Onboarding */}
      <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
        <div className="flex items-center justify-between mb-4">
          <h2 className="font-semibold text-dark dark:text-white">Active Onboarding · {onboarding.length}</h2>
          <Link href="/onboarding" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">View →</Link>
        </div>
        {onboarding.length === 0 ? (
          <p className="text-sm text-dark-5 dark:text-dark-6 py-4">No active onboarding records.</p>
        ) : (
          <div className="space-y-3">
            {onboarding.map((person) => {
              const initials = person.name.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 2);
              return (
                <div key={person.id} className="flex items-center gap-2.5">
                  <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-primary-100 text-xs font-bold text-primary-700 dark:bg-primary-900/30 dark:text-primary-300">
                    {initials}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-1 mb-0.5">
                      <p className="text-xs font-semibold text-dark dark:text-white truncate">{person.name}</p>
                      <span className="text-[10px] text-dark-5 dark:text-dark-6 shrink-0">{person.progress}%</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <div className="relative h-1 w-20 rounded-full bg-gray-2 dark:bg-dark-3 overflow-hidden">
                        <div className="absolute inset-y-0 left-0 rounded-full bg-primary-500" style={{ width: `${person.progress}%` }} />
                      </div>
                      <span className="text-[10px] text-dark-5 dark:text-dark-6">Day {person.day}/30</span>
                      <span className={`rounded px-1.5 py-0.5 text-[10px] font-semibold ${badgeClass.indigo}`}>{person.department}</span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
        <div className="mt-4 border-t border-gray-3 dark:border-dark-3 pt-3">
          <Link href="/onboarding" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">
            View all onboarding →
          </Link>
        </div>
      </div>

      {/* Compliance Tracker */}
      <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
        <div className="flex items-center justify-between mb-4">
          <h2 className="font-semibold text-dark dark:text-white">Compliance Checklist</h2>
          <span className={`rounded-full px-2.5 py-0.5 text-xs font-semibold ${badgeClass.amber}`}>{complianceItems.length} items</span>
        </div>
        <div className="space-y-3">
          {complianceItems.map((item) => (
            <div key={item.title} className="border-b border-gray-3 dark:border-dark-3 pb-3 last:border-0 last:pb-0">
              <div className="flex items-start justify-between gap-2">
                <p className="text-xs font-semibold text-dark dark:text-white">{item.title}</p>
                <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-semibold ${badgeClass[item.statusColor]}`}>{item.status}</span>
              </div>
              <p className="mt-0.5 text-[10px] text-dark-5 dark:text-dark-6">{item.detail}</p>
            </div>
          ))}
        </div>
        <div className="mt-4 border-t border-gray-3 dark:border-dark-3 pt-3">
          <Link href="/reports" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">
            View All Compliance →
          </Link>
        </div>
      </div>

    </div>
  );
}

import Link from "next/link";
import { getHrDashboardData } from "@/lib/actions/dashboard";
import { HrKpiRow } from "./_components/hr-kpi-row";
