              <Link href="/leave/approvals" className="rounded-lg bg-primary-600 px-3 py-1 text-xs font-semibold text-white hover:bg-primary-700">
                Approvals: {pendingLeaveCount}
              </Link>
            </div>
          </div>

          {/* Payroll Status */}
          <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
            <div className="flex items-center justify-between mb-3">
              <h2 className="font-semibold text-dark dark:text-white">Payroll Status</h2>
              <span className="text-xs text-dark-5 dark:text-dark-6">{monthStr}</span>
            </div>
            <div className="flex items-center justify-between mb-3">
              <span className={`rounded-full px-2.5 py-0.5 text-xs font-semibold ${badge.amber}`}>Processing not started</span>
            </div>
            <p className="text-xs text-dark-5 dark:text-dark-6 mb-3">Cutoff: 25th &nbsp;·&nbsp; Payday: 31st</p>
            <Link href="/payroll" className="block w-full rounded-lg bg-primary-600 px-4 py-2 text-center text-sm font-semibold text-white hover:bg-primary-700">
              Start Payroll →
            </Link>
          </div>

        </div>
      </div>

      <HrThreeColumns jobPostings={data?.jobPostings ?? []} onboarding={data?.onboarding ?? []} />
      <HrHeadcountAttrition headcount={headcount} deptHeadcount={data?.deptHeadcount ?? []} />

    </div>
  );
}

"use client";

import Link from "next/link";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";

type DeptHealth = { name: string; headcount: number };

type LeadershipData = {
  totalEmployees: number;
  deptHealth: DeptHealth[];
  totalPayroll: number;
  pendingLeave: number;
  openJobs: number;
  taskMap: Record<string, number>;
};

const DEPT_COLORS = [
  "bg-emerald-50 text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
  "bg-primary-50 text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
  "bg-amber-light text-amber-dark dark:bg-amber-dark/20 dark:text-amber",
  "bg-violet-light text-violet-dark dark:bg-violet-dark/20 dark:text-violet-300",
  "bg-rose-light text-rose-dark dark:bg-rose-dark/20 dark:text-rose",
];

export function LeadershipDashboardClient({ data, orgName }: Readonly<{ data: LeadershipData; orgName: string }>) {
  const { toast, setToast } = useToast();

  const done = data.taskMap["DONE"] ?? 0;
  const total = Object.values(data.taskMap).reduce((a, b) => a + b, 0);
  const completionRate = total > 0 ? Math.round((done / total) * 100) : 0;

  const formattedPayroll = data.totalPayroll > 0
    ? `₹${(data.totalPayroll / 100000).toFixed(1)}L`
    : "N/A";

  return (
    <div className="page-container">
      {/* Section 1: Executive Header */}
      <div className="bg-gradient-to-r from-slate-800 to-primary-900 text-white rounded-xl p-6">
        <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
          <div className="flex-1">
            <h1 className="page-title text-white">{orgName} · Executive Overview</h1>
            <p className="mt-0.5 text-sm text-white/70">
              {new Date().toLocaleDateString("en-US", { month: "long", year: "numeric" })} · Q2 Performance
            </p>
            <div className="mt-4 flex flex-wrap gap-2">
              <span className="rounded-lg bg-white/10 px-4 py-2 text-sm font-medium text-white">
                {data.totalEmployees} Employees
              </span>
              <span className="rounded-lg bg-white/10 px-4 py-2 text-sm font-medium text-white">
                {data.openJobs} Open Roles
              </span>
              <span className="rounded-lg bg-white/10 px-4 py-2 text-sm font-medium text-white">
                {data.pendingLeave} Pending Approvals
              </span>
              {data.totalPayroll > 0 && (
                <span className="rounded-lg bg-white/10 px-4 py-2 text-sm font-medium text-white">
                  {formattedPayroll} Monthly Payroll
                </span>
              )}
            </div>
          </div>
          <div className="flex flex-col items-end gap-3">
            <p className="text-xs text-white/50">
              Last updated: {new Date().toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" })} IST
            </p>
            <button
              onClick={() => {
                const lines = [
                  `Executive Report — ${new Date().toLocaleDateString("en-US", { month: "long", year: "numeric" })}`,
                  `Organization: ${orgName}`,
                  "",
                  "KPIs",
                  `Total Employees,${data.totalEmployees}`,
                  `Open Positions,${data.openJobs}`,
                  `Pending Leave Approvals,${data.pendingLeave}`,
                  `Task Completion Rate,${completionRate}%`,
                  `Monthly Payroll,${formattedPayroll}`,
                  "",
                  "Department Headcount",
                  "Department,Headcount",
                  ...data.deptHealth.map((d) => `${d.name},${d.headcount}`),
                ];
                const blob = new Blob([lines.join("\n")], { type: "text/csv" });
                const url = URL.createObjectURL(blob);
                const a = document.createElement("a");
                a.href = url;
                a.download = `executive-report-${new Date().toISOString().slice(0, 7)}.csv`;
                a.click();
                URL.revokeObjectURL(url);
                setToast("Executive report downloaded!");
              }}
              className="rounded-lg border border-white/40 bg-white/10 px-4 py-2 text-sm font-semibold text-white hover:bg-white/20 transition-colors"
            >
              Generate Report
            </button>
          </div>
        </div>
      </div>

      {/* Section 2: KPI Row */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-2 lg:grid-cols-4 md:gap-6">
        <div className="card p-5 border-t-4 border-primary-500">
          <p className="text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Total Employees</p>
          <p className="mt-2 text-3xl font-bold text-primary-600">{data.totalEmployees}</p>
          <p className="text-muted mt-1">Active headcount</p>
        </div>

        <div className="card p-5 border-t-4 border-emerald-500">
          <p className="text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Task Completion</p>
          <p className="mt-2 text-3xl font-bold text-emerald-600">{completionRate}%</p>
          <p className="text-muted mt-1">{done} of {total} tasks</p>
        </div>

        <div className="card p-5 border-t-4 border-amber-500">
          <p className="text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Open Positions</p>
          <p className="mt-2 text-3xl font-bold text-amber-600">{data.openJobs}</p>
          <p className="text-muted mt-1">Active job postings</p>
        </div>

        <div className="card p-5 border-t-4 border-violet-500">
          <p className="text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Departments</p>
          <p className="mt-2 text-3xl font-bold text-violet-600">{data.deptHealth.length}</p>
          <p className="text-muted mt-1">Active departments</p>
        </div>
      </div>

      {/* Section 3: Org Layout */}
      <div className="grid gap-4 md:grid-cols-12 md:gap-6">
        {/* Department Headcount */}
        <div className="md:col-span-7 card-p">
          <div className="flex items-center justify-between mb-4">
            <h2 className="section-title">Department Headcount</h2>
            <Link href="/employees" className="text-xs text-primary-600 hover:underline dark:text-primary-400">View All →</Link>
          </div>

          {data.deptHealth.length === 0 ? (
            <p className="text-sm text-dark-5 dark:text-dark-6">No department data yet.</p>
          ) : (
            <div className="space-y-3">
              {data.deptHealth.map((dept, idx) => (
                <div key={dept.name}>
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-body-medium">{dept.name}</span>
                    <span className="text-muted font-semibold">{dept.headcount}</span>
                  </div>
                  <div className="relative h-2 rounded-full bg-gray-2 dark:bg-dark-3 overflow-hidden">
                    <div
                      className="absolute inset-y-0 left-0 rounded-full bg-primary-500"
                      style={{ width: data.totalEmployees > 0 ? `${Math.round((dept.headcount / data.totalEmployees) * 100)}%` : "0%" }}
                    />
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Department Health + Payroll Snapshot */}
        <div className="md:col-span-5 flex flex-col gap-4">
          <div className="card-p">
            <h2 className="section-title mb-3">Department Overview</h2>
            <div className="space-y-2.5">
              {data.deptHealth.slice(0, 6).map((dept, idx) => (
                <div key={dept.name} className="flex items-center justify-between">
                  <span className="text-body-medium">{dept.name}</span>
                  <span className={`rounded-full px-2 py-0.5 text-xs font-semibold ${DEPT_COLORS[idx % DEPT_COLORS.length]}`}>
                    {dept.headcount} people
                  </span>
                </div>
              ))}
              {data.deptHealth.length === 0 && (
                <p className="text-muted">No departments yet.</p>
              )}
            </div>
          </div>

          <div className="card-p">
            <h2 className="section-title mb-3">Quick Actions</h2>
            <div className="grid grid-cols-2 gap-2">
              <Link href="/employees" className="flex items-center gap-2 rounded-lg border border-gray-3 p-2.5 text-xs font-medium text-dark hover:bg-gray-2 dark:border-dark-3 dark:text-white dark:hover:bg-dark-3">
                <span>👥</span> Employees
              </Link>
              <Link href="/reports" className="flex items-center gap-2 rounded-lg border border-gray-3 p-2.5 text-xs font-medium text-dark hover:bg-gray-2 dark:border-dark-3 dark:text-white dark:hover:bg-dark-3">
                <span>📊</span> Reports
              </Link>
              <Link href="/payroll" className="flex items-center gap-2 rounded-lg border border-gray-3 p-2.5 text-xs font-medium text-dark hover:bg-gray-2 dark:border-dark-3 dark:text-white dark:hover:bg-dark-3">
                <span>💰</span> Payroll
              </Link>
              <Link href="/recruitment" className="flex items-center gap-2 rounded-lg border border-gray-3 p-2.5 text-xs font-medium text-dark hover:bg-gray-2 dark:border-dark-3 dark:text-white dark:hover:bg-dark-3">
                <span>🎯</span> Recruitment
              </Link>
            </div>
          </div>
        </div>
      </div>

      <Toast message={toast} />
    </div>
  );
}

import Image from "next/image";
import Link from "next/link";
import {
  DEPARTMENT_COLORS,
  STATUS_COLORS,
  type Employee,
  type EmployeeDisplay,
} from "./employee-data";

interface EmployeeCardProps {
  employee: Employee | EmployeeDisplay;
}

export function EmployeeCard({ employee }: EmployeeCardProps) {
  const deptColor =
    DEPARTMENT_COLORS[employee.department as keyof typeof DEPARTMENT_COLORS] ??
    "rounded-full bg-gray-100 px-2.5 py-0.5 text-xs font-medium text-dark-5";
  const statusColor = STATUS_COLORS[employee.status as keyof typeof STATUS_COLORS] ?? "bg-gray-400";
  const skills = "skills" in employee ? (employee as Employee).skills : [];

  return (
    <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3 flex flex-col">
      {/* Avatar + status */}
      <div className="flex items-start justify-between">
        <div className="relative">
          <Image
            src={employee.avatar}
            width={52}
            height={52}
            alt={employee.name}
            className="rounded-full object-cover"
          />
          <span
            className={`absolute bottom-0.5 right-0.5 h-3 w-3 rounded-full border-2 border-white dark:border-dark-2 ${statusColor}`}
            title={employee.status}
          />
        </div>
        <span className={deptColor}>
          {employee.department}
        </span>
      </div>

      {/* Name + Title */}
      <div className="mt-3">
        <h3 className="text-sm font-semibold text-dark dark:text-white">
          {employee.name}
        </h3>
        <p className="text-xs text-dark-5 dark:text-dark-6">{employee.title}</p>
      </div>

      {/* Email */}
      <p className="mt-2 truncate text-xs text-dark-5 dark:text-dark-6">
        {employee.email}
      </p>

      {/* Skills (only for legacy Employee shape) */}
      {skills.length > 0 && (
        <div className="mt-3 flex flex-wrap gap-1.5">
          {skills.slice(0, 3).map((skill) => (
            <span
              key={skill}
              className="rounded-md bg-gray-2 px-2 py-0.5 text-[10px] font-medium text-dark-5 dark:bg-dark-3 dark:text-dark-6"
            >
              {skill}
            </span>
          ))}
        </div>
      )}

      {/* Footer */}
      <div className="mt-4 border-t border-gray-3 pt-3 dark:border-dark-3">
        <Link
          href="/employees/profile"
          className="flex w-full items-center justify-center rounded-lg border border-gray-3 px-4 py-2 text-sm font-medium text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6"
        >
          View Profile
        </Link>
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { EmployeeCard } from "./employee-card";
import { EmployeeListRow } from "./employee-list-row";
import { StatCard } from "./stat-card";
import { AddEmployeeModal } from "./add-employee-modal";
import { TempPasswordModal } from "./temp-password-modal";
import { toEmployeeDisplay, type EmployeeWithDept } from "./employee-data";
import { createEmployee } from "@/lib/actions/employees";

const EMPTY_FORM = {
  firstName: "", lastName: "", email: "", phone: "",
  departmentId: "", title: "", employmentType: "Full-time",
  startDate: "", salary: "", role: "EMPLOYEE",
};

interface Department { id: string; name: string; }
interface Props { employees: EmployeeWithDept[]; departments: Department[]; totalCount: number; }

export function EmployeeDirectory({ employees, departments, totalCount }: Props) {
  const router = useRouter();
  const [search, setSearch] = useState("");
  const [department, setDepartment] = useState("All");
  const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
  const [showAddModal, setShowAddModal] = useState(false);
  const [createdPassword, setCreatedPassword] = useState<{ email: string; password: string } | null>(null);
  const [isPending, startTransition] = useTransition();
  const [formError, setFormError] = useState<string | null>(null);
  const [formData, setFormData] = useState(EMPTY_FORM);

  const filtered = employees.map(toEmployeeDisplay).filter((e) => {
    const matchSearch = search === "" || e.name.toLowerCase().includes(search.toLowerCase()) || e.title.toLowerCase().includes(search.toLowerCase()) || e.email.toLowerCase().includes(search.toLowerCase());
    const matchDept = department === "All" || e.department === department;
    return matchSearch && matchDept;
  });

  function handleFieldChange(field: keyof typeof formData, value: string) {
    setFormData((prev) => ({ ...prev, [field]: value }));
  }

  function handleSubmit() {
    setFormError(null);
    if (!formData.firstName || !formData.lastName || !formData.email || !formData.title || !formData.startDate || !formData.salary) {
      setFormError("Please fill in all required fields."); return;
    }
    startTransition(async () => {
      try {
        const result = await createEmployee({
          firstName: formData.firstName, lastName: formData.lastName, email: formData.email,
          phone: formData.phone || undefined, title: formData.title,
          departmentId: formData.departmentId || undefined, employmentType: formData.employmentType,
          startDate: formData.startDate, salary: Number(formData.salary),
          role: formData.role as "SUPER_ADMIN" | "HR_ADMIN" | "MANAGER" | "EMPLOYEE",
        });
        setShowAddModal(false); setFormData(EMPTY_FORM);
        setCreatedPassword({ email: formData.email, password: result.tempPassword });
        router.refresh();
      } catch (err: unknown) {
        setFormError(err instanceof Error ? err.message : "Failed to add employee.");
      }
    });
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <div className="flex items-center gap-3">
          <h1 className="page-title">Employee Directory</h1>
          <span className="rounded-full bg-sky-50 px-2.5 py-0.5 text-xs font-medium text-sky-dark dark:bg-sky-dark/10 dark:text-sky">{totalCount} employees</span>
        </div>
        <button onClick={() => setShowAddModal(true)} className="btn-primary">+ Add Employee</button>
      </div>

      <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
        <StatCard label="Total Employees" value={totalCount} iconBg="bg-primary-50 dark:bg-primary-900/20" icon={<svg className="size-5 text-primary-600 dark:text-primary-300" viewBox="0 0 24 24" fill="none"><path d="M15 19.128a9.38 9.38 0 002.625.372 9.337 9.337 0 004.121-.952 4.125 4.125 0 00-7.533-2.493M15 19.128v-.003c0-1.113-.285-2.16-.786-3.07M15 19.128v.106A12.318 12.318 0 018.624 21c-2.331 0-4.512-.645-6.374-1.766l-.001-.109a6.375 6.375 0 0111.964-3.07M12 6.375a3.375 3.375 0 11-6.75 0 3.375 3.375 0 016.75 0zm8.25 2.25a2.625 2.625 0 11-5.25 0 2.625 2.625 0 015.25 0z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>} trend="Active workforce" trendUp />
        <StatCard label="Active" value={totalCount} iconBg="bg-emerald-light dark:bg-emerald-dark/20" icon={<svg className="size-5 text-emerald-dark dark:text-emerald" viewBox="0 0 24 24" fill="none"><path d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>} trend="All active" trendUp />
        <StatCard label="On Leave" value={0} iconBg="bg-amber-light dark:bg-amber-dark/20" icon={<svg className="size-5 text-amber-dark dark:text-amber" viewBox="0 0 24 24" fill="none"><path d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>} />
        <StatCard label="Departments" value={departments.length} iconBg="bg-violet-light dark:bg-violet-dark/20" icon={<svg className="size-5 text-violet-dark dark:text-violet-300" viewBox="0 0 24 24" fill="none"><path d="M12 9v6m3-3H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>} trend="Active depts" trendUp />
      </div>

      <div className="card p-4">
        <div className="flex flex-wrap items-center gap-3">
          <div className="relative flex-1 min-w-48">
            <svg className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-dark-5 dark:text-dark-6" viewBox="0 0 24 24" fill="none">
              <path d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
            <input type="text" placeholder="Search employees..." value={search} onChange={(e) => setSearch(e.target.value)} className="h-9 w-full rounded-lg border border-gray-3 bg-gray-2 pl-9 pr-3 text-sm outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white dark:placeholder-dark-6" />
          </div>
          <select value={department} onChange={(e) => setDepartment(e.target.value)} className="h-9 rounded-lg border border-gray-3 bg-gray-2 px-3 text-sm outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white">
            <option value="All">All Departments</option>
            {departments.map((d) => <option key={d.id} value={d.name}>{d.name}</option>)}
          </select>
          <div className="flex rounded-lg border border-gray-3 dark:border-dark-3">
            <button onClick={() => setViewMode("grid")} className={`flex items-center justify-center rounded-l-lg px-3 py-2 transition-colors ${viewMode === "grid" ? "bg-primary-600 text-white" : "bg-transparent text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"}`} aria-label="Grid view">
              <svg className="size-4" viewBox="0 0 24 24" fill="none"><path d="M3.75 6A2.25 2.25 0 016 3.75h2.25A2.25 2.25 0 0110.5 6v2.25a2.25 2.25 0 01-2.25 2.25H6a2.25 2.25 0 01-2.25-2.25V6zM3.75 15.75A2.25 2.25 0 016 13.5h2.25a2.25 2.25 0 012.25 2.25V18a2.25 2.25 0 01-2.25 2.25H6A2.25 2.25 0 013.75 18v-2.25zM13.5 6a2.25 2.25 0 012.25-2.25H18A2.25 2.25 0 0120.25 6v2.25A2.25 2.25 0 0118 10.5h-2.25A2.25 2.25 0 0113.5 8.25V6zM13.5 15.75a2.25 2.25 0 012.25-2.25H18a2.25 2.25 0 012.25 2.25V18A2.25 2.25 0 0118 20.25h-2.25A2.25 2.25 0 0113.5 18v-2.25z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
            </button>
            <button onClick={() => setViewMode("list")} className={`flex items-center justify-center rounded-r-lg px-3 py-2 transition-colors ${viewMode === "list" ? "bg-primary-600 text-white" : "bg-transparent text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"}`} aria-label="List view">
              <svg className="size-4" viewBox="0 0 24 24" fill="none"><path d="M8.25 6.75h12M8.25 12h12m-12 5.25h12M3.75 6.75h.007v.008H3.75V6.75zm.375 0a.375.375 0 11-.75 0 .375.375 0 01.75 0zM3.75 12h.007v.008H3.75V12zm.375 0a.375.375 0 11-.75 0 .375.375 0 01.75 0zm-.375 5.25h.007v.008H3.75v-.008zm.375 0a.375.375 0 11-.75 0 .375.375 0 01.75 0z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
            </button>
          </div>
          <p className="text-muted">{filtered.length} results</p>
        </div>
      </div>

      {filtered.length === 0 ? (
        <div className="card empty-state"><p className="empty-state-text">No employees match your filters.</p></div>
      ) : viewMode === "grid" ? (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {filtered.map((employee) => (
            <div key={employee.id} onClick={() => router.push(`/employees/profile?id=${employee.id}`)} className="cursor-pointer hover:shadow-md transition-shadow">
              <EmployeeCard employee={employee} />
            </div>
          ))}
        </div>
      ) : (
        <div className="flex flex-col gap-3">
          {filtered.map((employee) => (
            <div key={employee.id} onClick={() => router.push(`/employees/profile?id=${employee.id}`)} className="cursor-pointer hover:shadow-md transition-shadow">
              <EmployeeListRow employee={employee} />
            </div>
          ))}
        </div>
      )}

      {showAddModal && (
        <AddEmployeeModal
          departments={departments} formData={formData} formError={formError}
          isPending={isPending} onFieldChange={handleFieldChange}
          onSubmit={handleSubmit} onClose={() => { setShowAddModal(false); setFormError(null); }}
        />
      )}

      {createdPassword && (
        <TempPasswordModal email={createdPassword.email} password={createdPassword.password} onDone={() => setCreatedPassword(null)} />
      )}
    </div>
  );
}

import Image from "next/image";
import Link from "next/link";
import {
  DEPARTMENT_COLORS,
  STATUS_COLORS,
  type Employee,
  type EmployeeDisplay,
} from "./employee-data";

interface EmployeeListRowProps {
  employee: Employee | EmployeeDisplay;
}

export function EmployeeListRow({ employee }: EmployeeListRowProps) {
  const deptColor =
    DEPARTMENT_COLORS[employee.department as keyof typeof DEPARTMENT_COLORS] ??
    "rounded-full bg-gray-100 px-2.5 py-0.5 text-xs font-medium text-dark-5";
  const statusColor = STATUS_COLORS[employee.status as keyof typeof STATUS_COLORS] ?? "bg-gray-400";
  const skills = "skills" in employee ? (employee as Employee).skills : [];

  return (
    <div className="flex items-center gap-4 rounded-xl bg-white px-5 py-4 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
      {/* Avatar */}
      <div className="relative shrink-0">
        <Image
          src={employee.avatar}
          width={42}
          height={42}
          alt={employee.name}
          className="rounded-full object-cover"
        />
        <span
          className={`absolute bottom-0.5 right-0.5 h-2.5 w-2.5 rounded-full border-2 border-white dark:border-dark-2 ${statusColor}`}
        />
      </div>

      {/* Name + Title */}
      <div className="min-w-0 flex-1">
        <p className="text-sm font-semibold text-dark dark:text-white">
          {employee.name}
        </p>
        <p className="text-xs text-dark-5 dark:text-dark-6">{employee.title}</p>
      </div>

      {/* Department */}
      <span className={`hidden sm:inline-flex ${deptColor}`}>
        {employee.department}
      </span>

      {/* Email */}
      <p className="hidden w-48 truncate text-xs text-dark-5 dark:text-dark-6 lg:block">
        {employee.email}
      </p>

      {/* Skills (only for legacy Employee shape) */}
      {skills.length > 0 && (
        <div className="hidden gap-1.5 xl:flex">
          {skills.slice(0, 2).map((skill) => (
            <span
              key={skill}
              className="rounded-md bg-gray-2 px-2 py-0.5 text-[10px] font-medium text-dark-5 dark:bg-dark-3 dark:text-dark-6"
            >
              {skill}
            </span>
          ))}
        </div>
      )}

      {/* Action */}
      <Link
        href="/employees/profile"
        className="shrink-0 rounded-lg border border-gray-3 px-4 py-2 text-sm font-medium text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6"
      >
        View
      </Link>
    </div>
  );
}

import Link from "next/link";
import { getLeaveRequests } from "@/lib/actions/leave";
import { getOrgReviews } from "@/lib/actions/performance";

export async function EmployeesActionItems() {
  const [pendingLeave, pendingReviews] = await Promise.all([
    getLeaveRequests("PENDING").catch(() => []),
    getOrgReviews().catch(() => []),
  ]);

  const pendingReviewCount = pendingReviews.filter((r) => r.status === "PENDING").length;

  const items = [
    ...(pendingLeave.length > 0
      ? [{
          icon: (
            <svg className="h-5 w-5 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          ),
          description: `${pendingLeave.length} leave request${pendingLeave.length !== 1 ? "s" : ""} awaiting approval`,
          badge: "Pending",
          badgeClass: "bg-amber-light text-amber-dark dark:bg-amber-dark/20 dark:text-amber",
          action: "Review",
          href: "/leave/approvals",
        }]
      : []),
    ...(pendingReviewCount > 0
      ? [{
          icon: (
            <svg className="h-5 w-5 text-primary-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          ),
          description: `${pendingReviewCount} performance review${pendingReviewCount !== 1 ? "s" : ""} pending`,
          badge: "Review",
          badgeClass: "bg-primary-50 text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
          action: "View",
          href: "/performance/reviews",
        }]
      : []),
    {
      icon: (
        <svg className="h-5 w-5 text-emerald-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
        </svg>
      ),
      description: "Annual performance cycle — configure reviewers",
      badge: "Upcoming",
      badgeClass: "bg-emerald-light text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
      action: "Setup",
      href: "/performance",
    },
  ];

  return (
    <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3 md:col-span-7">
      <div className="mb-4 flex items-center justify-between">
        <h2 className="text-base font-semibold text-dark dark:text-white">HR Action Items</h2>
        <span className="rounded-full bg-rose-light px-2.5 py-0.5 text-xs font-medium text-rose-dark dark:bg-rose-dark/20 dark:text-rose">
          {pendingLeave.length + pendingReviewCount} pending
        </span>
      </div>
      <div className="space-y-3">
        {items.map((item, idx) => (
          <div key={idx} className="flex items-center gap-3 rounded-lg p-2 hover:bg-gray-50 dark:hover:bg-dark-3">
            <div className="shrink-0">{item.icon}</div>
            <p className="flex-1 text-sm text-dark dark:text-white">{item.description}</p>
            <span className={`shrink-0 rounded-full px-2.5 py-0.5 text-xs font-medium ${item.badgeClass}`}>{item.badge}</span>
            <Link
              href={item.href}
              className="shrink-0 rounded-lg border border-gray-3 bg-white px-3 py-1 text-xs font-medium text-dark hover:bg-gray-2 dark:border-dark-3 dark:bg-dark-2 dark:text-white"
            >
              {item.action}
            </Link>
          </div>
        ))}
        {items.length === 0 && (
          <p className="py-4 text-center text-sm text-dark-5 dark:text-dark-6">No pending items — all caught up!</p>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import {
  createDepartment,
  updateDepartment,
  deleteDepartment,
  type DepartmentRow,
} from "@/lib/actions/departments";
import { type Employee, type FormState, BLANK_FORM } from "./dept-types";
import { DeptCard } from "./dept-card";
import { DeptFormModal } from "./dept-form-modal";
import { DeleteConfirmModal } from "./delete-confirm-modal";

interface Props {
  departments: DepartmentRow[];
  employees: Employee[];
}

export function DepartmentsClient({ departments, employees }: Readonly<Props>) {
  const router = useRouter();
  const [showCreate, setShowCreate] = useState(false);
  const [editDept, setEditDept] = useState<DepartmentRow | null>(null);
  const [deleteDept, setDeleteDept] = useState<DepartmentRow | null>(null);
  const [form, setForm] = useState<FormState>(BLANK_FORM);
  const [error, setError] = useState("");
  const [isPending, startTransition] = useTransition();

  const totalHeadcount = departments.reduce((sum, d) => sum + d.employeeCount, 0);
  const avgTeamSize = departments.length > 0 ? (totalHeadcount / departments.length).toFixed(1) : "—";
  const missingHead = departments.filter((d) => !d.headId).length;

  function openCreate() {
    setForm(BLANK_FORM);
    setError("");
    setShowCreate(true);
  }

  function openEdit(dept: DepartmentRow) {
    setForm({ name: dept.name, description: dept.description ?? "", color: dept.color, headId: dept.headId ?? "" });
    setError("");
    setEditDept(dept);
  }

  function handleCreate(e: React.FormEvent) {
    e.preventDefault();
    setError("");
    startTransition(async () => {
      try {
        await createDepartment({ ...form, headId: form.headId || undefined });
        setShowCreate(false);
        router.refresh();
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to create department");
      }
    });
  }

  function handleUpdate(e: React.FormEvent) {
    e.preventDefault();
    if (!editDept) return;
    setError("");
    startTransition(async () => {
      try {
        await updateDepartment(editDept.id, { ...form, headId: form.headId || undefined });
        setEditDept(null);
        router.refresh();
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to update department");
      }
    });
  }

  function handleDelete() {
    if (!deleteDept) return;
    startTransition(async () => {
      try {
        await deleteDepartment(deleteDept.id);
        setDeleteDept(null);
        router.refresh();
      } catch (err) {
        alert(err instanceof Error ? err.message : "Failed to delete department");
        setDeleteDept(null);
      }
    });
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <nav className="mb-1 flex items-center gap-1.5 text-xs text-dark-5 dark:text-dark-6">
            <Link href="/employees" className="hover:text-dark dark:hover:text-white transition-colors">Employees</Link>
            <span>/</span>
            <span className="text-dark dark:text-white font-medium">Departments</span>
          </nav>
          <h1 className="page-title">Departments</h1>
          <p className="mt-0.5 text-muted">
            {departments.length} department{departments.length === 1 ? "" : "s"} · {totalHeadcount} employees
          </p>
        </div>
        <button onClick={openCreate} className="btn-primary">+ New Department</button>
      </div>

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        <div className="stat-card">
          <p className="stat-label">Total Departments</p>
          <p className="stat-value text-primary-600">{departments.length}</p>
        </div>
        <div className="stat-card">
          <p className="stat-label">Total Headcount</p>
          <p className="stat-value text-emerald-600">{totalHeadcount}</p>
        </div>
        <div className="stat-card">
          <p className="stat-label">Avg Team Size</p>
          <p className="stat-value text-violet-600">{avgTeamSize}</p>
        </div>
        <div className="stat-card">
          <p className="stat-label">Missing Head</p>
          <p className={`stat-value ${missingHead > 0 ? "text-amber-600" : "text-dark dark:text-white"}`}>
            {missingHead}
          </p>
          {missingHead > 0 && <p className="mt-0.5 text-muted">needs attention</p>}
        </div>
      </div>

      {departments.length === 0 ? (
        <div className="empty-state card py-16">
          <div className="mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-primary-50 dark:bg-primary-900/20">
            <svg className="h-7 w-7 text-primary-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 21h16.5M4.5 3h15M5.25 3v18m13.5-18v18M9 6.75h1.5m-1.5 3h1.5m-1.5 3h1.5m3-6H15m-1.5 3H15m-1.5 3H15M9 21v-3.375c0-.621.504-1.125 1.125-1.125h3.75c.621 0 1.125.504 1.125 1.125V21" />
            </svg>
          </div>
          <p className="text-sm font-semibold text-dark dark:text-white">No departments yet</p>
          <p className="mt-1 empty-state-text">Create your first department to organise your workforce.</p>
          <button onClick={openCreate} className="btn-primary mt-4">+ Create Department</button>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4">
          {departments.map((dept) => (
            <DeptCard key={dept.id} dept={dept} onEdit={openEdit} onDelete={setDeleteDept} />
          ))}
        </div>
      )}

      {showCreate && (
        <DeptFormModal
          title="New Department"
          form={form}
          setForm={setForm}
          onSubmit={handleCreate}
          onClose={() => { setShowCreate(false); setError(""); }}
          error={error}
          isPending={isPending}
          employees={employees}
          submitLabel="Create Department"
        />
      )}

      {editDept && (
        <DeptFormModal
          title="Edit Department"
          form={form}
          setForm={setForm}
          onSubmit={handleUpdate}
          onClose={() => { setEditDept(null); setError(""); }}
          error={error}
          isPending={isPending}
          employees={employees}
          submitLabel="Save Changes"
        />
      )}

      {deleteDept && (
        <DeleteConfirmModal
          dept={deleteDept}
          onConfirm={handleDelete}
          onClose={() => setDeleteDept(null)}
          isPending={isPending}
        />
      )}
    </div>
  );
}

import Image from "next/image";
import Link from "next/link";
import type { DepartmentRow } from "@/lib/actions/departments";
import { AvatarStack } from "./avatar-stack";

export function DeptCard({
  dept,
  onEdit,
  onDelete,
}: Readonly<{
  dept: DepartmentRow;
  onEdit: (d: DepartmentRow) => void;
  onDelete: (d: DepartmentRow) => void;
}>) {
  return (
    <div className="card flex flex-col overflow-hidden">
      <div className="h-1.5 w-full flex-shrink-0" style={{ backgroundColor: dept.color }} />

      <div className="flex flex-1 flex-col p-5">
        <div className="flex items-start justify-between gap-2">
          <div className="flex items-center gap-2.5 min-w-0">
            <span className="mt-0.5 h-2.5 w-2.5 flex-shrink-0 rounded-full" style={{ backgroundColor: dept.color }} />
            <h3 className="section-title truncate">{dept.name}</h3>
          </div>
          <div className="flex flex-shrink-0 items-center gap-1">
            <button
              onClick={() => onEdit(dept)}
              title="Edit department"
              className="flex h-7 w-7 items-center justify-center rounded-lg text-dark-5 transition-colors hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
            >
              <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
              </svg>
            </button>
            <button
              onClick={() => onDelete(dept)}
              title="Delete department"
              className="flex h-7 w-7 items-center justify-center rounded-lg text-dark-5 transition-colors hover:bg-rose-50 hover:text-rose-600 dark:text-dark-6 dark:hover:bg-rose-dark/10 dark:hover:text-rose"
            >
              <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </button>
          </div>
        </div>

        <p className="mt-2 text-xs text-dark-5 dark:text-dark-6 line-clamp-2 min-h-[2.5rem]">
          {dept.description ?? "No description provided."}
        </p>

        <div className="mt-4 flex items-center gap-2.5">
          {dept.head ? (
            <>
              <Image
                src={dept.head.avatarUrl ?? "/images/user/user-03.png"}
                alt={`${dept.head.firstName} ${dept.head.lastName}`}
                width={32}
                height={32}
                className="h-8 w-8 flex-shrink-0 rounded-full object-cover ring-2 ring-white dark:ring-dark-2"
                style={{ "--tw-ring-color": dept.color } as React.CSSProperties}
              />
              <div className="min-w-0">
                <p className="truncate text-xs font-semibold text-dark dark:text-white">
                  {dept.head.firstName} {dept.head.lastName}
                </p>
                <p className="truncate text-[10px] text-dark-5 dark:text-dark-6">{dept.head.title}</p>
              </div>
            </>
          ) : (
            <div className="flex items-center gap-2">
              <div className="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full border-2 border-dashed border-gray-3 dark:border-dark-3">
                <svg className="h-3.5 w-3.5 text-dark-5 dark:text-dark-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                </svg>
              </div>
              <button onClick={() => onEdit(dept)} className="text-xs text-amber-600 hover:underline dark:text-amber">
                Set department head →
              </button>
            </div>
          )}
        </div>

        <div className="mt-4 flex items-center justify-between border-t border-gray-2 pt-3.5 dark:border-dark-3">
          {dept.employeeCount > 0 ? (
            <AvatarStack employees={dept.sampleEmployees} total={dept.employeeCount} />
          ) : (
            <span className="text-xs text-dark-5 dark:text-dark-6">No employees yet</span>
          )}
          <Link href={`/employees?dept=${dept.id}`} className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">
            View →
          </Link>
        </div>
      </div>
    </div>
  );
}

import type { FormState, Employee } from "./dept-types";
import { COLOR_SWATCHES } from "./dept-types";

export function DeptFormModal({
  title,
  form,
  setForm,
  onSubmit,
  onClose,
  error,
  isPending,
  employees,
  submitLabel,
}: Readonly<{
  title: string;
  form: FormState;
  setForm: React.Dispatch<React.SetStateAction<FormState>>;
  onSubmit: (e: React.FormEvent) => void;
  onClose: () => void;
  error: string;
  isPending: boolean;
  employees: Employee[];
  submitLabel: string;
}>) {
  return (
    <div className="modal-overlay">
      <div className="modal-panel max-w-lg p-0">
        <div className="modal-header">
          <h2 className="text-base font-semibold text-dark dark:text-white">{title}</h2>
          <button
            onClick={onClose}
            className="flex h-8 w-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <form onSubmit={onSubmit} className="space-y-4 p-5">
          {error && (
            <div className="rounded-lg bg-rose-50 px-3 py-2 text-sm text-rose-700 dark:bg-rose-dark/10 dark:text-rose">
              {error}
            </div>
          )}

          <div>
            <label htmlFor="dept-name" className="label-field">
              Department Name <span className="text-rose-500">*</span>
            </label>
            <input
              id="dept-name"
              value={form.name}
              onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
              required
              placeholder="e.g. Engineering"
              className="input-field"
            />
          </div>

          <div>
            <label htmlFor="dept-description" className="label-field">
              Description <span className="text-muted font-normal">(optional)</span>
            </label>
            <textarea
              id="dept-description"
              value={form.description}
              onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))}
              rows={2}
              placeholder="What does this department do?"
              className="input-field resize-none"
            />
          </div>

          <div>
            <p className="label-field">Color</p>
            <div className="flex flex-wrap gap-2">
              {COLOR_SWATCHES.map((s) => (
                <button
                  key={s.hex}
                  type="button"
                  title={s.label}
                  onClick={() => setForm((f) => ({ ...f, color: s.hex }))}
                  className={`h-7 w-7 rounded-full transition-transform hover:scale-110 ${
                    form.color === s.hex ? "ring-2 ring-offset-2 ring-dark dark:ring-white" : ""
                  }`}
                  style={{ backgroundColor: s.hex }}
                />
              ))}
            </div>
          </div>

          <div>
            <label htmlFor="dept-head" className="label-field">
              Department Head <span className="text-muted font-normal">(optional)</span>
            </label>
            <select
              id="dept-head"
              value={form.headId}
              onChange={(e) => setForm((f) => ({ ...f, headId: e.target.value }))}
              className="input-field"
            >
              <option value="">— No head assigned —</option>
              {employees.map((emp) => (
                <option key={emp.id} value={emp.id}>
                  {emp.firstName} {emp.lastName} · {emp.title}
                  {emp.department ? ` (${emp.department.name})` : ""}
                </option>
              ))}
            </select>
          </div>

          <div className="flex gap-3 pt-1">
            <button type="button" onClick={onClose} className="btn-secondary flex-1">
              Cancel
            </button>
            <button type="submit" disabled={isPending} className="btn-primary flex-1 disabled:opacity-50">
              {isPending ? "Saving…" : submitLabel}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import Image from "next/image";
import Link from "next/link";

interface OrgNodeProps {
  id: string;
  avatar: string;
  name: string;
  title: string;
  department?: string;
  reportsCount?: number;
  isRoot?: boolean;
  isHead?: boolean;
}

const DEPT_COLORS: Record<string, string> = {
  Engineering:
    "bg-primary-50 text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
  Product:
    "bg-violet-light text-violet-dark dark:bg-violet-dark/20 dark:text-violet-300",
  Finance:
    "bg-sky-50 text-sky-dark dark:bg-sky-dark/10 dark:text-sky",
  HR: "bg-amber-light text-amber-dark dark:bg-amber-dark/20 dark:text-amber",
};

export function OrgNode({
  id,
  avatar,
  name,
  title,
  department,
  reportsCount,
  isRoot = false,
  isHead = false,
}: OrgNodeProps) {
  return (
    <Link
      href={`/employees/profile?id=${id}`}
      className={`group flex flex-col items-center rounded-xl bg-white p-4 shadow-card transition-all hover:-translate-y-0.5 hover:shadow-lg dark:bg-dark-2 dark:border dark:border-dark-3 ${
        isRoot ? "min-w-48 border-2 border-primary-200 dark:border-primary-800" : isHead ? "min-w-40" : "min-w-36"
      }`}
    >
      <div className="relative">
        <Image
          src={avatar}
          width={isRoot ? 64 : isHead ? 52 : 44}
          height={isRoot ? 64 : isHead ? 52 : 44}
          alt={name}
          className="rounded-full object-cover ring-2 ring-white dark:ring-dark-2"
        />
        <span className="absolute bottom-0.5 right-0.5 h-3 w-3 rounded-full border-2 border-white bg-emerald dark:border-dark-2" />
      </div>

      <p
        className={`mt-2 text-center font-semibold text-dark dark:text-white ${
          isRoot ? "text-sm" : "text-xs"
        }`}
      >
        {name}
      </p>
      <p className="mt-0.5 text-center text-[10px] text-dark-5 dark:text-dark-6">
        {title}
      </p>

      {department && (
        <span
          className={`mt-2 rounded-full px-2 py-0.5 text-[10px] font-medium ${DEPT_COLORS[department] ?? "bg-gray-100 text-gray-600"}`}
        >
          {department}
        </span>
      )}

      {reportsCount !== undefined && (
        <span className="mt-1.5 rounded-full bg-gray-2 px-2 py-0.5 text-[10px] font-medium text-dark-5 dark:bg-dark-3 dark:text-dark-6">
          {reportsCount} reports
        </span>
      )}
    </Link>
  );
}

