    <div className="rounded-xl bg-white p-6 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
      <div className="flex flex-wrap items-start gap-6">
        <div className="relative shrink-0">
          <Image
            src={employee.avatarUrl ?? "/images/user/user-01.png"}
            alt={`${employee.firstName} ${employee.lastName}`}
            width={80}
            height={80}
            className="rounded-full object-cover"
          />
          {employee.isActive && (
            <span className="absolute bottom-1 right-1 h-3.5 w-3.5 rounded-full border-2 border-white bg-emerald dark:border-dark-2" />
          )}
        </div>

        <div className="min-w-[160px]">
          <h1 className="text-xl font-bold text-dark dark:text-white">
            {employee.firstName} {employee.lastName}
          </h1>
          <p className="mt-0.5 text-sm text-dark-5 dark:text-dark-6">{employee.title}</p>
          <p className="mt-1 text-xs text-dark-5 dark:text-dark-6">
            Joined {new Date(employee.startDate).toLocaleDateString("en-US", { month: "long", year: "numeric" })} &middot; {tenure(employee.startDate)}
          </p>
        </div>

        <div className="min-w-[200px] flex-1 space-y-2.5">
          {employee.department && (
            <div>
              <span className="inline-flex items-center rounded-md px-2.5 py-0.5 text-xs font-medium"
                style={{ backgroundColor: employee.department.color + "20", color: employee.department.color }}>
                {employee.department.name}
              </span>
            </div>
          )}
          <p className="text-sm text-dark-5 dark:text-dark-6">
            {employee.employmentType} · {employee.employeeCode}
          </p>
          {employee.manager && (
            <p className="text-sm text-dark-5 dark:text-dark-6">
              Reports to{" "}
              <span className="font-medium text-dark dark:text-white">
                {employee.manager.firstName} {employee.manager.lastName}
              </span>
              , {employee.manager.title}
            </p>
          )}
          {employee.email && (
            <p className="truncate text-sm text-dark-5 dark:text-dark-6">{employee.email}</p>
          )}
        </div>

        <div className="grid grid-cols-3 gap-x-8 gap-y-3 text-center">
          <div>
            <p className="text-2xl font-bold text-dark dark:text-white">{totalLeave}</p>
            <p className="mt-0.5 text-xs text-dark-5 dark:text-dark-6">Leave Days</p>
          </div>
          <div>
            <p className="text-2xl font-bold text-dark dark:text-white">{activeGoals}</p>
            <p className="mt-0.5 text-xs text-dark-5 dark:text-dark-6">Active Goals</p>
          </div>
          <div>
            <p className={`text-sm font-semibold leading-tight ${employee.isActive ? "text-emerald-dark" : "text-rose-600"}`}>
              {employee.isActive ? "Active" : "Inactive"}
            </p>
            <p className="mt-0.5 text-xs text-dark-5 dark:text-dark-6">Status</p>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { deactivateEmployee, type EmployeeProfile } from "@/lib/actions/employees";
import { type SerializedReview } from "@/lib/actions/performance";
import { ProfileHeroCard } from "./profile-hero-card";
import { EditProfileModal } from "./edit-profile-modal";
import { OverviewTab } from "./tabs/overview-tab";
import { PerformanceTab } from "./tabs/performance-tab";
import { LeaveTab } from "./tabs/leave-tab";
import { DocumentsTab } from "./tabs/documents-tab";

type Tab = "overview" | "performance" | "leave" | "documents";

const TABS: { key: Tab; label: string }[] = [
  { key: "overview", label: "Overview" },
  { key: "performance", label: "Performance" },
  { key: "leave", label: "Leave History" },
  { key: "documents", label: "Documents" },
];

interface Props {
  employee: EmployeeProfile;
  departments: { id: string; name: string }[];
  reviews: SerializedReview[];
}

export function ProfilePageClient({ employee, departments, reviews }: Readonly<Props>) {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<Tab>("overview");
  const [showEdit, setShowEdit] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [isPending, startTransition] = useTransition();

  function handleDeactivate() {
    if (!confirm(`Deactivate ${employee.firstName} ${employee.lastName}? They will lose access immediately.`)) return;
    startTransition(async () => {
      await deactivateEmployee(employee.id);
      router.push("/employees");
    });
  }

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <nav className="flex items-center gap-1.5 text-xs text-dark-5 dark:text-dark-6">
          <Link href="/employees" className="hover:text-primary-600 dark:hover:text-primary-400">Employees</Link>
          <span>/</span>
          <span className="text-dark dark:text-white">{employee.firstName} {employee.lastName}</span>
        </nav>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowEdit(true)}
            className="rounded-lg border border-gray-3 bg-white px-4 py-2 text-sm font-medium text-dark hover:bg-gray-2 dark:border-dark-3 dark:bg-dark-2 dark:text-white"
          >
            Edit Profile
          </button>
          <div className="relative">
            <button
              onClick={() => setShowMenu((v) => !v)}
              className="rounded-lg border border-gray-3 bg-white px-4 py-2 text-sm font-medium text-dark hover:bg-gray-2 dark:border-dark-3 dark:bg-dark-2 dark:text-white"
            >
              &bull;&bull;&bull;
            </button>
            {showMenu && (
              <div className="absolute right-0 top-10 z-20 w-48 rounded-xl border border-gray-3 bg-white shadow-floating dark:border-dark-3 dark:bg-dark-2" onMouseLeave={() => setShowMenu(false)}>
                <button
                  onClick={() => { setShowMenu(false); handleDeactivate(); }}
                  disabled={isPending}
                  className="block w-full px-4 py-2.5 text-left text-sm text-rose-600 hover:bg-gray-2 dark:hover:bg-dark-3 rounded-xl disabled:opacity-50"
                >
                  Deactivate Account
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      <ProfileHeroCard employee={employee} />

      <div className="rounded-xl bg-white shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
        <div className="flex gap-6 overflow-x-auto border-b border-gray-3 px-6 dark:border-dark-3">
          {TABS.map(({ key, label }) => (
            <button
              key={key}
              onClick={() => setActiveTab(key)}
              className={`shrink-0 border-b-2 py-3.5 text-sm font-medium transition-colors ${
                activeTab === key
                  ? "border-primary-600 text-primary-600 dark:border-primary-400 dark:text-primary-400"
                  : "border-transparent text-dark-5 hover:text-dark dark:text-dark-6 dark:hover:text-white"
              }`}
            >
              {label}
            </button>
          ))}
        </div>
        <div className="p-6">
          {activeTab === "overview" && (
            <OverviewTab employee={employee} onGoToPerformance={() => setActiveTab("performance")} onGoToLeave={() => setActiveTab("leave")} />
          )}
          {activeTab === "performance" && <PerformanceTab reviews={reviews} />}
          {activeTab === "leave" && <LeaveTab leaveBalances={employee.leaveBalances} />}
          {activeTab === "documents" && <DocumentsTab />}
        </div>
      </div>

      {showEdit && (
        <EditProfileModal
          employee={employee}
          departments={departments}
          onClose={() => setShowEdit(false)}
        />
      )}
    </div>
  );
}

type LeaveBalance = {
  id: string;
  leaveType: string;
  total: number;
  used: number;
  pending: number;
  year: number;
};

const LEAVE_COLORS: Record<string, string> = {
  ANNUAL: "text-primary-600",
  SICK: "text-amber",
  CASUAL: "text-violet-500",
  MATERNITY: "text-emerald",
  PATERNITY: "text-sky-dark",
  UNPAID: "text-dark-4",
  OTHER: "text-rose-600",
};

interface Props {
  leaveBalances: LeaveBalance[];
}

export function LeaveTab({ leaveBalances }: Readonly<Props>) {
  return (
    <div className="space-y-5">
      {leaveBalances.length > 0 ? (
        <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
          {leaveBalances.map((lb) => (
            <div key={lb.id} className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3 text-center">
              <p className={`text-3xl font-bold ${LEAVE_COLORS[lb.leaveType] ?? "text-primary-600"}`}>
                {lb.total - lb.used - lb.pending}
              </p>
              <p className="mt-1 text-xs font-medium text-dark dark:text-white capitalize">
                {lb.leaveType.toLowerCase()} Leave
              </p>
              <p className="mt-0.5 text-xs text-dark-5 dark:text-dark-6">
                {lb.used}/{lb.total} used · {lb.pending} pending
              </p>
            </div>
          ))}
        </div>
      ) : (
        <div className="rounded-xl bg-white p-8 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3 text-center">
          <p className="text-sm text-dark-5 dark:text-dark-6">No leave balances set up for this year.</p>
        </div>
      )}

      <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
        <h2 className="mb-4 text-base font-semibold text-dark dark:text-white">Leave Summary — {new Date().getFullYear()}</h2>
        {leaveBalances.length > 0 ? (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-3 dark:border-dark-3">
                  {["Type", "Total", "Used", "Pending", "Available"].map((h) => (
