const LEVEL_BADGE: Record<string, string> = {
  Beginner:     "rounded-full bg-emerald-light px-2.5 py-0.5 text-xs font-medium text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
  Intermediate: "rounded-full bg-amber-light px-2.5 py-0.5 text-xs font-medium text-amber-dark",
  Advanced:     "rounded-full bg-rose-light px-2.5 py-0.5 text-xs font-medium text-rose-dark",
};

function getGradient(category: string) {
  return CATEGORY_GRADIENT[category] ?? "from-primary-500 to-violet-600";
}

export function CoursesClient({ courses, stats }: Readonly<{ courses: Course[]; stats: Stats }>) {
  const router = useRouter();
  const { toast, setToast } = useToast();
  const [, startTransition] = useTransition();
  const [search, setSearch] = useState("");
  const [activeCategory, setActiveCategory] = useState("All");

  const categories = ["All", ...Array.from(new Set(courses.map((c) => c.category))).sort()];

  const filtered = courses.filter((c) => {
    const matchSearch = c.title.toLowerCase().includes(search.toLowerCase());
    const matchCat = activeCategory === "All" || c.category === activeCategory;
    return matchSearch && matchCat;
  });

  function handleEnroll(courseId: string, title: string) {
    startTransition(async () => {
      try {
        await enrollInCourse(courseId);
        setToast(`Enrolled in "${title}"! Check My Learning for progress.`);
        router.refresh();
      } catch {
        setToast("Failed to enroll. Please try again.");
      }
    });
  }

  function handleContinue(course: Course) {
    if (!course.enrollmentId) return;
    startTransition(async () => {
      try {
        const newProgress = Math.min(100, course.progress + 10);
        await updateCourseProgress(course.enrollmentId!, newProgress);
        setToast(newProgress >= 100 ? `"${course.title}" marked as complete!` : `Progress updated to ${newProgress}%`);
        router.refresh();
      } catch {
        setToast("Failed to update progress");
      }
    });
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <h1 className="page-title">Course Catalog</h1>
          <p className="text-muted mt-0.5">{courses.length} courses · {stats.completionRate}% avg completion rate</p>
        </div>
        <div className="relative">
          <svg className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-dark-5 dark:text-dark-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" />
          </svg>
          <input
            type="text"
            placeholder="Search courses..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="input-field h-9 w-64 pl-9"
          />
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        {[
          { label: "Total Courses", value: courses.length, color: "text-primary-600 dark:text-primary-300", bg: "bg-primary-50 dark:bg-primary-900/20" },
          { label: "Enrolled",      value: stats.totalEnrollments, color: "text-emerald-dark dark:text-emerald", bg: "bg-emerald-light dark:bg-emerald-dark/20" },
          { label: "Completed",     value: stats.completedEnrollments, color: "text-amber-dark", bg: "bg-amber-light dark:bg-amber-dark/20" },
          { label: "Certifications",value: stats.certCount, color: "text-violet-dark dark:text-violet-300", bg: "bg-violet-light dark:bg-violet-dark/20" },
        ].map((s) => (
          <div key={s.label} className="card-p text-center">
            <p className={`text-2xl font-bold ${s.color}`}>{s.value}</p>
            <p className="text-muted mt-0.5 text-xs">{s.label}</p>
          </div>
        ))}
      </div>

      {/* Category Filter */}
      <div className="flex flex-wrap gap-2">
        {categories.map((cat) => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className={`rounded-lg px-4 py-2 text-sm font-medium transition-colors ${
              activeCategory === cat ? "bg-primary-600 text-white" : "btn-secondary"
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Course Grid */}
      {filtered.length === 0 ? (
        <div className="card flex h-40 items-center justify-center">
          <p className="text-muted">No courses found.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
          {filtered.map((course) => (
            <div key={course.id} className="card overflow-hidden">
              <div className={`flex h-36 items-center justify-center bg-gradient-to-br ${getGradient(course.category)}`}>
                <svg className="h-12 w-12 text-white/50" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                </svg>
              </div>
              <div className="p-4">
                <div className="mb-2 flex items-center justify-between">
                  <span className="rounded-full bg-primary-50 px-2.5 py-0.5 text-xs font-medium text-primary-600 dark:bg-primary-900/20 dark:text-primary-300">
                    {course.category}
                  </span>
                  <span className={LEVEL_BADGE[course.level] ?? LEVEL_BADGE.Beginner}>{course.level}</span>
                </div>
                <p className="text-body-medium mb-2 line-clamp-2">{course.title}</p>
                <div className="mb-3 flex items-center justify-between text-xs text-muted">
                  <span>{course.duration}</span>
                  <span>{course.enrolledCount} enrolled</span>
                </div>
                {course.isEnrolled && course.progress > 0 && (
                  <div className="mb-3">
                    <div className="mb-1 flex justify-between text-xs text-muted">
                      <span>Progress</span>
                      <span>{course.progress}%</span>
                    </div>
                    <div className="h-1.5 w-full rounded-full bg-gray-200 dark:bg-dark-3">
                      <div className="h-1.5 rounded-full bg-primary-600" style={{ width: `${course.progress}%` }} />
                    </div>
                  </div>
                )}
                <button
                  onClick={() => course.isEnrolled ? handleContinue(course) : handleEnroll(course.id, course.title)}
                  disabled={course.progress >= 100}
                  className={`w-full py-1.5 ${course.isEnrolled ? "btn-primary disabled:opacity-60" : "btn-secondary"}`}
                >
                  {course.isEnrolled ? (course.progress >= 100 ? "Completed ✓" : "Continue") : "Enroll"}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState } from "react";
import { applyLeave } from "@/lib/actions/leave";

interface ApplyLeaveModalProps {
  onClose: () => void;
}

type LeaveTypeEnum = "ANNUAL" | "SICK" | "CASUAL" | "MATERNITY" | "PATERNITY" | "UNPAID" | "OTHER";

const LEAVE_TYPE_OPTIONS: { value: LeaveTypeEnum; label: string }[] = [
  { value: "ANNUAL", label: "Annual Leave" },
  { value: "SICK", label: "Sick Leave" },
  { value: "CASUAL", label: "Casual Leave" },
  { value: "MATERNITY", label: "Maternity Leave" },
  { value: "PATERNITY", label: "Paternity Leave" },
  { value: "UNPAID", label: "Unpaid Leave" },
  { value: "OTHER", label: "Other" },
];

export function ApplyLeaveModal({ onClose }: ApplyLeaveModalProps) {
  const [leaveType, setLeaveType] = useState<LeaveTypeEnum>("ANNUAL");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [reason, setReason] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setSubmitting(true);
    try {
      await applyLeave({ leaveType, startDate, endDate, reason });
      onClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to submit leave request. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
      <div className="w-full max-w-md rounded-xl bg-white p-6 shadow-modal dark:bg-dark-2 dark:border dark:border-dark-3">
        <div className="flex items-center justify-between mb-5">
          <h2 className="text-sm font-semibold text-dark dark:text-white">Apply for Leave</h2>
          <button
            onClick={onClose}
            className="flex h-8 w-8 items-center justify-center rounded-lg hover:bg-gray-2 dark:hover:bg-dark-3 text-dark-5 dark:text-dark-6"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {error && (
          <div className="mb-4 rounded-lg bg-rose-light px-4 py-2.5 text-sm text-rose-dark dark:bg-rose-dark/20 dark:text-rose">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1.5 block text-xs font-medium text-dark dark:text-white">Leave Type</label>
            <select
              value={leaveType}
              onChange={(e) => setLeaveType(e.target.value as LeaveTypeEnum)}
              className="h-9 w-full rounded-lg border border-gray-3 bg-gray-2 px-3 text-sm outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white"
            >
              {LEAVE_TYPE_OPTIONS.map((opt) => (
                <option key={opt.value} value={opt.value}>{opt.label}</option>
              ))}
            </select>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="mb-1.5 block text-xs font-medium text-dark dark:text-white">From Date</label>
              <input
                type="date"
                required
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="h-9 w-full rounded-lg border border-gray-3 bg-gray-2 px-3 text-sm outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white"
              />
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-medium text-dark dark:text-white">To Date</label>
              <input
                type="date"
                required
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="h-9 w-full rounded-lg border border-gray-3 bg-gray-2 px-3 text-sm outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white"
              />
            </div>
          </div>

          <div>
            <label className="mb-1.5 block text-xs font-medium text-dark dark:text-white">Reason</label>
            <textarea
              rows={3}
              required
              minLength={5}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="Briefly describe the reason for leave..."
              className="w-full rounded-lg border border-gray-3 bg-gray-2 px-3 py-2 text-sm outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white dark:placeholder-dark-6 resize-none"
            />
          </div>

          <div className="flex gap-2 pt-1">
            <button
              type="button"
              onClick={onClose}
              disabled={submitting}
              className="flex-1 rounded-lg border border-gray-3 px-4 py-2 text-sm font-medium text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6 disabled:opacity-50"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="flex-1 rounded-lg bg-primary-600 px-4 py-2 text-sm font-semibold text-white hover:bg-primary-700 disabled:opacity-60"
            >
              {submitting ? "Submitting..." : "Submit Request"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import type { SerializedLeaveBalance, SerializedLeaveRequest } from "@/lib/actions/leave";
import { LeaveBalanceCards } from "./LeaveBalanceCards";
import { LeaveRequestsTable } from "./LeaveRequestsTable";
import { ApplyLeaveModal } from "./ApplyLeaveModal";

type Tab = "My Requests" | "Team Calendar" | "History";

interface LeavePageClientProps {
  balances: SerializedLeaveBalance[];
  requests: SerializedLeaveRequest[];
}

export function LeavePageClient({ balances, requests }: LeavePageClientProps) {
  const [activeTab, setActiveTab] = useState<Tab>("My Requests");
  const [showModal, setShowModal] = useState(false);

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">My Leave</h1>
          <p className="text-muted mt-0.5">Manage your leave requests and balances</p>
        </div>
        <button
          onClick={() => setShowModal(true)}
          className="btn-primary flex items-center gap-1.5 w-fit"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          Apply Leave
        </button>
      </div>

      {/* Leave Balance Cards */}
