      {/* Tabs */}
      <div className="card-p">
        <div className="flex items-center gap-1 border-b border-gray-3 dark:border-dark-3 -mx-5 px-5 mb-5">
          {(["My Requests", "Team Calendar", "History"] as Tab[]).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`pb-3 px-4 text-sm font-medium border-b-2 transition-colors ${
                activeTab === tab
                  ? "border-primary-600 text-primary-600"
                  : "border-transparent text-dark-5 hover:text-dark dark:text-dark-6 dark:hover:text-white"
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        {activeTab === "My Requests" && <LeaveRequestsTable requests={requests} />}

        {activeTab === "Team Calendar" && (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <div className="h-12 w-12 rounded-xl bg-primary-50 dark:bg-primary-900/20 flex items-center justify-center mb-3">
              <svg className="h-6 w-6 text-primary-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <p className="text-body-medium">Team Calendar</p>
            <p className="text-muted mt-1">
              View the full team calendar at{" "}
              <a href="/leave/calendar" className="text-primary-600 hover:underline">Leave Calendar</a>
            </p>
          </div>
        )}

        {activeTab === "History" && (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <div className="h-12 w-12 rounded-xl bg-gray-2 dark:bg-dark-3 flex items-center justify-center mb-3">
              <svg className="h-6 w-6 text-dark-5 dark:text-dark-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <p className="text-body-medium">Leave History</p>
            <p className="text-muted mt-1">All past leave records are shown in My Requests.</p>
          </div>
        )}
      </div>

      {/* Apply Leave Modal */}
      {showModal && <ApplyLeaveModal onClose={() => setShowModal(false)} />}
    </div>
  );
}

import type { SerializedLeaveRequest } from "@/lib/actions/leave";

interface LeaveRequestsTableProps {
  requests: SerializedLeaveRequest[];
}

type DisplayStatus = "Approved" | "Pending" | "Rejected";

const statusBadge: Record<DisplayStatus, string> = {
  Approved: "rounded-full bg-emerald-light px-2.5 py-0.5 text-xs font-medium text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
  Pending: "rounded-full bg-amber-light px-2.5 py-0.5 text-xs font-medium text-amber-dark dark:bg-amber-dark/20 dark:text-amber",
  Rejected: "rounded-full bg-rose-light px-2.5 py-0.5 text-xs font-medium text-rose-dark dark:bg-rose-dark/20 dark:text-rose",
};

const typeColors: Record<string, string> = {
  "Annual Leave": "bg-primary-50 text-primary-600 dark:bg-primary-900/20",
  "Sick Leave": "bg-rose-light text-rose-dark dark:bg-rose-dark/20 dark:text-rose",
  "Casual Leave": "bg-amber-light text-amber-dark dark:bg-amber-dark/20 dark:text-amber",
  "Maternity Leave": "bg-pink-50 text-pink-600 dark:bg-pink-900/20",
  "Paternity Leave": "bg-sky-50 text-sky-dark dark:bg-sky-dark/10 dark:text-sky",
  "Unpaid Leave": "bg-gray-100 text-dark-5 dark:bg-dark-3",
  "Other": "bg-violet-100 text-violet-dark dark:bg-violet-dark/20 dark:text-violet-400",
};

const LEAVE_TYPE_DISPLAY: Record<string, string> = {
  ANNUAL: "Annual Leave",
  SICK: "Sick Leave",
  CASUAL: "Casual Leave",
  MATERNITY: "Maternity Leave",
  PATERNITY: "Paternity Leave",
  UNPAID: "Unpaid Leave",
  OTHER: "Other",
};

function mapStatus(status: string): DisplayStatus {
  if (status === "APPROVED") return "Approved";
  if (status === "REJECTED") return "Rejected";
  return "Pending";
}

function formatDate(date: string): string {
  return new Date(date).toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

export function LeaveRequestsTable({ requests }: LeaveRequestsTableProps) {
  if (requests.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-center">
        <p className="text-sm font-medium text-dark dark:text-white">No leave requests found</p>
        <p className="text-xs text-dark-5 dark:text-dark-6 mt-1">Apply for leave using the button above.</p>
      </div>
    );
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full">
        <thead>
          <tr className="border-b border-gray-3 dark:border-dark-3">
            <th className="px-5 py-3 text-left text-xs font-semibold text-dark-5 dark:text-dark-6">Type</th>
            <th className="px-5 py-3 text-left text-xs font-semibold text-dark-5 dark:text-dark-6">From</th>
            <th className="px-5 py-3 text-left text-xs font-semibold text-dark-5 dark:text-dark-6">To</th>
            <th className="px-5 py-3 text-left text-xs font-semibold text-dark-5 dark:text-dark-6">Days</th>
            <th className="px-5 py-3 text-left text-xs font-semibold text-dark-5 dark:text-dark-6">Status</th>
            <th className="px-5 py-3 text-left text-xs font-semibold text-dark-5 dark:text-dark-6">Applied On</th>
            <th className="px-5 py-3 text-left text-xs font-semibold text-dark-5 dark:text-dark-6">Action</th>
          </tr>
        </thead>
        <tbody>
          {requests.map((req) => {
            const displayType = LEAVE_TYPE_DISPLAY[req.leaveType] ?? req.leaveType;
            const displayStatus = mapStatus(req.status);
            return (
              <tr key={req.id} className="border-b border-gray-3 last:border-0 hover:bg-gray-1 dark:border-dark-3 dark:hover:bg-dark-3">
                <td className="px-5 py-3">
                  <span className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${typeColors[displayType] ?? "bg-gray-2 text-dark-5"}`}>
                    {displayType}
                  </span>
                </td>
                <td className="px-5 py-3 text-sm text-dark dark:text-white">{formatDate(req.startDate)}</td>
                <td className="px-5 py-3 text-sm text-dark dark:text-white">{formatDate(req.endDate)}</td>
                <td className="px-5 py-3">
                  <span className="text-sm font-semibold text-dark dark:text-white">{req.days}d</span>
                </td>
                <td className="px-5 py-3">
                  <span className={statusBadge[displayStatus]}>{displayStatus}</span>
                </td>
                <td className="px-5 py-3 text-sm text-dark-5 dark:text-dark-6">{formatDate(req.createdAt)}</td>
                <td className="px-5 py-3">
                  {displayStatus === "Pending" ? (
                    <button className="rounded-lg border border-gray-3 px-3 py-1.5 text-xs font-medium text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6">
                      Cancel
                    </button>
                  ) : (
                    <button className="rounded-lg border border-gray-3 px-3 py-1.5 text-xs font-medium text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6">
                      View
                    </button>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { approveLeave, rejectLeave } from "@/lib/actions/leave";
import Link from "next/link";

type LeaveRequest = {
  id: string;
  employeeName: string;
  employeeDept: string;
  leaveType: string;
  startDate: string;
  endDate: string;
  days: number;
  reason: string;
  status: string;
  createdAt: string;
};

const LEAVE_BADGE: Record<string, string> = {
  ANNUAL: "badge-info",
  SICK: "badge-error",
  CASUAL: "badge-warning",
  MATERNITY: "badge-ai",
  PATERNITY: "badge-ai",
  UNPAID: "badge-gray",
  OTHER: "badge-ai",
};

export function ApprovalsClient({ requests }: Readonly<{ requests: LeaveRequest[] }>) {
  const router = useRouter();
  const { toast, setToast } = useToast();
  const [filter, setFilter] = useState("All");
  const [processing, setProcessing] = useState<string | null>(null);
  const [actionedIds, setActionedIds] = useState<Record<string, "approved" | "rejected">>({});

  const filtered = requests.filter((r) => {
    if (filter === "All") return true;
    return r.leaveType === filter.toUpperCase();
  });

  async function handleApprove(id: string) {
    setProcessing(id);
    try {
      await approveLeave(id);
      setActionedIds((p) => ({ ...p, [id]: "approved" }));
      setToast("Leave approved successfully!");
      router.refresh();
    } catch {
      setToast("Failed to approve leave.");
    } finally {
      setProcessing(null);
    }
  }

  async function handleReject(id: string) {
    setProcessing(id);
    try {
      await rejectLeave(id);
      setActionedIds((p) => ({ ...p, [id]: "rejected" }));
      setToast("Leave rejected.");
      router.refresh();
    } catch {
      setToast("Failed to reject leave.");
    } finally {
      setProcessing(null);
    }
  }

  const pendingCount = requests.filter((r) => !actionedIds[r.id]).length;

  return (
    <div className="page-container">
      {/* Header */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <div className="mb-1 flex items-center gap-2 text-muted">
            <Link href="/leave" className="hover:text-primary-600">Leave</Link>
            <span>/</span>
            <span>Approvals</span>
          </div>
          <div className="flex items-center gap-2">
            <h1 className="page-title">Pending Approvals</h1>
            {pendingCount > 0 && (
              <span className="badge-error">
                {pendingCount}
              </span>
            )}
          </div>
          <p className="text-muted mt-0.5">Review and action team leave requests</p>
        </div>
      </div>

      {/* Filter tabs */}
      <div className="flex flex-wrap items-center gap-1">
        {["All", "Annual", "Sick", "Casual"].map((cat) => (
          <button
            key={cat}
            onClick={() => setFilter(cat)}
            className={filter === cat ? "btn-primary" : "btn-secondary"}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Cards */}
      <div className="space-y-4">
        {filtered.length === 0 ? (
          <div className="card p-12 text-center">
            <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-xl bg-gray-2 dark:bg-dark-3">
              <svg className="h-6 w-6 text-dark-5 dark:text-dark-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <p className="text-body-medium">No pending requests</p>
            <p className="text-muted mt-1">All leave requests have been actioned.</p>
          </div>
        ) : (
          filtered.map((req) => {
            const actioned = actionedIds[req.id];

            if (actioned) {
              return (
                <div key={req.id} className="card-p opacity-60">
                  <div className="flex items-center gap-3">
                    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-gray-2 dark:bg-dark-3 text-sm font-bold text-dark dark:text-white">
                      {req.employeeName.charAt(0)}
                    </div>
                    <div className="flex-1">
                      <p className="text-body-medium">{req.employeeName}</p>
                      <p className="text-muted">{req.leaveType} leave</p>
                    </div>
                    <span className={actioned === "approved" ? "badge-success" : "badge-error"}>
                      {actioned === "approved" ? "Approved" : "Rejected"}
                    </span>
                  </div>
                </div>
              );
            }

            const daysAgo = Math.floor((Date.now() - new Date(req.createdAt).getTime()) / 86400000);

            return (
              <div key={req.id} className="card-p">
                <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                  <div className="flex items-start gap-3">
                    <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-primary-600 text-sm font-bold text-white">
                      {req.employeeName.charAt(0)}
                    </div>
                    <div>
                      <div className="flex flex-wrap items-center gap-2">
                        <p className="text-body-medium font-semibold">{req.employeeName}</p>
                        <span className={LEAVE_BADGE[req.leaveType] ?? LEAVE_BADGE.OTHER}>
                          {req.leaveType.charAt(0) + req.leaveType.slice(1).toLowerCase()} Leave
                        </span>
                      </div>
                      <p className="text-muted mt-0.5">{req.employeeDept}</p>
                      <div className="mt-2 flex flex-wrap items-center gap-3">
                        <div className="flex items-center gap-1.5">
                          <svg className="h-3.5 w-3.5 text-muted" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                          </svg>
                          <span className="text-body-medium text-xs">
                            {new Date(req.startDate).toLocaleDateString("en-US", { month: "short", day: "numeric" })} —{" "}
                            {new Date(req.endDate).toLocaleDateString("en-US", { month: "short", day: "numeric" })}
                          </span>
                        </div>
                        <span className="badge-gray">
                          {req.days} day{req.days > 1 ? "s" : ""}
                        </span>
                        <span className="text-muted">
                          {daysAgo === 0 ? "Today" : `${daysAgo}d ago`}
                        </span>
                      </div>
                      {req.reason && (
                        <p className="text-muted mt-2 italic">&quot;{req.reason}&quot;</p>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-wrap items-center gap-2 sm:shrink-0">
                    <button
                      onClick={() => handleReject(req.id)}
                      disabled={processing === req.id}
                      className="btn-danger"
                    >
                      Reject
                    </button>
                    <button
                      onClick={() => handleApprove(req.id)}
                      disabled={processing === req.id}
                      className="btn rounded-lg bg-emerald-500 text-white hover:bg-emerald-600"
                    >
                      {processing === req.id ? "..." : "Approve"}
                    </button>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { getLeaveCalendarEvents } from "@/lib/actions/reports";
import type { LeaveCalendarEvent as LeaveEvent } from "@/lib/actions/reports";

const MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];
const DAY_LABELS = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];

const STATUS_COLORS: Record<string, string> = {
  APPROVED: "bg-emerald-500",
  PENDING: "bg-amber-400",
  REJECTED: "bg-rose-500",
};

const LEAVE_TYPE_COLORS: Record<string, string> = {
  ANNUAL: "bg-primary-500",
  SICK: "bg-rose-500",
  CASUAL: "bg-amber-400",
  MATERNITY: "bg-violet-500",
  PATERNITY: "bg-violet-500",
  UNPAID: "bg-gray-400",
  OTHER: "bg-sky-500",
};

function buildCalendarDays(monthIndex: number, year: number): (number | null)[] {
  const firstDayOfWeek = new Date(year, monthIndex, 1).getDay();
  const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
  const days: (number | null)[] = [];
  for (let i = 0; i < firstDayOfWeek; i++) days.push(null);
  for (let d = 1; d <= daysInMonth; d++) days.push(d);
  while (days.length % 7 !== 0) days.push(null);
  return days;
}

// Use string comparison to avoid local-vs-UTC timezone mismatch
function getEventsForDay(events: LeaveEvent[], day: number, month: number, year: number) {
  const dayStr = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
  return events.filter((e) => {
    const start = e.startDate.slice(0, 10);
    const end = e.endDate.slice(0, 10);
    return dayStr >= start && dayStr <= end;
  });
}

export function LeaveCalendarClient({ events: initialEvents, currentMonth, currentYear }: Readonly<{
  events: LeaveEvent[];
  currentMonth: number;
  currentYear: number;
}>) {
  const [month, setMonth] = useState(currentMonth);
  const [year, setYear] = useState(currentYear);
  const [events, setEvents] = useState<LeaveEvent[]>(initialEvents);
  const [loading, setLoading] = useState(false);

  const calDays = buildCalendarDays(month, year);
  const today = new Date();

  async function navigateMonth(dir: -1 | 1) {
    let newMonth = month + dir;
    let newYear = year;
    if (newMonth < 0) { newMonth = 11; newYear--; }
    if (newMonth > 11) { newMonth = 0; newYear++; }
    setLoading(true);
    const newEvents = await getLeaveCalendarEvents(newMonth, newYear);
    setEvents(newEvents);
    setMonth(newMonth);
    setYear(newYear);
    setLoading(false);
  }

  const approvedCount = events.filter((e) => e.status === "APPROVED").length;
  const pendingCount = events.filter((e) => e.status === "PENDING").length;
  const rejectedCount = events.filter((e) => e.status === "REJECTED").length;

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="page-title">Leave Calendar</h1>
            {pendingCount > 0 && (
              <span className="rounded-full bg-amber-light px-2.5 py-0.5 text-xs font-medium text-amber-dark dark:bg-amber-dark/20 dark:text-amber">
                {pendingCount} pending
              </span>
            )}
          </div>
          <p className="text-muted mt-0.5">Team leave overview</p>
        </div>
        <div className="flex items-center gap-2">
          <Link href="/leave/approvals" className="btn-secondary">
            Approvals {pendingCount > 0 && `(${pendingCount})`}
          </Link>
          <Link href="/leave" className="btn-primary">
            Apply Leave
          </Link>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        {[
          { label: "Approved", value: approvedCount, color: "text-emerald-dark dark:text-emerald" },
          { label: "Pending", value: pendingCount, color: "text-amber-dark dark:text-amber" },
          { label: "Rejected", value: rejectedCount, color: "text-rose-dark dark:text-rose" },
          { label: "Unique Employees", value: new Set(events.map((e) => e.name)).size, color: "text-violet-dark dark:text-violet-300" },
        ].map((stat) => (
          <div key={stat.label} className="stat-card">
            <p className="stat-label">{stat.label}</p>
            <p className={`stat-value ${stat.color}`}>{stat.value}</p>
          </div>
        ))}
      </div>

      {/* Calendar */}
      <div className="card-p">
        <div className="flex items-center justify-between mb-4">
          <h2 className="section-title">
            {MONTHS[month]} {year}
          </h2>
          <div className="flex items-center gap-2">
            <button
              onClick={() => navigateMonth(-1)}
              disabled={loading}
              className="btn-secondary btn-sm"
            >
              ‹ Prev
            </button>
            <button
              onClick={() => navigateMonth(1)}
              disabled={loading}
              className="btn-secondary btn-sm"
            >
              Next ›
            </button>
          </div>
        </div>

        {/* Day labels */}
        <div className="grid grid-cols-7 mb-1">
          {DAY_LABELS.map((d) => (
            <div key={d} className="py-1 text-center text-muted text-xs font-semibold uppercase">{d}</div>
          ))}
        </div>

        {/* Calendar grid */}
        <div className="grid grid-cols-7 gap-px bg-gray-3 dark:bg-dark-3 border border-gray-3 dark:border-dark-3 rounded-lg overflow-hidden">
          {calDays.map((day, idx) => {
            const dayEvents = day ? getEventsForDay(events, day, month, year) : [];
            const isToday = day !== null
              && today.getDate() === day
              && today.getMonth() === month
              && today.getFullYear() === year;

            return (
              <div
                key={idx}
                className={`min-h-[80px] bg-white p-1.5 dark:bg-dark-2 ${!day ? "bg-gray-1 dark:bg-dark-3/50" : ""}`}
              >
                {day !== null && (
                  <>
                    <div className={`flex h-6 w-6 items-center justify-center rounded-full text-xs font-semibold mb-1 ${
                      isToday ? "bg-primary-600 text-white" : "text-dark dark:text-white"
                    }`}>
                      {day}
                    </div>
                    <div className="space-y-0.5">
                      {dayEvents.slice(0, 2).map((ev) => (
                        <div
                          key={`${ev.id}-${day}`}
                          title={`${ev.name} — ${ev.leaveType} (${ev.status})`}
                          className={`rounded px-1 py-0.5 text-[10px] font-medium text-white truncate ${STATUS_COLORS[ev.status] ?? "bg-gray-400"}`}
                        >
                          {ev.name}
                        </div>
                      ))}
                      {dayEvents.length > 2 && (
                        <div className="text-muted text-[10px]">+{dayEvents.length - 2} more</div>
                      )}
                    </div>
                  </>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-3">
        {[
          { label: "Approved", color: "bg-emerald-500" },
          { label: "Pending", color: "bg-amber-400" },
          { label: "Rejected", color: "bg-rose-500" },
        ].map((item) => (
          <div key={item.label} className="flex items-center gap-1.5">
            <span className={`h-3 w-3 rounded-full ${item.color}`} />
            <span className="text-muted">{item.label}</span>
          </div>
        ))}
      </div>

      {/* Event List */}
      {events.length > 0 && (
        <div className="card-p">
          <h2 className="section-title mb-3">All Leave Events — {MONTHS[month]} {year}</h2>
          <div className="space-y-2">
            {events.map((ev) => (
              <div key={ev.id} className="flex items-center justify-between rounded-lg border border-gray-2 p-3 dark:border-dark-3">
                <div className="flex items-center gap-3">
                  <div className={`h-2 w-2 rounded-full ${STATUS_COLORS[ev.status] ?? "bg-gray-400"}`} />
                  <div>
                    <p className="text-body-medium">{ev.name}</p>
                    <p className="text-muted">
                      {ev.dept} · {ev.leaveType.toLowerCase()} · {ev.days} day{ev.days !== 1 ? "s" : ""}
                    </p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-muted">
                    {new Date(ev.startDate).toLocaleDateString("en-US", { month: "short", day: "numeric" })} –{" "}
                    {new Date(ev.endDate).toLocaleDateString("en-US", { month: "short", day: "numeric" })}
                  </p>
                  <span className={`text-[10px] font-medium ${
                    ev.status === "APPROVED" ? "text-emerald-dark dark:text-emerald" :
                    ev.status === "PENDING" ? "text-amber-dark dark:text-amber" : "text-rose-dark dark:text-rose"
                  }`}>
                    {ev.status}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import Image from "next/image";

interface OnboardingCardProps {
  name: string;
  avatar: string;
  role: string;
  department: string;
  startDate: string;
  progress: number;
  pendingTasks: number;
  daysRemaining: number;
  departmentColor: string;
}

export function OnboardingCard({
  name,
  avatar,
  role,
  department,
  startDate,
  progress,
  pendingTasks,
  daysRemaining,
  departmentColor,
}: OnboardingCardProps) {
  const progressColor =
    progress >= 80 ? "bg-emerald-500" : progress >= 50 ? "bg-sky-500" : progress >= 25 ? "bg-amber-400" : "bg-rose-500";

  return (
    <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3 flex flex-col gap-4">
      {/* Top */}
      <div className="flex items-start justify-between gap-3">
        <div className="flex items-center gap-3">
          <Image
            src={avatar}
            alt={name}
            width={44}
            height={44}
            className="rounded-full object-cover"
          />
          <div>
            <p className="text-sm font-semibold text-dark dark:text-white">{name}</p>
            <p className="text-xs text-dark-5 dark:text-dark-6">{role}</p>
