      </div>

      {/* Progress */}
      <div>
        <div className="flex items-center justify-between mb-1.5">
          <span className="text-xs text-dark-5 dark:text-dark-6">Onboarding Progress</span>
          <span className="text-xs font-bold text-dark dark:text-white">{progress}%</span>
        </div>
        <div className="h-2 w-full rounded-full bg-gray-3 dark:bg-dark-3 overflow-hidden">
          <div className={`h-full rounded-full ${progressColor} transition-all`} style={{ width: `${progress}%` }} />
        </div>
      </div>

      {/* Stats */}
      <div className="flex items-center justify-between rounded-lg bg-gray-1 dark:bg-dark-3 px-4 py-2.5">
        <div className="text-center">
          <p className={`text-base font-bold ${pendingTasks > 0 ? "text-amber-dark" : "text-emerald-dark dark:text-emerald"}`}>
            {pendingTasks}
          </p>
          <p className="text-xs text-dark-5 dark:text-dark-6">Pending tasks</p>
        </div>
        <div className="h-8 w-px bg-gray-3 dark:bg-dark-3" />
        <div className="text-center">
          <p className={`text-base font-bold ${daysRemaining <= 3 ? "text-rose-dark" : "text-sky-dark dark:text-sky"}`}>
            {daysRemaining}d
          </p>
          <p className="text-xs text-dark-5 dark:text-dark-6">Days remaining</p>
        </div>
      </div>

      {/* Action */}
      <button className="w-full rounded-lg border border-gray-3 py-2 text-sm font-medium text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6 transition-colors">
        View Journey
      </button>
    </div>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import Link from "next/link";
import { createOnboarding } from "@/lib/actions/onboarding";

type OnboardingRecord = {
  id: string;
  employeeId: string;
  name: string;
  avatarUrl: string | null;
  role: string;
  department: string;
  startDate: string;
  progress: number;
  pendingTasks: number;
  daysRemaining: number | null;
  status: string;
};

type Stats = {
  inProgress: number;
  completedThisMonth: number;
  completingThisWeek: number;
};

function getInitials(name: string) {
  return name.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 2);
}

const DEPT_COLORS: Record<string, string> = {
  Engineering: "rounded-full bg-primary-50 px-2.5 py-0.5 font-medium text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
  Marketing: "rounded-full bg-rose-light px-2.5 py-0.5 font-medium text-rose-dark",
  Sales: "rounded-full bg-emerald-light px-2.5 py-0.5 font-medium text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
  HR: "rounded-full bg-amber-light px-2.5 py-0.5 font-medium text-amber-dark",
  Finance: "rounded-full bg-sky-50 px-2.5 py-0.5 font-medium text-sky-dark dark:bg-sky-dark/10 dark:text-sky",
  Product: "rounded-full bg-violet-light px-2.5 py-0.5 font-medium text-violet-dark dark:bg-violet-dark/20 dark:text-violet-300",
};

function getDeptColor(dept: string) {
  return DEPT_COLORS[dept] ?? "rounded-full bg-gray-100 px-2.5 py-0.5 font-medium text-gray-600 dark:bg-dark-3 dark:text-dark-6";
}

function getProgressColor(pct: number) {
  if (pct >= 80) return "bg-emerald-500";
  if (pct >= 50) return "bg-primary-500";
  if (pct >= 25) return "bg-amber-500";
  return "bg-rose-500";
}

export function OnboardingPageClient({ records, stats }: Readonly<{ records: OnboardingRecord[]; stats: Stats }>) {
  const [showModal, setShowModal] = useState(false);
  const { toast, setToast } = useToast();
  const router = useRouter();

  const [form, setForm] = useState({
    employeeId: "",
    startDate: "",
    dueDate: "",
  });

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    try {
      await createOnboarding({
        employeeId: form.employeeId,
        startDate: form.startDate,
        dueDate: form.dueDate || undefined,
      });
      setShowModal(false);
      setForm({ employeeId: "", startDate: "", dueDate: "" });
      setToast("Onboarding started successfully!");
      router.refresh();
    } catch (err) {
      setToast(err instanceof Error ? err.message : "Failed to start onboarding.");
    }
  }

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-xl font-bold text-dark dark:text-white">Onboarding</h1>
            <span className="rounded-full bg-emerald-light px-2.5 py-0.5 text-xs font-medium text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald">
              {stats.inProgress} in progress
            </span>
          </div>
          <p className="text-xs text-dark-5 dark:text-dark-6 mt-0.5">Track new employee onboarding journeys</p>
        </div>
        <div className="flex items-center gap-2">
          <Link href="/onboarding/offboarding" className="rounded-lg border border-gray-3 px-4 py-2 text-sm font-medium text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6">
            Offboarding
          </Link>
          <button
            onClick={() => setShowModal(true)}
            className="rounded-lg bg-primary-600 px-4 py-2 text-sm font-semibold text-white hover:bg-primary-700 flex items-center gap-2"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
            </svg>
            New Onboarding
          </button>
        </div>
      </div>

      {/* Stat Cards */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-xs text-dark-5 dark:text-dark-6">In Progress</p>
              <p className="mt-1 text-2xl font-bold text-dark dark:text-white">{stats.inProgress}</p>
              <p className="mt-0.5 text-xs text-dark-5 dark:text-dark-6">active onboarding journeys</p>
            </div>
            <span className="flex h-10 w-10 items-center justify-center rounded-lg bg-sky-50 dark:bg-sky-dark/10">
              <svg className="h-5 w-5 text-sky-dark" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z" />
              </svg>
            </span>
          </div>
        </div>

        <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-xs text-dark-5 dark:text-dark-6">Completing This Week</p>
              <p className="mt-1 text-2xl font-bold text-dark dark:text-white">{stats.completingThisWeek}</p>
              <p className="mt-0.5 text-xs text-amber-dark">Onboardings due soon</p>
            </div>
            <span className="flex h-10 w-10 items-center justify-center rounded-lg bg-amber-light dark:bg-amber-dark/20">
              <svg className="h-5 w-5 text-amber-dark" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </span>
          </div>
        </div>

        <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-xs text-dark-5 dark:text-dark-6">Completed This Month</p>
              <p className="mt-1 text-2xl font-bold text-dark dark:text-white">{stats.completedThisMonth}</p>
              <p className="mt-0.5 text-xs text-emerald-dark dark:text-emerald">successfully onboarded</p>
            </div>
            <span className="flex h-10 w-10 items-center justify-center rounded-lg bg-emerald-light dark:bg-emerald-dark/20">
              <svg className="h-5 w-5 text-emerald-dark" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </span>
          </div>
        </div>
      </div>

      {/* Onboarding Cards Grid */}
      {records.length === 0 ? (
        <div className="rounded-xl bg-white p-10 shadow-card dark:bg-dark-2 text-center">
          <p className="text-dark-5 dark:text-dark-6 mb-3">No active onboardings.</p>
          <button
            onClick={() => setShowModal(true)}
            className="rounded-lg bg-primary-600 px-4 py-2 text-sm font-semibold text-white hover:bg-primary-700"
          >
            Start First Onboarding
          </button>
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {records.map((ob) => (
            <div key={ob.id} className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
              <div className="flex items-start gap-3">
                {ob.avatarUrl ? (
                  <Image
                    src={ob.avatarUrl}
                    alt={ob.name}
                    width={40}
                    height={40}
                    className="h-10 w-10 rounded-full object-cover"
                  />
                ) : (
                  <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary-100 text-sm font-bold text-primary-600 dark:bg-primary-900/30 dark:text-primary-300">
                    {getInitials(ob.name)}
                  </span>
                )}
                <div className="min-w-0 flex-1">
                  <p className="font-semibold text-dark dark:text-white truncate">{ob.name}</p>
                  <p className="text-xs text-dark-5 dark:text-dark-6">{ob.role}</p>
                  <span className={`text-xs ${getDeptColor(ob.department)}`}>{ob.department}</span>
                </div>
              </div>

              <div className="mt-4">
                <div className="flex items-center justify-between mb-1">
                  <span className="text-xs text-dark-5 dark:text-dark-6">Progress</span>
                  <span className="text-xs font-semibold text-dark dark:text-white">{ob.progress}%</span>
                </div>
                <div className="relative h-2 rounded-full bg-gray-2 dark:bg-dark-3 overflow-hidden">
                  <div className={`absolute inset-y-0 left-0 rounded-full ${getProgressColor(ob.progress)}`} style={{ width: `${ob.progress}%` }} />
                </div>
              </div>

              <div className="mt-3 flex items-center justify-between text-xs text-dark-5 dark:text-dark-6">
                <span>Started {ob.startDate}</span>
                {ob.daysRemaining !== null && (
                  <span className={ob.daysRemaining <= 3 ? "text-rose-dark font-semibold" : "text-amber-dark"}>
                    {ob.daysRemaining === 0 ? "Due today" : `${ob.daysRemaining}d remaining`}
                  </span>
                )}
              </div>

              {ob.pendingTasks > 0 && (
                <div className="mt-2">
                  <span className="inline-flex items-center rounded-full bg-amber-light px-2 py-0.5 text-xs font-medium text-amber-dark dark:bg-amber-dark/20 dark:text-amber">
                    {ob.pendingTasks} tasks pending
                  </span>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* New Onboarding Modal */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="w-full max-w-lg rounded-2xl bg-white p-6 shadow-modal dark:bg-dark-2">
            <div className="mb-4 flex items-center justify-between">
              <h2 className="text-lg font-bold text-dark dark:text-white">Start New Onboarding</h2>
              <button
                onClick={() => setShowModal(false)}
                className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
              >
                <svg className="size-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label htmlFor="employee-id" className="block text-xs font-medium text-dark-5 dark:text-dark-6 mb-1">
                  Employee ID <span className="text-rose-500">*</span>
                </label>
                <input
                  id="employee-id"
                  type="text"
                  required
                  placeholder="Employee ID from the system"
                  value={form.employeeId}
                  onChange={(e) => setForm((p) => ({ ...p, employeeId: e.target.value }))}
                  className="w-full rounded-lg border border-gray-3 bg-white px-3 py-2 text-sm text-dark outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white"
                />
                <p className="mt-1 text-xs text-dark-5 dark:text-dark-6">Find employee IDs on the Employees page.</p>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label htmlFor="start-date" className="block text-xs font-medium text-dark-5 dark:text-dark-6 mb-1">
                    Start Date <span className="text-rose-500">*</span>
                  </label>
                  <input
                    id="start-date"
                    type="date"
                    required
                    value={form.startDate}
                    onChange={(e) => setForm((p) => ({ ...p, startDate: e.target.value }))}
                    className="w-full rounded-lg border border-gray-3 bg-white px-3 py-2 text-sm text-dark outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white"
                  />
                </div>
                <div>
                  <label htmlFor="due-date" className="block text-xs font-medium text-dark-5 dark:text-dark-6 mb-1">Due Date</label>
                  <input
                    id="due-date"
                    type="date"
                    value={form.dueDate}
                    onChange={(e) => setForm((p) => ({ ...p, dueDate: e.target.value }))}
                    className="w-full rounded-lg border border-gray-3 bg-white px-3 py-2 text-sm text-dark outline-none focus:border-primary-600 dark:border-dark-3 dark:bg-dark-3 dark:text-white"
                  />
                </div>
              </div>
              <div className="flex justify-end gap-3 pt-2">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="rounded-lg border border-gray-3 px-4 py-2 text-sm font-medium text-dark hover:bg-gray-2 dark:border-dark-3 dark:text-white"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="rounded-lg bg-primary-600 px-4 py-2 text-sm font-semibold text-white hover:bg-primary-700"
                >
                  Start Onboarding
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

"use client";

import type { ActiveEmployee } from "@/lib/actions/onboarding";

interface Props {
  employees: ActiveEmployee[];
  onClose: () => void;
  onSubmit: (e: React.FormEvent<HTMLFormElement>) => void;
  isPending?: boolean;
}

const EXIT_REASONS = ["Resignation", "Termination", "Retirement", "Contract End", "Relocation"];

export function NewOffboardingModal({ employees, onClose, onSubmit, isPending }: Readonly<Props>) {
  return (
    <div className="modal-overlay">
      <div className="modal-panel w-full max-w-lg p-6">
        <div className="mb-4 flex items-center justify-between">
          <h2 className="page-title">Initiate Offboarding</h2>
          <button
            onClick={onClose}
            className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
          >
            <svg className="size-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
        <form onSubmit={onSubmit} className="space-y-4">
          <div>
            <label className="label-field">Employee <span className="text-rose-500">*</span></label>
            <select name="employeeId" required className="input-field">
              <option value="">Select employee</option>
              {employees.map((e) => (
                <option key={e.id} value={e.id}>
                  {e.firstName} {e.lastName} — {e.title}
                </option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="label-field">Last Working Day <span className="text-rose-500">*</span></label>
              <input name="lastWorkingDay" type="date" required className="input-field" />
            </div>
            <div>
              <label className="label-field">Reason</label>
              <select name="reason" className="input-field">
                <option value="">Select reason</option>
                {EXIT_REASONS.map((r) => (
                  <option key={r} value={r}>{r}</option>
                ))}
              </select>
            </div>
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <button type="button" onClick={onClose} disabled={isPending} className="btn-secondary">Cancel</button>
            <button type="submit" disabled={isPending} className="btn-primary disabled:opacity-60">
              {isPending ? "Initiating…" : "Initiate"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import Image from "next/image";

export interface ExitTask {
  label: string;
  done: boolean;
}

export interface OffboardingRecord {
  id: string;
  name: string;
  avatarUrl: string | null;
  role: string;
  department: string;
  lastDay: string;
  reason: string;
  tasks: ExitTask[];
}

const DEPT_COLORS: Record<string, string> = {
  Engineering: "rounded-full bg-primary-50 px-2.5 py-0.5 text-xs font-medium text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
  Product: "rounded-full bg-violet-light px-2.5 py-0.5 text-xs font-medium text-violet-dark dark:bg-violet-dark/20 dark:text-violet-300",
  Finance: "rounded-full bg-sky-50 px-2.5 py-0.5 text-xs font-medium text-sky-dark dark:bg-sky-dark/10 dark:text-sky",
  HR: "rounded-full bg-amber-light px-2.5 py-0.5 text-xs font-medium text-amber-dark dark:bg-amber-dark/20 dark:text-amber",
  Sales: "rounded-full bg-emerald-light px-2.5 py-0.5 text-xs font-medium text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
  Operations: "rounded-full bg-rose-light px-2.5 py-0.5 text-xs font-medium text-rose-dark dark:bg-rose-dark/20 dark:text-rose",
};

const taskIcons: Record<string, React.ReactNode> = {
  "Assets Return": (
    <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17V7m0 10a2 2 0 01-2 2H5a2 2 0 01-2-2V7a2 2 0 012-2h2a2 2 0 012 2m0 10a2 2 0 002 2h2a2 2 0 002-2M9 7a2 2 0 012-2h2a2 2 0 012 2m0 10V7m0 10a2 2 0 002 2h2a2 2 0 002-2V7a2 2 0 00-2-2h-2a2 2 0 00-2 2" />
    </svg>
  ),
  "Knowledge Transfer": (
    <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
    </svg>
  ),
  "Exit Interview": (
    <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
    </svg>
  ),
  "Final Settlement": (
    <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
  ),
};

interface Props {
  ob: OffboardingRecord;
  onViewDetails: () => void;
  onSendReminder: () => void;
}

export function OffboardingCard({ ob, onViewDetails, onSendReminder }: Readonly<Props>) {
  const doneCount = ob.tasks.filter((t) => t.done).length;
  const progress = Math.round((doneCount / ob.tasks.length) * 100);
  const progressColor =
    progress === 100 ? "bg-emerald-500" : progress >= 50 ? "bg-sky-500" : progress >= 25 ? "bg-amber-400" : "bg-rose-500";

  return (
    <div className="card-p space-y-4">
      <div className="flex items-start justify-between gap-3">
        <div className="flex items-center gap-3">
          <Image
            src={ob.avatarUrl ?? "/images/user/default-avatar.png"}
            alt={ob.name}
            width={44}
            height={44}
            className="rounded-full object-cover"
          />
          <div>
            <p className="text-body-medium font-semibold">{ob.name}</p>
            <p className="text-muted">{ob.role}</p>
          </div>
        </div>
        <div className="text-right">
          <span className={DEPT_COLORS[ob.department] ?? "rounded-full bg-gray-200 px-2.5 py-0.5 text-xs font-medium text-dark-5"}>{ob.department}</span>
          <p className="mt-1 text-muted">
            Last day: <span className="font-medium text-rose-dark">{ob.lastDay}</span>
          </p>
        </div>
      </div>

      <div className="flex items-center gap-2 text-xs">
        <span className="text-dark-5 dark:text-dark-6">Reason:</span>
        <span className="font-medium text-dark dark:text-white">{ob.reason}</span>
      </div>

      <div>
        <div className="flex items-center justify-between mb-1.5">
          <span className="text-muted">Exit Progress</span>
          <span className="text-xs font-bold text-dark dark:text-white">{doneCount}/{ob.tasks.length} tasks</span>
        </div>
        <div className="h-2 w-full rounded-full bg-gray-3 dark:bg-dark-3 overflow-hidden">
          <div className={`h-full rounded-full ${progressColor}`} style={{ width: `${progress}%` }} />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-2">
        {ob.tasks.map((task) => (
          <div
            key={task.label}
            className={`flex items-center gap-2.5 rounded-lg px-3 py-2.5 ${task.done ? "bg-emerald-light dark:bg-emerald-dark/10" : "bg-gray-1 dark:bg-dark-3"}`}
          >
            <span className={task.done ? "text-emerald-dark dark:text-emerald" : "text-dark-5 dark:text-dark-6"}>
              {task.done ? (
                <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 13l4 4L19 7" />
                </svg>
              ) : (
                taskIcons[task.label]
              )}
            </span>
            <span className={`text-xs font-medium ${task.done ? "text-emerald-dark dark:text-emerald line-through" : "text-dark dark:text-white"}`}>
              {task.label}
            </span>
            {!task.done && <span className="ml-auto text-[10px] text-amber-dark">Pending</span>}
          </div>
        ))}
      </div>

      <div className="flex gap-2 border-t border-gray-3 pt-3 dark:border-dark-3">
        <button onClick={onViewDetails} className="flex-1 btn-secondary py-2 text-xs">View Details</button>
        <button onClick={onSendReminder} className="flex-1 btn-primary py-2 text-xs">Send Reminder</button>
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { initiateOffboarding, sendOffboardingReminder } from "@/lib/actions/onboarding";
import { OffboardingCard, type OffboardingRecord } from "./offboarding-card";
import { NewOffboardingModal } from "./new-offboarding-modal";
import type { ActiveEmployee } from "@/lib/actions/onboarding";

interface OffboardingStats {
  exitingThisMonth: number;
  assetsPending: number;
  exitInterviews: number;
  completed: number;
}

interface Props {
  records: OffboardingRecord[];
  stats: OffboardingStats;
  activeEmployees: ActiveEmployee[];
}

export function OffboardingClient({ records, stats, activeEmployees }: Readonly<Props>) {
  const router = useRouter();
  const [showModal, setShowModal] = useState(false);
  const [detailRecord, setDetailRecord] = useState<OffboardingRecord | null>(null);
  const [isPending, startTransition] = useTransition();
  const { toast, setToast } = useToast();

  const summaryStats = [
    { label: "Exiting This Month", value: String(stats.exitingThisMonth), color: "text-rose-dark" },
    { label: "Assets Pending", value: String(stats.assetsPending), color: "text-amber-dark" },
    { label: "Exit Interviews", value: String(stats.exitInterviews), color: "text-sky-dark" },
    { label: "Completed", value: String(stats.completed), color: "text-emerald-dark" },
  ];

  function handleInitiate(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    startTransition(async () => {
      try {
        await initiateOffboarding({
          employeeId: fd.get("employeeId") as string,
          lastWorkingDay: fd.get("lastWorkingDay") as string,
          reason: (fd.get("reason") as string) || undefined,
        });
        setShowModal(false);
        setToast("Offboarding process initiated successfully!");
        router.refresh();
      } catch (err) {
        setToast(err instanceof Error ? err.message : "Failed to initiate offboarding");
      }
    });
  }

  function handleSendReminder(employeeId: string) {
    startTransition(async () => {
      try {
        const result = await sendOffboardingReminder(employeeId);
        setToast(result.success ? `Reminder sent to ${result.name}` : "Could not send reminder");
      } catch {
        setToast("Failed to send reminder");
      }
    });
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <div className="flex items-center gap-2 text-muted mb-1">
            <Link href="/onboarding" className="hover:text-primary-600">Onboarding</Link>
            <span>/</span>
            <span>Offboarding</span>
          </div>
          <div className="flex items-center gap-2">
            <h1 className="page-title">Offboarding</h1>
            <span className="rounded-full bg-rose-light px-2.5 py-0.5 text-xs font-medium text-rose-dark">
              {records.length} active
            </span>
          </div>
          <p className="text-muted mt-0.5">Manage employee exit workflows</p>
        </div>
        <button onClick={() => setShowModal(true)} className="btn-primary flex items-center gap-2">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          New Offboarding
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        {summaryStats.map((stat) => (
          <div key={stat.label} className="card-p">
            <p className="text-muted">{stat.label}</p>
            <p className={`mt-1 text-2xl font-bold ${stat.color}`}>{stat.value}</p>
          </div>
        ))}
      </div>

      <div className="grid gap-5 lg:grid-cols-2">
        {records.length === 0 && (
          <div className="card-p col-span-2 py-10 text-center">
            <p className="text-sm text-dark-5 dark:text-dark-6">
              No active offboarding records in the last 90 days. Initiate a process using &ldquo;New Offboarding&rdquo;.
            </p>
          </div>
        )}
        {records.map((ob) => (
          <OffboardingCard
            key={ob.id}
            ob={ob}
            onViewDetails={() => setDetailRecord(ob)}
            onSendReminder={() => handleSendReminder(ob.id)}
          />
        ))}
      </div>

      {showModal && (
        <NewOffboardingModal
          employees={activeEmployees}
          onClose={() => setShowModal(false)}
          onSubmit={handleInitiate}
          isPending={isPending}
        />
      )}

      {detailRecord && (
        <div className="modal-overlay">
          <div className="modal-panel max-w-md p-6">
            <div className="mb-4 flex items-center justify-between">
              <h2 className="text-lg font-bold text-dark dark:text-white">Exit Details</h2>
              <button
                onClick={() => setDetailRecord(null)}
                className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
              >
                <svg className="size-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <div className="space-y-3 text-sm">
              <div className="flex justify-between">
                <span className="text-muted">Employee</span>
                <span className="font-medium text-dark dark:text-white">{detailRecord.name}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted">Role</span>
                <span className="text-dark dark:text-white">{detailRecord.role}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted">Department</span>
                <span className="text-dark dark:text-white">{detailRecord.department}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted">Last Day</span>
                <span className="font-medium text-rose-dark">{detailRecord.lastDay}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted">Exit Reason</span>
                <span className="text-dark dark:text-white">{detailRecord.reason}</span>
              </div>
              <div className="mt-4 border-t border-gray-3 pt-4 dark:border-dark-3">
                <p className="mb-2 text-xs font-semibold text-dark-5 dark:text-dark-6 uppercase tracking-wide">Exit Checklist</p>
                <div className="space-y-2">
                  {detailRecord.tasks.map((t) => (
                    <div key={t.label} className="flex items-center gap-2">
                      <span className={t.done ? "text-emerald-dark" : "text-dark-5"}>
                        {t.done ? "?" : "?"}
                      </span>
                      <span className={`text-sm ${t.done ? "line-through text-dark-5" : "text-dark dark:text-white"}`}>{t.label}</span>
                      {!t.done && <span className="ml-auto text-xs text-amber-dark">Pending</span>}
                    </div>
                  ))}
                </div>
              </div>
            </div>
            <div className="mt-5 flex justify-end">
              <button onClick={() => setDetailRecord(null)} className="btn-secondary">Close</button>
            </div>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

interface Stats {
  totalGross: number;
  totalNet: number;
  totalDeductions: number;
  employeeCount: number;
  month: string;
}

function fmt(n: number) {
  return "₹" + Math.round(n).toLocaleString("en-IN");
}

export function PayrollBreakdown({ stats }: { stats?: Stats }) {
  if (!stats) {
    return (
      <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3 h-full flex items-center justify-center">
        <p className="text-sm text-dark-5 dark:text-dark-6 text-center">No payroll data yet.<br />Run payroll to see breakdown.</p>
      </div>
    );
  }

  const gross = stats.totalGross;
  const deductions = stats.totalDeductions;
  const net = stats.totalNet;

  // Basic = totalGross / 1.5 (since gross = basic + 0.4*basic + 0.1*basic = 1.5*basic)
  const basic = gross / 1.5;
  const hra = basic * 0.4;
  const allowances = basic * 0.1;
  const tax = deductions * (10 / 22);
  const pf = deductions * (12 / 22);

  const earnings = [
    { label: "Basic Salary", amount: basic, pct: (basic / gross) * 100, color: "text-primary-600", barColor: "bg-primary-500" },
    { label: "HRA", amount: hra, pct: (hra / gross) * 100, color: "text-violet-dark", barColor: "bg-violet-500" },
    { label: "Allowances", amount: allowances, pct: (allowances / gross) * 100, color: "text-sky-dark", barColor: "bg-sky-500" },
  ];

  const deductionItems = [
    { label: "Income Tax (TDS)", amount: tax, pct: (tax / deductions) * 100, barColor: "bg-rose-500" },
    { label: "Provident Fund", amount: pf, pct: (pf / deductions) * 100, barColor: "bg-amber-500" },
  ];

  const segments = [
    { pct: Math.round((basic / gross) * 100), color: "#6366F1" },
    { pct: Math.round((hra / gross) * 100), color: "#8B5CF6" },
    { pct: Math.round((allowances / gross) * 100), color: "#0EA5E9" },
  ];
  const r = 38;
  const circumference = 2 * Math.PI * r;
  let offset = 0;

  return (
    <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3 h-full">
      <h3 className="text-sm font-semibold text-dark dark:text-white mb-4">Salary Breakdown</h3>

      <div className="flex items-center justify-center mb-5">
        <div className="relative flex h-28 w-28 items-center justify-center">
          <svg viewBox="0 0 100 100" className="h-full w-full -rotate-90">
            {segments.map((seg, i) => {
              const dashLen = (seg.pct / 100) * circumference;
              const el = (
                <circle
                  key={i}
                  cx={50} cy={50} r={r}
                  fill="none"
                  stroke={seg.color}
                  strokeWidth="14"
                  strokeDasharray={`${dashLen} ${circumference - dashLen}`}
                  strokeDashoffset={(-offset * circumference) / 100}
                />
              );
              offset += seg.pct;
              return el;
            })}
          </svg>
          <div className="absolute flex flex-col items-center">
            <span className="text-sm font-bold text-dark dark:text-white">{fmt(gross)}</span>
            <span className="text-[10px] text-dark-5 dark:text-dark-6">Gross</span>
          </div>
        </div>
      </div>

      <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Earnings</p>
      <div className="space-y-2.5 mb-4">
        {earnings.map((item) => (
          <div key={item.label}>
            <div className="flex items-center justify-between mb-1">
              <span className="text-xs text-dark-5 dark:text-dark-6">{item.label}</span>
              <span className={`text-xs font-semibold ${item.color}`}>{fmt(item.amount)}</span>
            </div>
            <div className="h-1.5 w-full rounded-full bg-gray-3 dark:bg-dark-3 overflow-hidden">
              <div className={`h-full rounded-full ${item.barColor}`} style={{ width: `${item.pct}%` }} />
            </div>
          </div>
        ))}
      </div>

      <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Deductions</p>
      <div className="space-y-2.5 mb-4">
        {deductionItems.map((item) => (
          <div key={item.label}>
            <div className="flex items-center justify-between mb-1">
              <span className="text-xs text-dark-5 dark:text-dark-6">{item.label}</span>
              <span className="text-xs font-semibold text-rose-dark dark:text-rose">{fmt(item.amount)}</span>
            </div>
            <div className="h-1.5 w-full rounded-full bg-gray-3 dark:bg-dark-3 overflow-hidden">
              <div className={`h-full rounded-full ${item.barColor}`} style={{ width: `${item.pct}%` }} />
            </div>
          </div>
        ))}
      </div>

      <div className="rounded-lg bg-emerald-light dark:bg-emerald-dark/20 p-3 text-center">
        <p className="text-xs text-dark-5 dark:text-dark-6">Net Pay</p>
        <p className="text-lg font-bold text-emerald-dark dark:text-emerald">{fmt(net)}</p>
      </div>
    </div>
  );
}

interface PayrollStats {
  totalGross: number;
  totalNet: number;
  totalDeductions: number;
  employeeCount: number;
  month: string;
}

interface KpiCardProps {
  label: string;
  value: string;
  sub: string;
  iconBg: string;
  icon: React.ReactNode;
}

function KpiCard({ label, value, sub, iconBg, icon }: KpiCardProps) {
  return (
    <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-xs text-dark-5 dark:text-dark-6">{label}</p>
          <p className="mt-1 text-2xl font-bold text-dark dark:text-white">{value}</p>
          <p className="mt-0.5 text-xs text-dark-5 dark:text-dark-6">{sub}</p>
        </div>
        <span className={`flex h-10 w-10 items-center justify-center rounded-lg ${iconBg}`}>
          {icon}
        </span>
      </div>
    </div>
  );
}

function fmt(n: number) {
  return "₹" + Math.round(n).toLocaleString("en-IN");
}

export function PayrollKpiCards({ stats }: { stats?: PayrollStats }) {
  const gross = stats ? fmt(stats.totalGross) : "₹—";
  const avg = stats && stats.employeeCount > 0 ? fmt(stats.totalGross / stats.employeeCount) : "₹—";
  const deductions = stats ? fmt(stats.totalDeductions) : "₹—";
  const net = stats ? fmt(stats.totalNet) : "₹—";
  const period = stats?.month ?? "Current";

  return (
    <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
      <KpiCard
        label="Total Payout"
        value={gross}
        sub={period}
        iconBg="bg-primary-50 dark:bg-primary-900/20"
        icon={
          <svg className="h-5 w-5 text-primary-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        }
      />
      <KpiCard
        label="Average Salary"
        value={avg}
        sub={stats ? `${stats.employeeCount} employees` : "per employee"}
        iconBg="bg-emerald-light dark:bg-emerald-dark/20"
        icon={
          <svg className="h-5 w-5 text-emerald-dark" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
          </svg>
        }
      />
      <KpiCard
        label="Deductions"
        value={deductions}
        sub="tax + PF + other"
        iconBg="bg-amber-light dark:bg-amber-dark/20"
        icon={
          <svg className="h-5 w-5 text-amber-dark" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        }
      />
      <KpiCard
        label="Net Pay"
        value={net}
        sub="disbursed this month"
        iconBg="bg-sky-50 dark:bg-sky-dark/10"
        icon={
          <svg className="h-5 w-5 text-sky-dark" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        }
      />
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { runPayroll } from "@/lib/actions/payroll";
import type { SerializedPayrollRun, PayslipRow } from "@/lib/actions/payroll";
import { PayrollKpiCards } from "./PayrollKpiCards";
import { PayrollTable } from "./PayrollTable";
import { PayrollBreakdown } from "./PayrollBreakdown";
import { RecentPayrollRuns } from "./RecentPayrollRuns";

interface PayrollStats {
  totalGross: number;
  totalNet: number;
  totalDeductions: number;
  employeeCount: number;
  month: string;
}

interface Props {
  payrollRuns: SerializedPayrollRun[];
  payslipRows: PayslipRow[];
  latestStats?: PayrollStats;
  isAdmin: boolean;
}

const MONTH_NAMES = ["January","February","March","April","May","June","July","August","September","October","November","December"];

export function PayrollPageClient({ payrollRuns, payslipRows, latestStats, isAdmin }: Props) {
  const router = useRouter();
  const now = new Date();
  const [month, setMonth] = useState(now.getMonth() + 1);
  const year = now.getFullYear();
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [isPending, startTransition] = useTransition();
  const { toast, setToast } = useToast();

  const currentMonthLabel = `${MONTH_NAMES[month - 1]} ${year}`;

  function handleRunPayroll() {
    startTransition(async () => {
      try {
        await runPayroll(month, year);
        setShowConfirmModal(false);
        setToast(`Payroll processed for ${currentMonthLabel}`);
        router.refresh();
      } catch (e) {
        setToast(e instanceof Error ? e.message : "Payroll processing failed");
        setShowConfirmModal(false);
      }
    });
  }

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Payroll</h1>
          <p className="text-muted">Manage and process employee payroll</p>
        </div>
        {isAdmin && (
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2 rounded-lg border border-gray-3 bg-white px-3 py-2 dark:border-dark-3 dark:bg-dark-2">
              <button
                onClick={() => setMonth((m) => Math.max(1, m - 1))}
                className="text-dark-5 hover:text-dark dark:text-dark-6 dark:hover:text-white"
              >
                <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                </svg>
              </button>
              <span className="w-28 text-center text-sm font-semibold text-dark dark:text-white">
                {currentMonthLabel}
              </span>
              <button
                onClick={() => setMonth((m) => Math.min(12, m + 1))}
                className="text-dark-5 hover:text-dark dark:text-dark-6 dark:hover:text-white"
              >
                <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                </svg>
              </button>
            </div>

            <button
              onClick={() => setShowConfirmModal(true)}
              disabled={isPending}
              className="btn-primary flex items-center gap-2 disabled:opacity-60"
            >
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              {isPending ? "Processing…" : "Run Payroll"}
            </button>
          </div>
        )}
      </div>

      {/* KPI Cards */}
      <PayrollKpiCards stats={latestStats} />

      {/* Table + Breakdown */}
      <div className="grid gap-5 lg:grid-cols-12">
        <div className="lg:col-span-8">
          <PayrollTable rows={payslipRows} />
        </div>
        <div className="lg:col-span-4">
          <PayrollBreakdown stats={latestStats} />
        </div>
      </div>

      {/* Recent Runs */}
      {isAdmin && <RecentPayrollRuns runs={payrollRuns} />}

      {/* Run Payroll Modal */}
      {showConfirmModal && (
        <div className="modal-overlay">
          <div className="modal-panel max-w-md p-6">
            <div className="mb-4 flex justify-center">
              <div className="flex h-14 w-14 items-center justify-center rounded-full bg-amber-100 dark:bg-amber-500/20">
                <svg className="h-7 w-7 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z" />
                </svg>
              </div>
            </div>
            <h2 className="mb-2 text-center text-lg font-bold text-dark dark:text-white">
              Run {currentMonthLabel} Payroll?
            </h2>
            <p className="mb-6 text-center text-sm text-dark-5 dark:text-dark-6">
              This will calculate and process payroll for all active employees. This action cannot be undone.
            </p>
            <div className="flex gap-3">
              <button
                onClick={() => setShowConfirmModal(false)}
                className="flex-1 rounded-xl border border-gray-3 px-4 py-2.5 text-sm font-semibold text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6"
              >
                Cancel
              </button>
              <button
                onClick={handleRunPayroll}
                disabled={isPending}
                className="flex-1 rounded-xl bg-amber-500 px-4 py-2.5 text-sm font-semibold text-white hover:bg-amber-600 disabled:opacity-60"
              >
                Yes, Run Payroll
              </button>
            </div>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

