  "", "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

function fmt(val: number) {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 0,
  }).format(val);
}

export interface PayslipData {
  id: string;
  basicSalary: number;
  hra: number;
  allowances: number;
  grossPay: number;
  taxDeduction: number;
  pfDeduction: number;
  otherDeductions: number;
  netPay: number;
  payrollRun: {
    month: number;
    year: number;
    status: string;
  };
  createdAt: string;
}

interface PayslipsClientProps {
  payslips: PayslipData[];
}

export function PayslipsClient({ payslips }: PayslipsClientProps) {
  const { toast, setToast } = useToast();

  const monthLabels = payslips.map(
    (p) => `${MONTH_NAMES[p.payrollRun.month]} ${p.payrollRun.year}`
  );

  const [activeIdx, setActiveIdx] = useState(0);

  const active = payslips[activeIdx];

  // YTD totals
  const ytdGross = payslips.reduce((sum, p) => sum + p.grossPay, 0);
  const ytdNet = payslips.reduce((sum, p) => sum + p.netPay, 0);
  const ytdTax = payslips.reduce((sum, p) => sum + p.taxDeduction, 0);

  if (payslips.length === 0) {
    return (
      <div className="page-container">
        <div className="page-header">
          <div>
            <div className="flex items-center gap-2 text-muted mb-1">
              <Link href="/payroll" className="hover:text-primary-600">Payroll</Link>
              <span>/</span>
              <span>Payslips</span>
            </div>
            <h1 className="page-title">Payslips</h1>
          </div>
        </div>
        <div className="card empty-state">
          <p className="empty-state-text">No payslips found. Payslips will appear here once payroll is processed.</p>
        </div>
      </div>
    );
  }

  const totalDeductions = active.taxDeduction + active.pfDeduction + active.otherDeductions;

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <div className="flex items-center gap-2 text-muted mb-1">
            <Link href="/payroll" className="hover:text-primary-600">Payroll</Link>
            <span>/</span>
            <span>Payslips</span>
          </div>
          <h1 className="page-title">Payslips</h1>
        </div>
        {/* YTD summary */}
        <div className="flex items-center gap-6 text-right">
          <div>
            <p className="text-muted">YTD Gross</p>
            <p className="text-sm font-bold text-dark dark:text-white">{fmt(ytdGross)}</p>
          </div>
          <div>
            <p className="text-muted">YTD Net</p>
            <p className="text-sm font-bold text-emerald-600 dark:text-emerald">{fmt(ytdNet)}</p>
          </div>
          <div>
            <p className="text-muted">YTD Tax</p>
            <p className="text-sm font-bold text-rose-600 dark:text-rose">{fmt(ytdTax)}</p>
          </div>
        </div>
      </div>

      <div className="grid gap-5 lg:grid-cols-12">
        {/* Month List */}
        <div className="lg:col-span-3">
          <div className="card overflow-hidden">
            <div className="p-4 divider">
              <p className="section-title">Select Period</p>
            </div>
            <div className="p-2">
              {monthLabels.map((label, idx) => (
                <button
                  key={payslips[idx].id}
                  onClick={() => setActiveIdx(idx)}
                  className={`w-full rounded-lg px-4 py-2.5 text-left text-sm transition-colors ${
                    activeIdx === idx
                      ? "bg-primary-600 font-semibold text-white"
                      : "border border-gray-3 text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6"
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Payslip Document */}
        <div className="lg:col-span-9">
          <div className="card overflow-hidden">
            {/* Payslip Header */}
            <div className="divider bg-gray-1 p-6 dark:bg-dark-3">
              <div className="flex flex-wrap items-start justify-between gap-4">
                <div>
                  <h2 className="text-lg font-bold text-dark dark:text-white">Your Organisation</h2>
                  <p className="text-muted">Payroll document</p>
                </div>
                <div className="text-right">
                  <p className="text-body-medium">PAYSLIP</p>
                  <p className="text-muted">
                    {MONTH_NAMES[active.payrollRun.month]} {active.payrollRun.year}
                  </p>
                  <p className="text-muted">
                    Status:{" "}
                    <span className="font-semibold capitalize">{active.payrollRun.status.toLowerCase()}</span>
                  </p>
                </div>
              </div>
            </div>

            <div className="p-6 space-y-5">
              {/* Period label */}
              <div>
                <p className="text-muted">
                  Pay Period:{" "}
                  <span className="font-semibold text-dark dark:text-white">
                    {MONTH_NAMES[active.payrollRun.month]} {active.payrollRun.year}
                  </span>
                </p>
              </div>

              {/* Earnings & Deductions side by side */}
              <div className="grid gap-5 md:grid-cols-2">
                {/* Earnings */}
                <div>
                  <p className="mb-3 text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Earnings</p>
                  <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="thead-row">
                        <th className="px-3 py-2 text-left text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Component</th>
                        <th className="px-3 py-2 text-right text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Amount</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr className="tr-body">
                        <td className="px-3 py-2 text-dark dark:text-white">Basic Salary</td>
                        <td className="px-3 py-2 text-right font-medium text-emerald-dark dark:text-emerald">{fmt(active.basicSalary)}</td>
                      </tr>
                      <tr className="tr-body">
                        <td className="px-3 py-2 text-dark dark:text-white">HRA</td>
                        <td className="px-3 py-2 text-right font-medium text-emerald-dark dark:text-emerald">{fmt(active.hra)}</td>
                      </tr>
                      <tr className="tr-body">
                        <td className="px-3 py-2 text-dark dark:text-white">Allowances</td>
                        <td className="px-3 py-2 text-right font-medium text-emerald-dark dark:text-emerald">{fmt(active.allowances)}</td>
                      </tr>
                      <tr className="thead-row">
                        <td className="px-3 py-2 text-sm font-bold text-dark dark:text-white">Gross Earnings</td>
                        <td className="px-3 py-2 text-right text-sm font-bold text-dark dark:text-white">{fmt(active.grossPay)}</td>
                      </tr>
                    </tbody>
                  </table>
                  </div>
                </div>

                {/* Deductions */}
                <div>
                  <p className="mb-3 text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Deductions</p>
                  <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="thead-row">
                        <th className="px-3 py-2 text-left text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Component</th>
                        <th className="px-3 py-2 text-right text-xs font-semibold uppercase tracking-wide text-dark-5 dark:text-dark-6">Amount</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr className="tr-body">
                        <td className="px-3 py-2 text-dark dark:text-white">Provident Fund</td>
                        <td className="px-3 py-2 text-right font-medium text-rose-dark dark:text-rose">{fmt(active.pfDeduction)}</td>
                      </tr>
                      <tr className="tr-body">
                        <td className="px-3 py-2 text-dark dark:text-white">Income Tax (TDS)</td>
                        <td className="px-3 py-2 text-right font-medium text-rose-dark dark:text-rose">{fmt(active.taxDeduction)}</td>
                      </tr>
                      {active.otherDeductions > 0 && (
                        <tr className="tr-body">
                          <td className="px-3 py-2 text-dark dark:text-white">Other Deductions</td>
                          <td className="px-3 py-2 text-right font-medium text-rose-dark dark:text-rose">{fmt(active.otherDeductions)}</td>
                        </tr>
                      )}
                      <tr className="thead-row">
                        <td className="px-3 py-2 text-sm font-bold text-dark dark:text-white">Total Deductions</td>
                        <td className="px-3 py-2 text-right text-sm font-bold text-rose-dark dark:text-rose">{fmt(totalDeductions)}</td>
                      </tr>
                    </tbody>
                  </table>
                  </div>
                </div>
              </div>

              {/* Net Pay */}
              <div className="rounded-xl border-2 border-primary-600 bg-primary-50 p-5 dark:bg-primary-900/10">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-muted">Net Pay (Take Home)</p>
                    <p className="text-3xl font-bold text-dark dark:text-white mt-1">{fmt(active.netPay)}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-muted">Pay Period</p>
                    <p className="text-body-medium">
                      {MONTH_NAMES[active.payrollRun.month]} {active.payrollRun.year}
                    </p>
                    <p className="text-muted mt-1">Mode: Bank Transfer</p>
                  </div>
                </div>
              </div>

              {/* Actions */}
              <div className="flex flex-wrap gap-3 divider pt-4">
                <button
                  onClick={() => {
                    const period = `${MONTH_NAMES[active.payrollRun.month]} ${active.payrollRun.year}`;
                    const html = `<!DOCTYPE html><html><head><title>Payslip – ${period}</title>
<style>body{font-family:Arial,sans-serif;padding:32px;color:#111}h1{font-size:20px;margin:0}p{margin:4px 0;color:#555;font-size:13px}table{width:100%;border-collapse:collapse;margin-top:12px;font-size:13px}th{text-align:left;background:#f3f4f6;padding:8px 10px;font-size:11px;text-transform:uppercase;letter-spacing:.05em}td{padding:8px 10px;border-bottom:1px solid #e5e7eb}.tr{font-weight:700;background:#f9fafb}.net{background:#eff6ff;padding:16px;border-radius:8px;border:2px solid #4f46e5;margin-top:16px;display:flex;justify-content:space-between}.amt{font-size:24px;font-weight:700}@media print{body{padding:16px}}</style></head><body>
<h1>Payslip</h1><p>${period}</p><p>Status: ${active.payrollRun.status}</p>
<table><tr><th>Earnings</th><th style="text-align:right">Amount</th></tr>
<tr><td>Basic Salary</td><td style="text-align:right">${fmt(active.basicSalary)}</td></tr>
<tr><td>HRA</td><td style="text-align:right">${fmt(active.hra)}</td></tr>
<tr><td>Allowances</td><td style="text-align:right">${fmt(active.allowances)}</td></tr>
<tr class="tr"><td>Gross Earnings</td><td style="text-align:right">${fmt(active.grossPay)}</td></tr></table>
<table style="margin-top:16px"><tr><th>Deductions</th><th style="text-align:right">Amount</th></tr>
<tr><td>Provident Fund</td><td style="text-align:right">${fmt(active.pfDeduction)}</td></tr>
<tr><td>Income Tax (TDS)</td><td style="text-align:right">${fmt(active.taxDeduction)}</td></tr>
${active.otherDeductions > 0 ? `<tr><td>Other Deductions</td><td style="text-align:right">${fmt(active.otherDeductions)}</td></tr>` : ""}
<tr class="tr"><td>Total Deductions</td><td style="text-align:right">${fmt(active.taxDeduction + active.pfDeduction + active.otherDeductions)}</td></tr></table>
<div class="net"><div><p>Net Pay (Take Home)</p><div class="amt">${fmt(active.netPay)}</div></div><div style="text-align:right"><p>Pay Period</p><p>${period}</p></div></div>
<script>window.onload=()=>{window.print()}</script></body></html>`;
                    const w = window.open("", "_blank");
                    if (w) { w.document.write(html); w.document.close(); }
                  }}
                  className="btn-primary flex items-center gap-2"
                >
                  <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                  </svg>
                  Download PDF
                </button>
                <button
                  onClick={() => typeof window !== "undefined" && window.print()}
                  className="btn-secondary flex items-center gap-2"
                >
                  <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                  </svg>
                  Print
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { submitClaim, approveClaim } from "@/lib/actions/reimbursements";

type ClaimItem = {
  id: string;
  employeeName: string;
  category: string;
  amount: number;
  date: string;
  description: string;
  status: string;
};

const STATUS_BADGE: Record<string, string> = {
  PENDING: "badge-warning",
  APPROVED: "badge-success",
  REJECTED: "badge-error",
};

const CATEGORY_COLOR: Record<string, string> = {
  TRAVEL: "badge-info",
  MEALS: "badge-success",
  EQUIPMENT: "badge-ai",
  MEDICAL: "badge-error",
  TRAINING: "badge-warning",
  OTHER: "badge-gray",
};

export function ReimbursementsClient({
  claims,
  isAdmin,
  pendingTotal,
  approvedTotal,
}: Readonly<{
  claims: ClaimItem[];
  isAdmin: boolean;
  pendingTotal: number;
  approvedTotal: number;
}>) {
  const router = useRouter();
  const { toast, setToast } = useToast();
  const [showModal, setShowModal] = useState(false);
  const [filterCategory, setFilterCategory] = useState("All");
  const [filterStatus, setFilterStatus] = useState("All");
  const [form, setForm] = useState({ category: "TRAVEL", amount: "", date: "", description: "" });
  const [submitting, setSubmitting] = useState(false);

  const update = (k: string, v: string) => setForm((p) => ({ ...p, [k]: v }));

  const filtered = claims.filter((c) => {
    const catMatch = filterCategory === "All" || c.category === filterCategory;
    const statusMatch = filterStatus === "All" || c.status === filterStatus;
    return catMatch && statusMatch;
  });

  async function handleSubmit() {
    if (!form.amount || !form.date || !form.description) {
      setToast("Please fill all required fields");
      return;
    }
    setSubmitting(true);
    try {
      await submitClaim({ category: form.category as "TRAVEL" | "MEALS" | "EQUIPMENT" | "MEDICAL" | "TRAINING" | "OTHER", amount: Number(form.amount), date: form.date, description: form.description });
      setShowModal(false);
      setForm({ category: "TRAVEL", amount: "", date: "", description: "" });
      setToast("Claim submitted successfully!");
      router.refresh();
    } catch {
      setToast("Failed to submit claim. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  async function handleApprove(id: string) {
    try {
      await approveClaim(id);
      setToast("Claim approved!");
      router.refresh();
    } catch {
      setToast("Failed to approve claim.");
    }
  }

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Reimbursements</h1>
          <p className="mt-0.5 text-muted">Expense claims · Live data</p>
        </div>
        <button
          onClick={() => setShowModal(true)}
          className="btn-primary flex items-center gap-2"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          Submit Claim
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        {[
          { label: "Pending Claims", value: claims.filter((c) => c.status === "PENDING").length, sub: `₹${pendingTotal.toLocaleString("en-IN")} awaiting review`, color: "text-amber-dark", bg: "bg-amber-light dark:bg-amber-dark/20", icon: "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" },
          { label: "Approved", value: claims.filter((c) => c.status === "APPROVED").length, sub: `₹${approvedTotal.toLocaleString("en-IN")} approved`, color: "text-emerald-dark dark:text-emerald", bg: "bg-emerald-light dark:bg-emerald-dark/20", icon: "M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" },
          { label: "Total Claims", value: claims.length, sub: "All time", color: "text-primary-600 dark:text-primary-300", bg: "bg-primary-50 dark:bg-primary-900/20", icon: "M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" },
        ].map((s) => (
          <div key={s.label} className="card-p">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-muted">{s.label}</p>
                <p className="mt-1 text-2xl font-bold text-dark dark:text-white">{s.value}</p>
                <p className={`mt-0.5 text-xs ${s.color}`}>{s.sub}</p>
              </div>
              <span className={`flex h-10 w-10 items-center justify-center rounded-lg ${s.bg}`}>
                <svg className={`h-5 w-5 ${s.color}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={s.icon} />
                </svg>
              </span>
            </div>
          </div>
        ))}
      </div>

      {/* Table */}
      <div className="card overflow-hidden">
        <div className="page-header divider p-5">
          <h3 className="section-title">All Claims</h3>
          <div className="flex items-center gap-2">
            <select
              value={filterCategory}
              onChange={(e) => setFilterCategory(e.target.value)}
              className="input-field h-9"
            >
              <option value="All">All Categories</option>
              <option value="TRAVEL">Travel</option>
              <option value="MEALS">Meals</option>
              <option value="EQUIPMENT">Equipment</option>
              <option value="MEDICAL">Medical</option>
              <option value="TRAINING">Training</option>
            </select>
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="input-field h-9"
            >
              <option value="All">All Status</option>
              <option value="PENDING">Pending</option>
              <option value="APPROVED">Approved</option>
              <option value="REJECTED">Rejected</option>
            </select>
          </div>
        </div>

        {filtered.length === 0 ? (
          <div className="px-5 py-10 text-center text-sm text-dark-5 dark:text-dark-6">No claims found.</div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="thead-row">
                  <th className="th">Employee</th>
                  <th className="th">Category</th>
                  <th className="th text-right">Amount</th>
                  <th className="th">Date</th>
                  <th className="th">Description</th>
                  <th className="th">Status</th>
                  {isAdmin && <th className="th">Action</th>}
                </tr>
              </thead>
              <tbody>
                {filtered.map((claim) => (
                  <tr key={claim.id} className="tr-body">
                    <td className="td font-medium">{claim.employeeName}</td>
                    <td className="td">
                      <span className={CATEGORY_COLOR[claim.category] ?? CATEGORY_COLOR.OTHER}>
                        {claim.category.charAt(0) + claim.category.slice(1).toLowerCase()}
                      </span>
                    </td>
                    <td className="td text-right font-semibold">
                      ₹{claim.amount.toLocaleString("en-IN")}
                    </td>
                    <td className="td text-dark-5 dark:text-dark-6">
                      {new Date(claim.date).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                    </td>
                    <td className="td max-w-[200px] truncate text-dark-5 dark:text-dark-6" title={claim.description}>
                      {claim.description}
                    </td>
                    <td className="td">
                      <span className={STATUS_BADGE[claim.status] ?? STATUS_BADGE.PENDING}>{claim.status}</span>
                    </td>
                    {isAdmin && (
                      <td className="td">
                        {claim.status === "PENDING" && (
                          <button
                            onClick={() => handleApprove(claim.id)}
                            className="rounded-lg bg-emerald-light px-3 py-1.5 text-xs font-medium text-emerald-dark hover:bg-emerald-100 dark:bg-emerald-dark/20 dark:text-emerald"
                          >
                            Approve
                          </button>
                        )}
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Submit Modal */}
      {showModal && (
        <div className="modal-overlay">
          <div className="modal-panel max-w-md p-6">
            <div className="mb-5 flex items-center justify-between">
              <h3 className="section-title">Submit Reimbursement Claim</h3>
              <button onClick={() => setShowModal(false)} className="text-dark-5 hover:text-dark dark:text-dark-6">
                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="label-field">Category</label>
                <select value={form.category} onChange={(e) => update("category", e.target.value)} className="input-field h-9 w-full">
                  <option value="TRAVEL">Travel</option>
                  <option value="MEALS">Meals</option>
                  <option value="EQUIPMENT">Equipment</option>
                  <option value="MEDICAL">Medical</option>
                  <option value="TRAINING">Training</option>
                  <option value="OTHER">Other</option>
                </select>
              </div>
              <div>
                <label className="label-field">Amount (₹)</label>
                <input type="number" placeholder="Enter amount" value={form.amount} onChange={(e) => update("amount", e.target.value)} className="input-field h-9 w-full" />
              </div>
              <div>
                <label className="label-field">Date</label>
                <input type="date" value={form.date} onChange={(e) => update("date", e.target.value)} className="input-field h-9 w-full" />
              </div>
              <div>
                <label className="label-field">Description</label>
                <textarea rows={3} placeholder="Describe the expense..." value={form.description} onChange={(e) => update("description", e.target.value)} className="input-field w-full resize-none py-2" />
              </div>
              <div className="flex gap-3 pt-2">
                <button onClick={() => setShowModal(false)} className="btn-secondary flex-1">Cancel</button>
                <button onClick={handleSubmit} disabled={submitting} className="btn-primary flex-1 disabled:opacity-60">
                  {submitting ? "Submitting..." : "Submit Claim"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState, useTransition, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import Link from "next/link";
import { createGoal, scheduleReview } from "@/lib/actions/performance";
import { ScoreCard } from "./score-card";
import { GoalsList } from "./goals-list";
import { ReviewsTab } from "./tabs/reviews-tab";
import { TeamTab } from "./tabs/team-tab";
import { AnalyticsTab } from "./tabs/analytics-tab";
import { ScheduleReviewModal } from "./schedule-review-modal";
import type { SerializedGoal, SerializedReview, TeamPerformanceSummary } from "@/lib/actions/performance";

type Tab = "goals" | "reviews" | "team" | "analytics";

const TABS: { id: Tab; label: string }[] = [
  { id: "goals", label: "Goals" },
  { id: "reviews", label: "Reviews" },
  { id: "team", label: "Team" },
  { id: "analytics", label: "Analytics" },
];

type PerformancePageClientProps = {
  goals: readonly SerializedGoal[];
  reviews: readonly SerializedReview[];
  teamData: TeamPerformanceSummary | null;
};

function getGoalMetrics(goals: readonly SerializedGoal[]) {
  const totalGoals = goals.length;
  const completedGoals = goals.filter((goal) => goal.status === "COMPLETED").length;
  const inProgressGoals = goals.filter((goal) => goal.status === "IN_PROGRESS").length;
  const completionPct = totalGoals > 0 ? Math.round((completedGoals / totalGoals) * 100) : 0;

  return { totalGoals, completedGoals, inProgressGoals, completionPct };
}

function getLatestScore(reviews: readonly SerializedReview[]): number | null {
  return reviews.find((review) => review.score !== null)?.score ?? null;
}

export function PerformancePageClient({ goals: initialGoals, reviews, teamData }: Readonly<PerformancePageClientProps>) {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<Tab>("goals");
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [showGoalModal, setShowGoalModal] = useState(false);
  const [goals, setGoals] = useState(initialGoals);
  const [isPending, startTransition] = useTransition();
  const { toast, setToast } = useToast();

  useEffect(() => { setGoals(initialGoals); }, [initialGoals]);

  const { totalGoals, completedGoals, inProgressGoals, completionPct } = getGoalMetrics(goals);
  const completedReviews = reviews.filter((review) => review.status === "COMPLETED").length;
  const latestScore = getLatestScore(reviews);
  const latestReview = reviews[0];

  function handleCreateGoal(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    startTransition(async () => {
      try {
        await createGoal({
          title: fd.get("title") as string,
          description: (fd.get("description") as string) || undefined,
          dueDate: (fd.get("dueDate") as string) || undefined,
        });
        setShowGoalModal(false);
        setToast("Goal created successfully!");
        router.refresh();
      } catch (err) {
        setToast(err instanceof Error ? err.message : "Failed to create goal");
      }
    });
  }

  function handleScheduleReviewSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);

    startTransition(async () => {
      try {
        await scheduleReview({
          type: fd.get("type") as string,
          period: fd.get("period") as string,
          notes: (fd.get("notes") as string) || undefined,
        });
        setShowReviewModal(false);
        setToast("Review scheduled successfully!");
        router.refresh();
      } catch (err) {
        setToast(err instanceof Error ? err.message : "Failed to schedule review");
      }
    });
  }

  return (
    <div className="page-container">
      <nav className="flex items-center gap-1.5 text-xs text-dark-5 dark:text-dark-6">
        <Link href="/dashboard" className="hover:text-dark dark:hover:text-white transition-colors">Dashboard</Link>
        <span>/</span>
        <span className="text-dark dark:text-white font-medium">Performance</span>
      </nav>

      <div className="page-header">
        <div>
          <h1 className="page-title">Performance</h1>
          <p className="mt-0.5 text-muted text-sm">Track goals, reviews, and team performance</p>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setShowReviewModal(true)} className="btn-secondary">Schedule Review</button>
          <button onClick={() => setShowGoalModal(true)} className="btn-primary">Set New Goal</button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
        <div className="card-p">
          <p className="text-muted">My Score</p>
          <div className="mt-2 flex items-end gap-1">
            <span className="text-3xl font-bold text-primary-600">{latestScore ?? "—"}</span>
            {latestScore && <span className="mb-1 text-muted">/ 100</span>}
          </div>
          <span className="mt-1 badge-ai">
            {latestReview ? new Date(latestReview.createdAt).toLocaleDateString("en-US", { month: "short", year: "numeric" }) : "No review yet"}
          </span>
        </div>
        <div className="card-p">
          <p className="text-muted">Goals Completed</p>
          <div className="mt-2 flex items-end gap-1">
            <span className="text-3xl font-bold text-emerald-600">{completedGoals}</span>
            <span className="mb-1 text-muted">/ {totalGoals}</span>
          </div>
          <span className="mt-1 badge-success">{completionPct}% completion rate</span>
        </div>
        <div className="card-p">
          <p className="text-muted">Reviews Done</p>
          <div className="mt-2">
            <span className="text-3xl font-bold text-violet-600">{completedReviews}</span>
          </div>
          <span className="mt-1 badge-ai">{reviews.length} total</span>
        </div>
        <div className="card-p">
          <p className="text-muted">In Progress Goals</p>
          <div className="mt-2 flex items-end gap-1">
            <span className="text-3xl font-bold text-amber-600">{inProgressGoals}</span>
            <span className="mb-1 text-muted">active</span>
          </div>
          <span className="mt-1 badge-warning">of {totalGoals} total</span>
        </div>
      </div>

      <div className="border-b border-gray-3 dark:border-dark-3 flex gap-6">
        {TABS.map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`pb-3 text-sm font-medium transition-colors ${
              activeTab === tab.id
                ? "border-b-2 border-primary-600 text-primary-600 dark:text-primary-400"
                : "border-b-2 border-transparent text-dark-5 hover:text-dark dark:text-dark-6 dark:hover:text-white"
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === "goals" && (
        <div className="space-y-5">
          <ScoreCard score={latestScore} reviews={reviews} />
          <GoalsList goals={goals} setToast={setToast} />
        </div>
      )}
      {activeTab === "reviews" && <ReviewsTab reviews={reviews} />}
      {activeTab === "team" && <TeamTab teamData={teamData} />}
      {activeTab === "analytics" && <AnalyticsTab teamData={teamData} />}

      {showReviewModal && (
        <ScheduleReviewModal
          onClose={() => setShowReviewModal(false)}
          isPending={isPending}
          onSubmit={handleScheduleReviewSubmit}
        />
      )}

      {showGoalModal && (
        <div className="modal-overlay">
          <div className="modal-panel max-w-lg p-6">
            <div className="mb-5 flex items-center justify-between">
              <h2 className="text-lg font-bold text-dark dark:text-white">Set New Goal</h2>
              <button onClick={() => setShowGoalModal(false)} className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
                <svg className="size-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <form onSubmit={handleCreateGoal} className="space-y-4">
              <div>
                <label htmlFor="goal-title" className="label-field">Goal Title <span className="text-rose-500">*</span></label>
                <input id="goal-title" name="title" type="text" required placeholder="Enter goal title" className="input-field" />
              </div>
              <div>
                <label htmlFor="goal-due-date" className="label-field">Target Date</label>
                <input id="goal-due-date" name="dueDate" type="date" className="input-field" />
              </div>
              <div>
                <label htmlFor="goal-description" className="label-field">Description</label>
                <textarea id="goal-description" name="description" rows={2} placeholder="Describe the goal..." className="input-field resize-none" />
              </div>
              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowGoalModal(false)} className="btn-secondary">Cancel</button>
                <button type="submit" disabled={isPending} className="btn-primary disabled:opacity-60">
                  {isPending ? "Creating…" : "Create Goal"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { updateGoalProgress } from "@/lib/actions/performance";
import type { SerializedGoal } from "@/lib/actions/performance";

interface GoalsListProps {
  goals: readonly SerializedGoal[];
  setToast: (msg: string) => void;
}

const statusConfig: Record<string, { badge: string; bar: string; label: string }> = {
  COMPLETED: {
    badge: "rounded-full bg-primary-50 px-2.5 py-0.5 text-xs font-medium text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
    bar: "bg-primary-500",
    label: "Completed",
  },
  IN_PROGRESS: {
    badge: "rounded-full bg-emerald-light px-2.5 py-0.5 text-xs font-medium text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
    bar: "bg-emerald-500",
    label: "In Progress",
  },
  NOT_STARTED: {
    badge: "rounded-full bg-rose-light px-2.5 py-0.5 text-xs font-medium text-rose-dark",
    bar: "bg-gray-300",
    label: "Not Started",
  },
  AT_RISK: {
    badge: "rounded-full bg-amber-light px-2.5 py-0.5 text-xs font-medium text-amber-dark",
    bar: "bg-amber-500",
    label: "At Risk",
  },
};

function formatDate(date: string): string {
  return new Date(date).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

export function GoalsList({ goals, setToast }: Readonly<GoalsListProps>) {
  const router = useRouter();
  const [, startTransition] = useTransition();
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState(0);

  function startEdit(goalId: string, current: number) {
    setEditingId(goalId);
    setEditValue(current);
  }

  function handleSave(goalId: string) {
    const clamped = Math.min(100, Math.max(0, editValue));
    setEditingId(null);
    startTransition(async () => {
      try {
        await updateGoalProgress(goalId, clamped);
        setToast("Goal progress updated!");
        router.refresh();
      } catch {
        setToast("Failed to update progress");
      }
    });
  }

  if (goals.length === 0) {
    return (
      <div className="rounded-xl bg-white p-12 text-center shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
        <p className="text-sm font-medium text-dark dark:text-white">No goals yet</p>
        <p className="mt-1 text-xs text-dark-5 dark:text-dark-6">Set your first goal to get started.</p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 gap-3 xl:grid-cols-2">
      {goals.map((goal) => {
        const sc = statusConfig[goal.status] ?? statusConfig.IN_PROGRESS;
        const isEditing = editingId === goal.id;
        return (
          <div key={goal.id} className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
            <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
              <div className="flex-1 min-w-0">
                <div className="flex flex-wrap items-center gap-2 mb-2">
                  <h3 className="text-sm font-semibold text-dark dark:text-white">{goal.title}</h3>
                  <span className={sc.badge}>{sc.label}</span>
                </div>

                {isEditing ? (
                  <div className="flex items-center gap-2">
                    <input
                      type="number"
                      min={0}
                      max={100}
                      value={editValue}
                      onChange={(e) => setEditValue(Number(e.target.value))}
                      className="input-field w-20 py-1 text-sm"
                      autoFocus
                    />
                    <span className="text-xs text-dark-5 dark:text-dark-6">%</span>
                    <button onClick={() => handleSave(goal.id)} className="btn-primary py-1 px-3 text-xs">Save</button>
                    <button onClick={() => setEditingId(null)} className="btn-secondary py-1 px-3 text-xs">Cancel</button>
                  </div>
                ) : (
                  <div className="flex items-center gap-3">
                    <div className="flex-1 h-2 overflow-hidden rounded-full bg-gray-2 dark:bg-dark-3">
                      <div className={`h-full rounded-full ${sc.bar} transition-all`} style={{ width: `${goal.progress}%` }} />
                    </div>
                    <span className="text-xs font-semibold text-dark dark:text-white w-10 text-right">{goal.progress}%</span>
                    <button
                      onClick={() => startEdit(goal.id, goal.progress)}
                      className="flex size-6 items-center justify-center rounded text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
                      title="Update progress"
                    >
                      <svg className="size-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                      </svg>
                    </button>
                  </div>
                )}
              </div>

              {goal.dueDate && (
                <div className="flex flex-col items-start sm:items-end gap-1 text-xs text-dark-5 dark:text-dark-6 flex-shrink-0 sm:ml-4">
                  <span>Due {formatDate(goal.dueDate)}</span>
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

import type { SerializedReview } from "@/lib/actions/performance";

interface Props {
  score: number | null;
  reviews: readonly SerializedReview[];
}

function getScoreLabel(score: number | null): string {
  if (score === null) return "No Reviews Yet";
  if (score >= 90) return "Outstanding";
  if (score >= 80) return "Excellent";
  if (score >= 70) return "Good";
  return "Needs Improvement";
}

export function ScoreCard({ score, reviews }: Readonly<Props>) {
  const displayScore = score ?? 0;
  const scoreText = score === null ? "--" : String(score);
  const circumference = 2 * Math.PI * 54;
  const offset = circumference - (displayScore / 100) * circumference;
  const completedReviews = reviews.filter((r) => r.status === "COMPLETED").length;
  const latestReview = reviews.find((r) => r.score !== null);

  return (
    <div
      className="rounded-xl p-6 text-white"
      style={{ background: "linear-gradient(135deg, #4F46E5, #8B5CF6)" }}
    >
      <div className="flex flex-col gap-6 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex items-center gap-5">
          <div className="relative flex-shrink-0">
            <svg width="112" height="112" viewBox="0 0 128 128">
              <circle cx="64" cy="64" r="54" fill="none" stroke="rgba(255,255,255,0.2)" strokeWidth="10" />
              <circle
                cx="64" cy="64" r="54"
                fill="none"
                stroke="white"
                strokeWidth="10"
                strokeDasharray={circumference}
                strokeDashoffset={offset}
                strokeLinecap="round"
                transform="rotate(-90 64 64)"
              />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span className="text-3xl font-bold text-white">{scoreText}</span>
              {score !== null && <span className="text-xs text-white/70">/ 100</span>}
            </div>
          </div>

          <div>
            <p className="text-sm font-medium text-white/70">Overall Performance Score</p>
            <h2 className="mt-1 text-2xl font-bold text-white">{getScoreLabel(score)}</h2>
            <p className="mt-1 text-xs text-white/60">
              {latestReview
                ? `Last reviewed ${new Date(latestReview.createdAt).toLocaleDateString("en-US", { month: "long", year: "numeric" })}`
                : "No performance reviews yet"}
            </p>
          </div>
        </div>

        <div className="flex flex-wrap gap-6 sm:gap-8">
          {[
            { label: "Reviews", value: completedReviews, suffix: " done" },
            { label: "Total", value: reviews.length, suffix: " total" },
          ].map((item) => (
            <div key={item.label} className="text-center min-w-[64px]">
              <div className="text-2xl font-bold text-white">{item.value}{item.suffix}</div>
              <div className="mt-0.5 text-xs text-white/70">{item.label}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import Link from "next/link";
import type { TeamPerformanceSummary } from "@/lib/actions/performance";

interface Props {
  teamData: TeamPerformanceSummary | null;
}

export function AnalyticsTab({ teamData }: Readonly<Props>) {
  if (!teamData) {
    return (
      <div className="card-p py-10 text-center">
        <p className="text-sm text-dark-5 dark:text-dark-6">Analytics data unavailable.</p>
      </div>
    );
  }

  const maxDistCount = Math.max(...teamData.distribution.map((d) => d.count), 1);

  const metrics = [
    { label: "Team Avg Score", value: teamData.avgScore > 0 ? String(teamData.avgScore) : "—", sub: `${teamData.topPerformers.length} scored`, color: "text-primary-600" },
    { label: "On-Track Goals", value: `${teamData.onTrackGoals}/${teamData.totalGoals}`, sub: teamData.totalGoals > 0 ? `${Math.round((teamData.onTrackGoals / teamData.totalGoals) * 100)}% on track` : "No goals yet", color: "text-emerald-600" },
    { label: "Reviews Done", value: String(teamData.completedReviews), sub: `of ${teamData.totalReviews} total`, color: "text-violet-600" },
    { label: "Need Attention", value: String(teamData.attentionEmployees.length), sub: "score < 75", color: "text-amber-600" },
  ];

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-dark dark:text-white">Performance Analytics</h2>
        <Link href="/performance/analytics" className="btn-primary">Full Analytics →</Link>
      </div>

      <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
        {metrics.map((m) => (
          <div key={m.label} className="card-p">
            <p className="text-muted">{m.label}</p>
            <p className={`mt-2 text-2xl font-bold ${m.color}`}>{m.value}</p>
            <p className="mt-1 text-muted">{m.sub}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 gap-5 md:grid-cols-12">
        <div className="md:col-span-6">
          <div className="card-p">
            <h3 className="mb-4 section-title">Score Distribution</h3>
            {teamData.distribution.every((d) => d.count === 0) ? (
              <p className="text-sm text-dark-5 dark:text-dark-6">No completed reviews to display.</p>
            ) : (
              <>
                <div className="flex items-end gap-4 h-36">
                  {teamData.distribution.map((d) => {
                    const heightPct = (d.count / maxDistCount) * 100;
                    return (
                      <div key={d.bucket} className="flex flex-1 flex-col items-center gap-1">
                        <span className="text-xs font-semibold text-dark dark:text-white">{d.count}</span>
                        <div className="relative w-full flex-1 flex items-end">
                          <div className="w-full rounded-t bg-primary-500" style={{ height: `${heightPct}%` }} />
                        </div>
                        <span className="text-[10px] text-dark-5 dark:text-dark-6 text-center">{d.bucket}</span>
                      </div>
                    );
                  })}
                </div>
                <p className="mt-3 text-muted">{teamData.completedReviews} completed reviews</p>
              </>
            )}
          </div>
        </div>

        <div className="md:col-span-6">
          <div className="card-p">
            <h3 className="mb-4 section-title">Employees Needing Attention</h3>
            <p className="mb-3 text-muted">Below 75 performance score</p>
            {teamData.attentionEmployees.length === 0 ? (
              <p className="text-sm text-emerald-600 dark:text-emerald font-medium">All employees are performing well!</p>
            ) : (
              <div className="space-y-4">
                {teamData.attentionEmployees.map((emp) => (
                  <div key={emp.name} className="flex items-center justify-between gap-3">
                    <div>
                      <p className="text-sm font-semibold text-dark dark:text-white">{emp.name}</p>
                      <p className="text-muted">{emp.dept} &middot; {emp.score}/100</p>
                    </div>
                    <span className="badge-warning flex-shrink-0">Below avg</span>
                  </div>
                ))}
              </div>
            )}
            <div className="mt-4 border-t border-gray-3 pt-4 dark:border-dark-3">
              <Link href="/performance/analytics" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">
                View full analytics report →
              </Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import Link from "next/link";
import type { SerializedReview } from "@/lib/actions/performance";

const TYPE_DISPLAY: Record<string, string> = {
  ANNUAL: "Annual Review",
  MID_YEAR: "Mid-year",
  QUARTERLY: "Quarterly",
  PROBATION: "Probation",
  PEER: "Peer Review",
};

export function ReviewsTab({ reviews }: Readonly<{ reviews: readonly SerializedReview[] }>) {
  if (reviews.length === 0) {
    return (
      <div className="card-p flex flex-col items-center justify-center py-12 text-center">
        <p className="text-sm font-medium text-dark dark:text-white">No reviews yet</p>
        <p className="mt-1 text-xs text-dark-5 dark:text-dark-6">Performance reviews will appear here once they are completed.</p>
      </div>
    );
  }

  const scoreBars = reviews
    .filter((r) => r.score !== null)
    .slice(0, 6)
    .reverse();

  const maxScore = Math.max(...scoreBars.map((r) => r.score ?? 0), 1);

  return (
    <div className="grid grid-cols-1 gap-5 md:grid-cols-12">
      <div className="md:col-span-8">
        <div className="card-p">
          <div className="mb-4 flex items-center justify-between">
            <h2 className="section-title">Review History</h2>
            <Link href="/performance/reviews" className="text-xs font-medium text-primary-600 hover:underline dark:text-primary-400">
              {"View all ->"}
            </Link>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full min-w-[560px] text-sm">
              <thead>
                <tr className="border-b border-gray-3 dark:border-dark-3">
                  {["Date", "Type", "Score", "Reviewer", "Status"].map((h) => (
                    <th key={h} className="pb-3 text-left text-xs font-semibold text-dark-5 dark:text-dark-6 first:pl-0 last:pr-0 px-3">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {reviews.map((row) => (
                  <tr key={row.id} className="border-b border-gray-3 last:border-0 dark:border-dark-3">
                    <td className="py-3 pl-0 pr-3 text-sm font-medium text-dark dark:text-white">
                      {new Date(row.createdAt).toLocaleDateString("en-US", { month: "short", year: "numeric" })}
                    </td>
                    <td className="px-3 py-3 text-muted">{TYPE_DISPLAY[row.type] ?? row.type}</td>
                    <td className="px-3 py-3 text-sm font-semibold text-dark dark:text-white">
                      {row.score === null ? "-" : `${row.score}/100`}
                    </td>
                    <td className="px-3 py-3 text-muted">
                      {row.reviewer ? `${row.reviewer.firstName} ${row.reviewer.lastName}` : "-"}
                    </td>
                    <td className="px-3 py-3">
                      <span className={row.status === "COMPLETED" ? "badge-success" : "badge-warning"}>
                        {row.status === "COMPLETED" ? "Completed" : "Pending"}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <div className="md:col-span-4 flex flex-col gap-4">
        {scoreBars.length > 0 && (
          <div className="card-p">
            <h2 className="mb-4 section-title">Score Trend</h2>
            <div className="flex items-end gap-2 h-32">
              {scoreBars.map((r) => {
                const heightPct = ((r.score ?? 0) / maxScore) * 100;
                return (
                  <div key={r.id} className="flex flex-1 flex-col items-center gap-1">
                    <span className="text-[10px] font-medium text-dark-5 dark:text-dark-6">{r.score}</span>
                    <div className="relative w-full flex-1 flex items-end">
                      <div className="w-full rounded-t bg-primary-600" style={{ height: `${heightPct}%` }} />
                    </div>
                    <span className="text-[10px] text-dark-5 dark:text-dark-6">
                      {new Date(r.createdAt).toLocaleDateString("en-US", { month: "short" })}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {reviews[0]?.comments && (
          <div className="card-p">
            <h2 className="mb-3 section-title">Latest Feedback</h2>
            <p className="text-xs text-dark-5 dark:text-dark-6 italic">&ldquo;{reviews[0].comments}&rdquo;</p>
            <p className="mt-2 text-xs text-dark-5 dark:text-dark-6">
              - {reviews[0].reviewer ? `${reviews[0].reviewer.firstName} ${reviews[0].reviewer.lastName}` : "Reviewer"}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

import Image from "next/image";
import Link from "next/link";
import type { TeamPerformanceSummary } from "@/lib/actions/performance";

const BAR_COLORS = ["bg-primary-600", "bg-primary-500", "bg-primary-400", "bg-emerald-500", "bg-violet-500", "bg-amber-500"];

function getInitials(name: string) {
  return name.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 2);
}

function goalStatusBadge(status: string, progress: number) {
  if (progress >= 80) return "badge-success";
  if (progress >= 50) return "badge-ai";
  return "badge-warning";
}

function goalStatusLabel(status: string, progress: number) {
  if (progress >= 80) return "Near Complete";
  if (progress >= 50) return "In Progress";
  return "Getting Started";
}

function goalBarColor(progress: number) {
  if (progress >= 80) return "bg-emerald-500";
  if (progress >= 50) return "bg-primary-500";
  return "bg-amber-500";
}

interface Props {
  teamData: TeamPerformanceSummary | null;
}

export function TeamTab({ teamData }: Readonly<Props>) {
