"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { createReviewCycle } from "@/lib/actions/performance";

type Review = {
  id: string;
  revieweeName: string;
  revieweeTitle: string;
  revieweeDept: string;
  reviewerName: string;
  period: string;
  type: string;
  score: number | null;
  status: string;
  completedAt: string | null;
};

type FilterStatus = "All" | "PENDING" | "COMPLETED";

const STATUS_BADGE: Record<string, string> = {
  PENDING: "rounded-full bg-amber-light px-2.5 py-0.5 text-xs font-medium text-amber-dark",
  IN_PROGRESS: "rounded-full bg-sky-50 px-2.5 py-0.5 text-xs font-medium text-sky-dark dark:bg-sky-dark/10 dark:text-sky",
  COMPLETED: "rounded-full bg-emerald-light px-2.5 py-0.5 text-xs font-medium text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
};

function getReviewStats(reviews: readonly Review[]) {
  let pending = 0;
  let completed = 0;
  let scoredCount = 0;
  let scoreTotal = 0;

  for (const review of reviews) {
    if (review.status === "PENDING") pending += 1;
    if (review.status === "COMPLETED") completed += 1;

    if (review.score !== null) {
      scoredCount += 1;
      scoreTotal += review.score;
    }
  }

  return {
    pending,
    completed,
    avgScore: scoredCount > 0 ? Math.round(scoreTotal / scoredCount) : 0,
  };
}

function getActivePeriodData(reviews: readonly Review[]) {
  const frequency: Record<string, number> = {};

  for (const review of reviews) {
    if (review.status !== "COMPLETED") {
      frequency[review.period] = (frequency[review.period] ?? 0) + 1;
    }
  }

  const activePeriod =
    Object.entries(frequency)
      .sort((a, b) => b[1] - a[1])[0]?.[0] ?? reviews[0]?.period ?? null;

  const activePeriodReviews = activePeriod
    ? reviews.filter((review) => review.period === activePeriod)
    : [];
  const activePeriodCompleted = activePeriodReviews.filter((review) => review.status === "COMPLETED").length;
  const activePeriodPct = activePeriodReviews.length > 0
    ? Math.round((activePeriodCompleted / activePeriodReviews.length) * 100)
    : 0;

  return {
    activePeriod,
    activePeriodReviews,
    activePeriodCompleted,
    activePeriodPct,
  };
}

function pluralizeReview(count: number): string {
  return `review${count === 1 ? "" : "s"}`;
}

export function ReviewsClient({ reviews }: Readonly<{ reviews: Review[] }>) {
  const router = useRouter();
  const { toast, setToast } = useToast();
  const [showModal, setShowModal] = useState(false);
  const [filterStatus, setFilterStatus] = useState<FilterStatus>("All");
  const [cycleName, setCycleName] = useState("");
  const [reviewType, setReviewType] = useState("Quarterly");
  const [isPending, startTransition] = useTransition();

  function handleCreate() {
    if (!cycleName.trim()) { setToast("Cycle name is required"); return; }
    startTransition(async () => {
      try {
        const result = await createReviewCycle({ period: cycleName.trim(), type: reviewType });
        setShowModal(false);
        setCycleName("");
        setReviewType("Quarterly");
        setToast(`Review cycle created — ${result.created} ${pluralizeReview(result.created)} scheduled`);
        router.refresh();
      } catch (err) {
        setToast(err instanceof Error ? err.message : "Failed to create review cycle");
      }
    });
  }

  const filtered = reviews.filter((review) => filterStatus === "All" || review.status === filterStatus);
  const { pending, completed, avgScore } = getReviewStats(reviews);
  const { activePeriod, activePeriodReviews, activePeriodCompleted, activePeriodPct } = getActivePeriodData(reviews);

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Performance Reviews</h1>
          <p className="text-muted mt-0.5">Manage review cycles and track progress</p>
        </div>
        <button
          onClick={() => setShowModal(true)}
          className="btn-primary"
        >
          + New Review Cycle
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        {[
          { label: "Total Reviews", value: reviews.length, color: "text-primary-600 dark:text-primary-300" },
          { label: "Pending", value: pending, color: "text-amber-dark" },
          { label: "Completed", value: completed, color: "text-emerald-dark dark:text-emerald" },
          { label: "Avg Score", value: avgScore > 0 ? `${avgScore}/100` : "—", color: "text-violet-dark dark:text-violet-300" },
        ].map((s) => (
          <div key={s.label} className="card-p">
            <p className="stat-label">{s.label}</p>
            <p className={`mt-1 text-2xl font-bold ${s.color}`}>{s.value}</p>
          </div>
        ))}
      </div>

      {/* Active cycle banner */}
      {activePeriod && (
        <div className="rounded-xl p-6 text-white" style={{ background: "linear-gradient(135deg, #4F46E5, #8B5CF6)" }}>
          <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
            <div>
              <span className="rounded-full bg-white/20 px-2.5 py-0.5 text-xs font-medium text-white">
                {activePeriodPct === 100 ? "Completed" : "Active"}
              </span>
              <h2 className="mt-1 text-xl font-bold text-white">{activePeriod}</h2>
              <p className="mt-1 text-sm text-white/70">
                {activePeriodCompleted} of {activePeriodReviews.length} reviews completed
              </p>
            </div>
            <button
              onClick={() => router.push("/performance")}
              className="self-start rounded-lg bg-white/20 px-4 py-2 text-sm font-semibold text-white backdrop-blur-sm hover:bg-white/30"
            >
              View My Review
            </button>
          </div>
          <div className="mt-4">
            <div className="mb-1.5 flex justify-between">
              <span className="text-sm text-white/80">Cycle Completion</span>
              <span className="text-sm font-bold text-white">{activePeriodPct}%</span>
            </div>
            <div className="h-2.5 w-full overflow-hidden rounded-full bg-white/20">
              <div className="h-full rounded-full bg-white" style={{ width: `${activePeriodPct}%` }} />
            </div>
          </div>
        </div>
      )}

      {/* Table */}
      <div className="card overflow-hidden">
        <div className="page-header border-b border-gray-3 px-5 py-4 dark:border-dark-3">
          <h2 className="section-title">All Reviews</h2>
          <div className="flex gap-2">
            {(["All", "PENDING", "COMPLETED"] as const).map((s) => (
              <button
                key={s}
                onClick={() => setFilterStatus(s)}
                className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                  filterStatus === s
                    ? "bg-primary-600 text-white"
                    : "border border-gray-3 text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6"
                }`}
              >
                {s === "All" ? "All" : s.charAt(0) + s.slice(1).toLowerCase()}
              </button>
            ))}
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="thead-row">
                <th className="th">Employee</th>
                <th className="th">Period</th>
                <th className="th">Reviewer</th>
                <th className="th">Score</th>
                <th className="th">Status</th>
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr>
                  <td colSpan={5} className="td py-10 text-center text-dark-5 dark:text-dark-6">No reviews found.</td>
                </tr>
              ) : (
                filtered.map((r) => (
                  <tr key={r.id} className="tr-body">
                    <td className="td">
                      <p className="text-body-medium">{r.revieweeName}</p>
                      <p className="text-muted">{r.revieweeTitle} · {r.revieweeDept}</p>
                    </td>
                    <td className="td text-dark-5 dark:text-dark-6">{r.period}</td>
                    <td className="td text-dark-5 dark:text-dark-6">{r.reviewerName}</td>
                    <td className="td">
                      {r.score === null ? (
                        <span className="text-dark-5 dark:text-dark-6">—</span>
                      ) : (
                        <>
                          <span className="font-semibold text-dark dark:text-white">{r.score}</span>
                          <span className="text-dark-5 dark:text-dark-6">/100</span>
                        </>
                      )}
                    </td>
                    <td className="td">
                      <span className={STATUS_BADGE[r.status] ?? STATUS_BADGE.PENDING}>{r.status}</span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal */}
      {showModal && (
        <div className="modal-overlay">
          <div className="modal-panel w-full max-w-md p-6">
            <div className="modal-header mb-5 flex items-center justify-between">
              <h2 className="section-title">Create Review Cycle</h2>
              <button onClick={() => setShowModal(false)} className="flex h-8 w-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
                <svg className="h-4 w-4" viewBox="0 0 24 24" fill="none"><path d="M6 18L18 6M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" /></svg>
              </button>
            </div>
            <div className="space-y-4">
              <div>
                <label htmlFor="cycle-name" className="label-field mb-1.5">Cycle Name <span className="text-rose-500">*</span></label>
                <input id="cycle-name" type="text" value={cycleName} onChange={(e) => setCycleName(e.target.value)} placeholder="e.g. Q3 2026 Review" className="input-field h-9 w-full" />
              </div>
              <div>
                <label htmlFor="review-type" className="label-field mb-1.5">Type</label>
                <select id="review-type" value={reviewType} onChange={(e) => setReviewType(e.target.value)} className="input-field h-9 w-full">
                  <option value="Annual">Annual</option>
                  <option value="Mid-year">Mid-year</option>
                  <option value="Quarterly">Quarterly</option>
                </select>
              </div>
              <p className="text-xs text-dark-5 dark:text-dark-6">This will create a pending review for every active employee, assigned to their manager.</p>
            </div>
            <div className="mt-6 flex justify-end gap-3">
              <button onClick={() => setShowModal(false)} className="btn-secondary" disabled={isPending}>Cancel</button>
              <button onClick={handleCreate} disabled={isPending} className="btn-primary disabled:opacity-60">
                {isPending ? "Creating…" : "Create"}
              </button>
            </div>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

"use client";

import Image from "next/image";
import Breadcrumb from "@/components/layout/breadcrumb";

type Profile = {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  title: string;
  department: string | null;
  avatarUrl: string | null;
  startDate: string;
  employmentType: string;
  goalsDone: number;
  tasksDone: number;
  coursesCount: number;
  certsCount: number;
};

function formatDate(iso: string) {
  return new Date(iso).toLocaleDateString("en-US", { month: "long", year: "numeric" });
}

export function ProfileClient({ profile }: Readonly<{ profile: Profile | null }>) {
  if (!profile) {
    return (
      <div className="mx-auto w-full max-w-[970px]">
        <Breadcrumb pageName="Profile" />
        <div className="card flex h-40 items-center justify-center">
          <p className="text-muted">No employee profile found. Contact HR to set up your profile.</p>
        </div>
      </div>
    );
  }

  const fullName = `${profile.firstName} ${profile.lastName}`;
  const avatar = profile.avatarUrl ?? "/images/user/user-01.png";
  const initials = `${profile.firstName[0]}${profile.lastName[0]}`.toUpperCase();

  return (
    <div className="mx-auto w-full max-w-[970px]">
      <Breadcrumb pageName="Profile" />

      <div className="overflow-hidden rounded-[10px] bg-white shadow-1 dark:bg-gray-dark dark:shadow-card">
        {/* Cover */}
        <div className="relative z-20 h-35 md:h-65">
          <Image
            src="/images/cover/cover-01.png"
            alt="profile cover"
            className="h-full w-full rounded-tl-[10px] rounded-tr-[10px] object-cover object-center"
            width={970}
            height={260}
            style={{ width: "100%", height: "100%" }}
          />
        </div>

        {/* Avatar + Info */}
        <div className="px-4 pb-6 text-center lg:pb-8 xl:pb-11.5">
          <div className="relative z-30 mx-auto -mt-22 h-30 w-full max-w-30 rounded-full bg-white/20 p-1 backdrop-blur sm:h-44 sm:max-w-[176px] sm:p-3">
            <div className="relative">
              {profile.avatarUrl ? (
                <Image
                  src={avatar}
                  width={160}
                  height={160}
                  className="overflow-hidden rounded-full object-cover"
                  alt={fullName}
                />
              ) : (
                <div className="flex h-[160px] w-[160px] items-center justify-center rounded-full bg-primary-100 text-4xl font-bold text-primary-600 dark:bg-primary-900/30 dark:text-primary-300">
                  {initials}
                </div>
              )}
            </div>
          </div>

          <div className="mt-4">
            <h3 className="mb-1 text-heading-6 font-bold text-dark dark:text-white">{fullName}</h3>
            <p className="font-medium text-dark-5 dark:text-dark-6">{profile.title}</p>
            {profile.department && (
              <p className="mt-0.5 text-sm text-muted">{profile.department} · {profile.employmentType}</p>
            )}

            {/* Stats */}
            <div className="mx-auto mb-5.5 mt-5 grid max-w-[420px] grid-cols-4 rounded-[5px] border border-stroke py-[9px] shadow-1 dark:border-dark-3 dark:bg-dark-2 dark:shadow-card">
              {[
                { label: "Goals", value: profile.goalsDone },
                { label: "Tasks", value: profile.tasksDone },
                { label: "Courses", value: profile.coursesCount },
                { label: "Certs", value: profile.certsCount },
              ].map((stat, i, arr) => (
                <div
                  key={stat.label}
                  className={`flex flex-col items-center justify-center gap-1 px-4 xsm:flex-row ${i < arr.length - 1 ? "border-r border-stroke dark:border-dark-3" : ""}`}
                >
                  <span className="font-semibold text-dark dark:text-white">{stat.value}</span>
                  <span className="text-body-sm text-muted">{stat.label}</span>
                </div>
              ))}
            </div>

            {/* About */}
            <div className="mx-auto max-w-[720px]">
              <h4 className="font-medium text-dark dark:text-white">About</h4>
              <div className="mt-4 space-y-1.5 text-sm text-muted">
                <p><span className="font-medium text-dark dark:text-white">Email:</span> {profile.email}</p>
                <p><span className="font-medium text-dark dark:text-white">Department:</span> {profile.department ?? "—"}</p>
                <p><span className="font-medium text-dark dark:text-white">Joined:</span> {formatDate(profile.startDate)}</p>
                <p><span className="font-medium text-dark dark:text-white">Employment:</span> {profile.employmentType}</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { addCandidate, updateCandidateStage } from "@/lib/actions/recruitment";
import type { SerializedCandidate, SerializedJobPosting } from "@/lib/actions/recruitment";

const STAGE_BADGE: Record<string, string> = {
  APPLIED:   "rounded-full bg-primary-50 px-2.5 py-0.5 text-xs font-medium text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
  SCREENING: "rounded-full bg-amber-light px-2.5 py-0.5 text-xs font-medium text-amber-dark",
  INTERVIEW: "rounded-full bg-sky-50 px-2.5 py-0.5 text-xs font-medium text-sky-dark dark:bg-sky-dark/10 dark:text-sky",
  OFFER:     "rounded-full bg-violet-light px-2.5 py-0.5 text-xs font-medium text-violet-dark dark:bg-violet-dark/20 dark:text-violet-300",
  HIRED:     "rounded-full bg-emerald-light px-2.5 py-0.5 text-xs font-medium text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
  REJECTED:  "rounded-full bg-rose-light px-2.5 py-0.5 text-xs font-medium text-rose-dark dark:bg-rose-dark/20 dark:text-rose",
};

interface Props {
  candidates: SerializedCandidate[];
  jobs: SerializedJobPosting[];
}

export function CandidatesClient({ candidates, jobs }: Readonly<Props>) {
  const router = useRouter();
  const { toast, setToast } = useToast();
  const [showModal, setShowModal] = useState(false);
  const [stageFilter, setStageFilter] = useState("All");
  const [isPending, startTransition] = useTransition();

  const stages = ["All", "APPLIED", "SCREENING", "INTERVIEW", "OFFER", "HIRED", "REJECTED"];
  const STAGE_VALUES = ["APPLIED", "SCREENING", "INTERVIEW", "OFFER", "HIRED", "REJECTED"] as const;
  const filtered = stageFilter === "All" ? candidates : candidates.filter((c) => c.stage === stageFilter);

  function handleStageChange(candidateId: string, newStage: typeof STAGE_VALUES[number]) {
    startTransition(async () => {
      try {
        await updateCandidateStage(candidateId, newStage);
        router.refresh();
      } catch {
        setToast("Failed to update stage");
      }
    });
  }

  function handleAdd(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    startTransition(async () => {
      try {
        await addCandidate({
          jobId: fd.get("jobId") as string,
          name: fd.get("name") as string,
          email: fd.get("email") as string,
          phone: (fd.get("phone") as string) || undefined,
          source: (fd.get("source") as string) || undefined,
        });
        setShowModal(false);
        setToast("Candidate added successfully!");
        router.refresh();
      } catch (err) {
        setToast(err instanceof Error ? err.message : "Failed to add candidate");
      }
    });
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <div className="flex items-center gap-2 text-muted mb-1">
            <Link href="/recruitment" className="hover:text-primary-600">Recruitment</Link>
            <span>/</span>
            <span>Candidates</span>
          </div>
          <h1 className="page-title">All Candidates</h1>
          <p className="text-muted">{candidates.length} candidate{candidates.length !== 1 ? "s" : ""} across all stages</p>
        </div>
        <button onClick={() => setShowModal(true)} className="btn-primary flex items-center gap-2">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          Add Candidate
        </button>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        {stages.map((s) => (
          <button
            key={s}
            onClick={() => setStageFilter(s)}
            className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
              stageFilter === s
                ? "bg-primary-600 text-white"
                : "border border-gray-3 text-dark-5 hover:bg-gray-2 dark:border-dark-3 dark:text-dark-6"
            }`}
          >
            {s === "All" ? "All" : s.charAt(0) + s.slice(1).toLowerCase()}
          </button>
        ))}
      </div>

      <div className="card overflow-hidden">
        {filtered.length === 0 ? (
          <div className="p-8 text-center">
            <p className="text-sm text-dark-5 dark:text-dark-6">No candidates found.</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="thead-row">
                  <th className="th">Name</th>
                  <th className="th">Position</th>
                  <th className="th">Source</th>
                  <th className="th">Stage</th>
                  <th className="th">Applied</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((c) => (
                  <tr key={c.id} className="tr-body">
                    <td className="td">
                      <div>
                        <p className="text-body-medium">{c.name}</p>
                        <p className="text-xs text-dark-5 dark:text-dark-6">{c.email}</p>
                      </div>
                    </td>
                    <td className="td text-muted">{c.jobTitle}</td>
                    <td className="td text-muted">{c.source ?? "—"}</td>
                    <td className="td">
                      <select
                        value={c.stage}
                        onChange={(e) => handleStageChange(c.id, e.target.value as typeof STAGE_VALUES[number])}
                        className={`cursor-pointer border-0 bg-transparent p-0 text-xs font-medium focus:outline-none ${STAGE_BADGE[c.stage] ?? STAGE_BADGE.APPLIED}`}
                        disabled={isPending}
                      >
                        {STAGE_VALUES.map((s) => (
                          <option key={s} value={s}>{s.charAt(0) + s.slice(1).toLowerCase()}</option>
                        ))}
                      </select>
                    </td>
                    <td className="td text-muted">
                      {new Date(c.appliedAt).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showModal && (
        <div className="modal-overlay">
          <div className="modal-panel max-w-lg p-6">
            <div className="mb-5 flex items-center justify-between">
              <h2 className="text-lg font-bold text-dark dark:text-white">Add Candidate</h2>
              <button onClick={() => setShowModal(false)} className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
                <svg className="size-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <form onSubmit={handleAdd} className="space-y-4">
              <div>
                <label className="label-field">Position <span className="text-rose-500">*</span></label>
                <select name="jobId" required className="input-field">
                  <option value="">Select a position</option>
                  {jobs.filter((j) => j.isActive).map((j) => (
                    <option key={j.id} value={j.id}>{j.title}</option>
                  ))}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label-field">Full Name <span className="text-rose-500">*</span></label>
                  <input name="name" type="text" required placeholder="John Doe" className="input-field" />
                </div>
                <div>
                  <label className="label-field">Email <span className="text-rose-500">*</span></label>
                  <input name="email" type="email" required placeholder="john@example.com" className="input-field" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label-field">Phone</label>
                  <input name="phone" type="tel" placeholder="+1 234 567 8900" className="input-field" />
                </div>
                <div>
                  <label className="label-field">Source</label>
                  <select name="source" className="input-field">
                    <option value="">Select source</option>
                    {["LinkedIn", "Indeed", "Referral", "Direct", "Other"].map((s) => (
                      <option key={s} value={s}>{s}</option>
                    ))}
                  </select>
                </div>
              </div>
              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)} className="btn-secondary">Cancel</button>
                <button type="submit" disabled={isPending} className="btn-primary disabled:opacity-60">
                  {isPending ? "Adding…" : "Add Candidate"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

import Link from "next/link";
import { getCandidates, getJobPostings } from "@/lib/actions/recruitment";
import { KanbanColumn, type CandidateCard } from "./_components/KanbanColumn";

const STAGE_CONFIG = {
  APPLIED:   { title: "Applied",   headerColor: "bg-primary-50 dark:bg-primary-900/20", dotColor: "bg-primary-500" },
  SCREENING: { title: "Screening", headerColor: "bg-amber-light dark:bg-amber-dark/10", dotColor: "bg-amber-500" },
  INTERVIEW: { title: "Interview", headerColor: "bg-sky-50 dark:bg-sky-dark/10",    dotColor: "bg-sky-500" },
  OFFER:     { title: "Offer",     headerColor: "bg-violet-light dark:bg-violet-dark/10", dotColor: "bg-violet-500" },
  HIRED:     { title: "Hired",     headerColor: "bg-emerald-light dark:bg-emerald-dark/10", dotColor: "bg-emerald-500" },
};

export default async function RecruitmentPage() {
  const [candidates, jobs] = await Promise.all([
    getCandidates().catch(() => []),
    getJobPostings().catch(() => []),
  ]);

  // Group candidates by stage
  const columns = (Object.keys(STAGE_CONFIG) as Array<keyof typeof STAGE_CONFIG>).map((stage) => {
    const stageCandidates = candidates
      .filter((c) => c.stage === stage)
      .map((c): CandidateCard => ({
        id: c.id,
        name: c.name,
        avatar: "/images/user/user-03.png",
        currentRole: c.email,
        appliedFor: c.jobTitle ?? "Unknown Position",
        stageInfo: `Applied ${new Date(c.appliedAt).toLocaleDateString("en-US", { month: "short", day: "numeric" })}`,
      }));
    return { stage, ...STAGE_CONFIG[stage], candidates: stageCandidates };
  });

  const totalCandidates = candidates.length;
  const openJobs = jobs.filter((j) => j.isActive).length;

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Recruitment Pipeline</h1>
          <p className="text-muted">
            <span className="inline-flex items-center gap-1">
              <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
              {openJobs} open position{openJobs !== 1 ? "s" : ""}
            </span>
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Link
            href="/recruitment/jobs"
            className="btn-secondary"
          >
            View Jobs
          </Link>
          <Link
            href="/recruitment/candidates"
            className="btn-secondary"
          >
            All Candidates
          </Link>
        </div>
      </div>

      {/* Pipeline Stats Bar */}
      <div className="card-p">
        <div className="flex flex-wrap items-center gap-6">
          {columns.map((col) => (
            <div key={col.stage} className="flex items-center gap-2">
              <span className={`h-2.5 w-2.5 rounded-full ${col.dotColor}`} />
              <span className="text-muted">{col.title}</span>
              <span className="text-xs font-bold text-dark dark:text-white">{col.candidates.length}</span>
            </div>
          ))}
          <div className="ml-auto text-muted">
            Total: <span className="font-bold text-dark dark:text-white">{totalCandidates} candidate{totalCandidates !== 1 ? "s" : ""}</span>
          </div>
        </div>
        {totalCandidates > 0 && (
          <div className="mt-3 h-2 w-full overflow-hidden rounded-full flex gap-0.5">
            {columns.map((col) => {
              const pct = totalCandidates > 0 ? Math.round((col.candidates.length / totalCandidates) * 100) : 0;
              if (pct === 0) return null;
              return (
                <div
                  key={col.stage}
                  className={col.dotColor.replace("bg-", "bg-")}
                  style={{ width: `${pct}%` }}
                />
              );
            })}
          </div>
        )}
      </div>

      {/* Kanban Board */}
      <div className="overflow-x-auto pb-2">
        <div className="flex gap-4 min-w-max">
          {columns.map((col) => (
            <KanbanColumn
              key={col.stage}
              title={col.title}
              headerColor={col.headerColor}
              dotColor={col.dotColor}
              candidates={col.candidates}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

const MONTHS = ["Dec", "Jan", "Feb", "Mar", "Apr", "May"];
const VALUES = [225, 231, 235, 238, 244, 248];

export function HeadcountChart() {
  const min = 215;
  const max = 260;
  const range = max - min;
  const width = 340;
  const height = 140;
  const padX = 36;
  const padY = 16;
  const chartW = width - padX * 2;
  const chartH = height - padY * 2;

  const points = VALUES.map((v, i) => {
    const x = padX + (i / (VALUES.length - 1)) * chartW;
    const y = padY + chartH - ((v - min) / range) * chartH;
    return `${x},${y}`;
  }).join(" ");

  const areaPoints = `${padX},${padY + chartH} ${points} ${padX + chartW},${padY + chartH}`;

  return (
    <div>
      <svg viewBox={`0 0 ${width} ${height}`} className="w-full">
        <defs>
          <linearGradient id="hcGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#4F46E5" stopOpacity="0.25" />
            <stop offset="100%" stopColor="#4F46E5" stopOpacity="0" />
          </linearGradient>
        </defs>
        {/* Grid lines */}
        {[0, 0.25, 0.5, 0.75, 1].map((t) => {
          const y = padY + chartH * (1 - t);
          const val = Math.round(min + range * t);
          return (
            <g key={t}>
              <line x1={padX} y1={y} x2={padX + chartW} y2={y} stroke="#E5E7EB" strokeWidth="1" strokeDasharray="4,4" className="dark:stroke-dark-3" />
              <text x={padX - 4} y={y + 4} fontSize="9" fill="#9CA3AF" textAnchor="end">{val}</text>
            </g>
          );
        })}
        {/* Area fill */}
        <polygon points={areaPoints} fill="url(#hcGrad)" />
        {/* Line */}
        <polyline points={points} fill="none" stroke="#4F46E5" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
        {/* Points */}
        {VALUES.map((v, i) => {
          const x = padX + (i / (VALUES.length - 1)) * chartW;
          const y = padY + chartH - ((v - min) / range) * chartH;
          return <circle key={i} cx={x} cy={y} r="4" fill="white" stroke="#4F46E5" strokeWidth="2" />;
        })}
        {/* X Labels */}
        {MONTHS.map((m, i) => {
          const x = padX + (i / (MONTHS.length - 1)) * chartW;
          return <text key={m} x={x} y={height - 3} fontSize="9" fill="#9CA3AF" textAnchor="middle">{m}</text>;
        })}
      </svg>
    </div>
  );
}

"use client";

