              <button onClick={() => setShowNewTaskModal(false)} className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
                <svg className="size-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <form onSubmit={handleCreateTask} className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-dark-5 dark:text-dark-6 mb-1">Task Title <span className="text-rose-500">*</span></label>
                <input name="title" type="text" required placeholder="Enter task title" className="input-field" />
              </div>
              <div>
                <label className="block text-xs font-medium text-dark-5 dark:text-dark-6 mb-1">Description</label>
                <textarea name="description" rows={3} placeholder="Describe the task..." className="input-field resize-none" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium text-dark-5 dark:text-dark-6 mb-1">Priority</label>
                  <select name="priority" className="input-field">
                    <option value="HIGH">High</option>
                    <option value="MEDIUM" defaultValue="MEDIUM">Medium</option>
                    <option value="LOW">Low</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-medium text-dark-5 dark:text-dark-6 mb-1">Due Date</label>
                  <input name="dueDate" type="date" className="input-field" />
                </div>
              </div>
              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowNewTaskModal(false)} className="btn-secondary">Cancel</button>
                <button type="submit" disabled={isPending} className="btn-primary disabled:opacity-60">
                  {isPending ? "Creating…" : "Create Task"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState, useMemo, useTransition } from "react";
import { useRouter } from "next/navigation";
import { type Task, type TaskGroup } from "./tasks-data";
import { TaskRow } from "./task-row";
import { TasksFilterBar, type FilterTab, type PriorityFilter } from "./tasks-filter-bar";
import { updateTaskStatus, deleteTask } from "@/lib/actions/tasks";
import type { SerializedTask } from "@/lib/actions/tasks";

interface MyTasksViewProps {
  tasks: SerializedTask[];
  setToast: (msg: string) => void;
}

const today = new Date();
today.setHours(0, 0, 0, 0);

const weekEnd = new Date(today);
weekEnd.setDate(weekEnd.getDate() + 7);

function mapDbTaskToTask(t: SerializedTask): Task {
  let group: TaskGroup = "Later";
  if (t.dueDate) {
    const due = new Date(t.dueDate);
    due.setHours(0, 0, 0, 0);
    if (due.getTime() === today.getTime()) group = "Today";
    else if (due < weekEnd) group = "This Week";
  }

  const priorityMap: Record<string, Task["priority"]> = {
    HIGH: "High",
    MEDIUM: "Medium",
    LOW: "Low",
  };

  return {
    id: t.id,
    title: t.title,
    project: t.project?.name ?? "General",
    projectColor: "indigo",
    priority: priorityMap[t.priority] ?? "Medium",
    dueDate: t.dueDate
      ? new Date(t.dueDate).toLocaleDateString("en-US", { month: "short", day: "numeric" })
      : "No due date",
    avatar: t.assignee?.avatarUrl ?? "/images/user/user-01.png",
    group,
  };
}

export function MyTasksView({ tasks: dbTasks, setToast }: MyTasksViewProps) {
  const router = useRouter();
  const [, startTransition] = useTransition();
  const [optimisticDone, setOptimisticDone] = useState<Set<string>>(
    () => new Set(dbTasks.filter((t) => t.status === "DONE").map((t) => t.id))
  );
  const [filterTab, setFilterTab] = useState<FilterTab>("All");
  const [priorityFilter, setPriorityFilter] = useState<PriorityFilter>("All");

  function handleToggle(id: string) {
    const isNowDone = !optimisticDone.has(id);
    setOptimisticDone((prev) => {
      const next = new Set(prev);
      isNowDone ? next.add(id) : next.delete(id);
      return next;
    });
    startTransition(async () => {
      try {
        await updateTaskStatus(id, isNowDone ? "DONE" : "TODO");
        router.refresh();
      } catch {
        setOptimisticDone((prev) => {
          const next = new Set(prev);
          isNowDone ? next.delete(id) : next.add(id);
          return next;
        });
        setToast("Failed to update task status");
      }
    });
  }

  function handleDelete(id: string) {
    startTransition(async () => {
      try {
        await deleteTask(id);
        setToast("Task deleted.");
        router.refresh();
      } catch {
        setToast("Failed to delete task");
      }
    });
  }

  const allTasks = useMemo<Task[]>(
    () => dbTasks.filter((t) => t.status !== "DONE").map(mapDbTaskToTask),
    [dbTasks],
  );

  const overdueTasksList = useMemo<Task[]>(
    () =>
      dbTasks
        .filter((t) => {
          if (!t.dueDate || t.status === "DONE") return false;
          const due = new Date(t.dueDate);
          due.setHours(0, 0, 0, 0);
          return due < today;
        })
        .map(mapDbTaskToTask),
    [dbTasks],
  );

  const filtered = allTasks.filter((t) => {
    const matchTab =
      filterTab === "All" ||
      (filterTab === "Today" && t.group === "Today") ||
      (filterTab === "This Week" && t.group === "This Week") ||
      filterTab === "Overdue";
    const matchPriority = priorityFilter === "All" || t.priority === priorityFilter;
    return matchTab && matchPriority;
  });

  const overdueFiltered = overdueTasksList.filter(
    (t) => priorityFilter === "All" || t.priority === priorityFilter,
  );

  const groups: TaskGroup[] = ["Today", "This Week", "Later"];
  const showOverdue = filterTab === "All" || filterTab === "Overdue";
  const showGroups = filterTab !== "Overdue";

  return (
    <div className="space-y-4">
      <TasksFilterBar
        filterTab={filterTab}
        setFilterTab={setFilterTab}
        priorityFilter={priorityFilter}
        setPriorityFilter={setPriorityFilter}
      />

      {showOverdue && overdueFiltered.length > 0 && (
        <div className="card">
          <div className="flex items-center gap-2 border-b border-gray-3 px-5 py-3 dark:border-dark-3">
            <span className="size-2 rounded-full bg-rose-dark" />
            <h2 className="section-title text-rose-dark">Overdue ({overdueFiltered.length})</h2>
          </div>
          <div className="p-3">
            {overdueFiltered.map((task) => (
              <TaskRow
                key={task.id}
                task={task}
                completed={optimisticDone.has(task.id)}
                onToggle={handleToggle}
                onDelete={handleDelete}
                overdue
              />
            ))}
          </div>
        </div>
      )}

      {showGroups &&
        groups.map((group) => {
          const groupTasks = filtered.filter((t) => t.group === group);
          if (groupTasks.length === 0) return null;
          return (
            <div key={group} className="card">
              <div className="flex items-center justify-between border-b border-gray-3 px-5 py-3 dark:border-dark-3">
                <h2 className="section-title">{group}</h2>
                <span className="text-muted">{groupTasks.length} tasks</span>
              </div>
              <div className="p-3">
                {groupTasks.map((task) => (
                  <TaskRow
                    key={task.id}
                    task={task}
                    completed={optimisticDone.has(task.id)}
                    onToggle={handleToggle}
                    onDelete={handleDelete}
                  />
                ))}
              </div>
            </div>
          );
        })}

      {showGroups && filtered.length === 0 && overdueFiltered.length === 0 && (
        <div className="card empty-state">
          <p className="text-body-medium">No tasks found</p>
          <p className="empty-state-text">
            {filterTab !== "All" ? "Try switching to the All tab." : "Create a new task to get started."}
          </p>
        </div>
      )}

      {!showGroups && (
        <div className="card">
          <div className="flex items-center gap-2 border-b border-gray-3 px-5 py-3 dark:border-dark-3">
            <span className="size-2 rounded-full bg-rose-dark" />
            <h2 className="section-title text-rose-dark">Overdue ({overdueFiltered.length})</h2>
          </div>
          <div className="p-3">
            {overdueFiltered.length > 0 ? (
              overdueFiltered.map((task) => (
                <TaskRow
                  key={task.id}
                  task={task}
                  completed={optimisticDone.has(task.id)}
                  onToggle={handleToggle}
                  onDelete={handleDelete}
                  overdue
                />
              ))
            ) : (
              <p className="py-6 text-center text-sm text-dark-5 dark:text-dark-6">No overdue tasks!</p>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import type { Task } from "./tasks-data";
import { PROJECT_COLORS, PRIORITY_COLORS } from "./tasks-data";

interface TaskRowProps {
  task: Task;
  completed: boolean;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  overdue?: boolean;
}

export function TaskRow({ task, completed, onToggle, onDelete, overdue }: TaskRowProps) {
  const [showMenu, setShowMenu] = useState(false);

  return (
    <div className={`flex items-center gap-3 rounded-lg px-3 py-2.5 transition-colors hover:bg-gray-1 dark:hover:bg-dark-3/40 ${completed ? "opacity-60" : ""}`}>
      <button
        onClick={() => onToggle(task.id)}
        className={`flex size-5 flex-shrink-0 items-center justify-center rounded border-2 transition-colors ${
          completed
            ? "border-primary-600 bg-primary-600"
            : "border-gray-4 bg-transparent hover:border-primary-600 dark:border-dark-4"
        }`}
        aria-label={completed ? "Mark incomplete" : "Mark complete"}
      >
        {completed && (
          <svg className="size-3 text-white" viewBox="0 0 24 24" fill="none">
            <path d="M4.5 12.75l6 6 9-13.5" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        )}
      </button>

      <span className={`min-w-0 flex-1 text-sm font-medium ${completed ? "line-through text-dark-5 dark:text-dark-6" : "text-dark dark:text-white"}`}>
        {task.title}
      </span>

      <span className={`hidden shrink-0 rounded-full px-2 py-0.5 text-xs font-medium sm:inline-flex ${PROJECT_COLORS[task.projectColor] ?? "bg-gray-2 text-dark-5"}`}>
        {task.project}
      </span>

      <div className="flex shrink-0 items-center gap-1.5">
        <span className={`size-2 rounded-full ${PRIORITY_COLORS[task.priority]}`} />
        <span className="hidden text-xs text-dark-5 dark:text-dark-6 md:inline">{task.priority}</span>
      </div>

      <span className={`hidden shrink-0 text-xs sm:inline ${overdue ? "font-semibold text-rose-dark" : "text-dark-5 dark:text-dark-6"}`}>
        {task.dueDate}
      </span>

      <Image src={task.avatar} alt="" width={24} height={24} className="size-6 flex-shrink-0 rounded-full" />

      <div className="relative flex-shrink-0">
        <button
          onClick={() => setShowMenu((p) => !p)}
          className="flex size-7 items-center justify-center rounded text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
        >
          <svg className="size-4" viewBox="0 0 24 24" fill="none">
            <path d="M12 6.75a.75.75 0 110-1.5.75.75 0 010 1.5zM12 12.75a.75.75 0 110-1.5.75.75 0 010 1.5zM12 18.75a.75.75 0 110-1.5.75.75 0 010 1.5z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>

        {showMenu && (
          <div className="absolute right-0 top-8 z-20 w-40 rounded-xl border border-gray-3 bg-white shadow-floating dark:border-dark-3 dark:bg-dark-2">
            {!completed && (
              <button
                onClick={() => { setShowMenu(false); onToggle(task.id); }}
                className="flex w-full items-center px-4 py-2.5 text-sm text-dark hover:bg-gray-1 dark:text-white dark:hover:bg-dark-3 rounded-t-xl"
              >
                Mark Complete
              </button>
            )}
            <button
              onClick={() => { setShowMenu(false); onDelete(task.id); }}
              className={`flex w-full items-center px-4 py-2.5 text-sm text-rose-dark hover:bg-gray-1 dark:hover:bg-dark-3 ${completed ? "rounded-t-xl" : ""} rounded-b-xl`}
            >
              Delete Task
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import Image from "next/image";

type TeamMember = {
  name: string;
  avatarUrl: string | null;
  tasks: number;
  done: number;
};

type TasksTeamWorkloadProps = {
  teamWorkload: TeamMember[];
};

export function TasksTeamWorkload({ teamWorkload }: TasksTeamWorkloadProps) {
  if (teamWorkload.length === 0) {
    return (
      <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
        <h2 className="font-semibold text-dark dark:text-white mb-4">Team Workload</h2>
        <p className="text-sm text-dark-5 dark:text-dark-6 py-4">No task assignments yet.</p>
      </div>
    );
  }

  return (
    <div className="rounded-xl bg-white p-5 shadow-card dark:bg-dark-2 dark:border dark:border-dark-3">
      <div className="mb-4 flex items-center justify-between">
        <h2 className="font-semibold text-dark dark:text-white">Team Workload</h2>
        <span className="rounded-full bg-primary-50 px-2 py-0.5 text-xs text-primary-600 dark:bg-primary-900/20 dark:text-primary-300">
          {teamWorkload.length} member{teamWorkload.length !== 1 ? "s" : ""}
        </span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-gray-2 dark:border-dark-3">
              <th className="pb-2 text-left text-xs font-medium text-dark-5 dark:text-dark-6">Member</th>
              <th className="pb-2 text-center text-xs font-medium text-dark-5 dark:text-dark-6">Tasks</th>
              <th className="pb-2 text-center text-xs font-medium text-dark-5 dark:text-dark-6">Done</th>
              <th className="pb-2 text-left text-xs font-medium text-dark-5 dark:text-dark-6 pl-2">Progress</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-2 dark:divide-dark-3">
            {teamWorkload.map((m) => {
              const pct = m.tasks > 0 ? Math.round((m.done / m.tasks) * 100) : 0;
              const initials = m.name.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 2);
              return (
                <tr key={m.name}>
                  <td className="py-2.5 pr-2">
                    <div className="flex items-center gap-2">
                      {m.avatarUrl ? (
                        <Image src={m.avatarUrl} alt={m.name} width={28} height={28} className="rounded-full object-cover shrink-0" />
                      ) : (
                        <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-primary-100 text-xs font-bold text-primary-700 dark:bg-primary-900/30 dark:text-primary-300">
                          {initials}
                        </div>
                      )}
                      <span className="whitespace-nowrap text-xs font-medium text-dark dark:text-white">
                        {m.name.split(" ")[0]}
                      </span>
                    </div>
                  </td>
                  <td className="py-2.5 text-center text-xs text-dark-5 dark:text-dark-6">{m.tasks}</td>
                  <td className="py-2.5 text-center text-xs text-dark-5 dark:text-dark-6">{m.done}</td>
                  <td className="py-2.5 pl-2">
                    <div className="relative h-1 w-20 rounded-full bg-gray-2 dark:bg-dark-3 overflow-hidden">
                      <div className="absolute inset-y-0 left-0 rounded-full bg-primary-500" style={{ width: `${pct}%` }} />
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import { PROJECTS_LIST, COLUMN_LABELS } from "./kanban-types";
import type { Priority, ColumnKey } from "./kanban-types";

interface Props {
  taskTitle: string;
  taskProject: string;
  taskPriority: Priority;
  taskColumn: ColumnKey;
  taskAssignee: string;
  taskDueDate: string;
  onTitleChange: (v: string) => void;
  onProjectChange: (v: string) => void;
  onPriorityChange: (v: Priority) => void;
  onColumnChange: (v: ColumnKey) => void;
  onAssigneeChange: (v: string) => void;
  onDueDateChange: (v: string) => void;
  onAdd: () => void;
  onClose: () => void;
}

export function KanbanAddModal({
  taskTitle, taskProject, taskPriority, taskColumn,
  taskAssignee, taskDueDate,
  onTitleChange, onProjectChange, onPriorityChange,
  onColumnChange, onAssigneeChange, onDueDateChange,
  onAdd, onClose,
}: Readonly<Props>) {
  return (
    <div className="modal-overlay">
      <div className="modal-panel w-full max-w-md p-6">
        <div className="modal-header mb-5 flex items-center justify-between">
          <h2 className="section-title">New Task</h2>
          <button onClick={onClose} className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
            <svg className="size-4" viewBox="0 0 24 24" fill="none">
              <path d="M6 18L18 6M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
          </button>
        </div>

        <div className="space-y-4">
          <div>
            <label className="label-field mb-1.5">Title <span className="text-rose-dark">*</span></label>
            <input type="text" value={taskTitle} onChange={(e) => onTitleChange(e.target.value)} placeholder="Enter task title" className="input-field w-full" />
          </div>
          <div>
            <label className="label-field mb-1.5">Project</label>
            <select value={taskProject} onChange={(e) => onProjectChange(e.target.value)} className="input-field w-full">
              <option value="">Select project</option>
              {PROJECTS_LIST.filter((p) => p !== "All Projects").map((p) => (
                <option key={p} value={p}>{p}</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="label-field mb-1.5">Priority</label>
              <select value={taskPriority} onChange={(e) => onPriorityChange(e.target.value as Priority)} className="input-field w-full">
                <option value="High">High</option>
                <option value="Medium">Medium</option>
                <option value="Low">Low</option>
              </select>
            </div>
            <div>
              <label className="label-field mb-1.5">Column</label>
              <select value={taskColumn} onChange={(e) => onColumnChange(e.target.value as ColumnKey)} className="input-field w-full">
                {(Object.keys(COLUMN_LABELS) as ColumnKey[]).map((k) => (
                  <option key={k} value={k}>{COLUMN_LABELS[k]}</option>
                ))}
              </select>
            </div>
          </div>
          <div>
            <label className="label-field mb-1.5">Assignee</label>
            <input type="text" value={taskAssignee} onChange={(e) => onAssigneeChange(e.target.value)} placeholder="Enter assignee name" className="input-field w-full" />
          </div>
          <div>
            <label className="label-field mb-1.5">Due Date</label>
            <input type="date" value={taskDueDate} onChange={(e) => onDueDateChange(e.target.value)} className="input-field w-full" />
          </div>
        </div>

        <div className="mt-6 flex items-center justify-end gap-3">
          <button onClick={onClose} className="btn-secondary">Cancel</button>
          <button onClick={onAdd} className="btn-primary">Add Task</button>
        </div>
      </div>
    </div>
  );
}

"use client";

import Image from "next/image";
import { useRef, useEffect } from "react";
import { PRIORITY_CONFIG, PROJECT_COLORS } from "./kanban-types";
import type { KanbanTask, ColumnKey } from "./kanban-types";

interface Props {
  task: KanbanTask;
  colKey: ColumnKey;
  openMenu: string | null;
  setOpenMenu: (id: string | null) => void;
  onMoveNext: (taskId: string, colKey: ColumnKey) => void;
  onDelete: (taskId: string) => void;
  onEdit: (taskId: string) => void;
}

export function KanbanCard({ task, colKey, openMenu, setOpenMenu, onMoveNext, onDelete, onEdit }: Readonly<Props>) {
  const done = colKey === "done";
  const p = PRIORITY_CONFIG[task.priority];
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (openMenu !== task.id) return;
    function handleClick(e: MouseEvent) {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setOpenMenu(null);
      }
    }
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, [openMenu, task.id, setOpenMenu]);

  return (
    <div className={`group rounded-xl bg-white p-4 shadow-card transition-shadow hover:shadow-floating dark:border dark:border-dark-3 dark:bg-dark-2 ${done ? "opacity-70" : ""}`}>
      <div className="mb-3 flex items-center justify-between">
        <span className={`flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-medium ${p.bg} ${p.text}`}>
          <span className={`size-1.5 rounded-full ${p.dot}`} />
          {task.priority}
        </span>
        <div ref={menuRef} className="relative">
          <button
            onClick={() => setOpenMenu(openMenu === task.id ? null : task.id)}
            className="flex size-6 items-center justify-center rounded text-dark-5 opacity-0 transition-opacity hover:bg-gray-2 group-hover:opacity-100 dark:text-dark-6 dark:hover:bg-dark-3"
          >
            <svg className="size-4" viewBox="0 0 24 24" fill="none">
              <path d="M12 6.75a.75.75 0 110-1.5.75.75 0 010 1.5zM12 12.75a.75.75 0 110-1.5.75.75 0 010 1.5zM12 18.75a.75.75 0 110-1.5.75.75 0 010 1.5z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </button>
          {openMenu === task.id && (
            <div className="absolute right-0 top-8 z-20 w-44 rounded-xl border border-gray-3 bg-white shadow-floating dark:border-dark-3 dark:bg-dark-2">
              <button
                onClick={() => { setOpenMenu(null); onEdit(task.id); }}
                className="flex w-full items-center px-4 py-2.5 text-sm text-dark hover:bg-gray-1 dark:text-white dark:hover:bg-dark-3 rounded-t-xl"
              >
                Edit
              </button>
              {colKey !== "done" && (
                <button
                  onClick={() => { setOpenMenu(null); onMoveNext(task.id, colKey); }}
                  className="flex w-full items-center px-4 py-2.5 text-sm text-dark hover:bg-gray-1 dark:text-white dark:hover:bg-dark-3"
                >
                  Move to Next Stage
                </button>
              )}
              <button
                onClick={() => { setOpenMenu(null); onDelete(task.id); }}
                className="flex w-full items-center px-4 py-2.5 text-sm text-rose-dark hover:bg-gray-1 dark:hover:bg-dark-3 rounded-b-xl"
              >
                Delete
              </button>
            </div>
          )}
        </div>
      </div>

      <p className={`mb-2 text-sm font-semibold leading-snug ${done ? "line-through text-dark-5 dark:text-dark-6" : "text-dark dark:text-white"}`}>
        {task.title}
      </p>

      <span className={`mb-3 inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${PROJECT_COLORS[task.projectColor] ?? "bg-gray-2 text-dark-5"}`}>
        {task.project}
      </span>

      {task.subtasks && (
        <div className="mb-3">
          <div className="mb-1 flex items-center justify-between text-xs text-dark-5 dark:text-dark-6">
            <span>Subtasks</span>
            <span>{task.subtasks.done}/{task.subtasks.total}</span>
          </div>
          <div className="h-1 w-full overflow-hidden rounded-full bg-gray-3 dark:bg-dark-3">
            <div className="h-full rounded-full bg-primary-600" style={{ width: `${(task.subtasks.done / task.subtasks.total) * 100}%` }} />
          </div>
        </div>
      )}

      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2.5 text-xs text-dark-5 dark:text-dark-6">
          <span className={`flex items-center gap-1 ${task.overdue ? "font-semibold text-rose-dark" : ""}`}>
            <svg className="size-3" viewBox="0 0 24 24" fill="none">
              <path d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
            {task.dueDate}
          </span>
          {task.comments > 0 && (
            <span className="flex items-center gap-1">
              <svg className="size-3" viewBox="0 0 24 24" fill="none">
                <path d="M2.25 12.76c0 1.6 1.123 2.994 2.707 3.227 1.068.157 2.148.279 3.238.364.466.037.893.281 1.153.671L12 21l2.652-3.978c.26-.39.687-.634 1.153-.67 1.09-.086 2.17-.208 3.238-.365 1.584-.233 2.707-1.626 2.707-3.228V6.741c0-1.602-1.123-2.995-2.707-3.228A48.394 48.394 0 0012 3c-2.392 0-4.744.175-7.043.513C3.373 3.746 2.25 5.14 2.25 6.741v6.018z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
              {task.comments}
            </span>
          )}
        </div>
        <Image src={task.avatar} alt="" width={24} height={24} className="size-6 rounded-full ring-2 ring-white dark:ring-dark-2" />
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { KanbanColumn } from "./kanban-column";
import { createTask, updateTaskStatus, updateTask, deleteTask } from "@/lib/actions/tasks";
import type { SerializedTask } from "@/lib/actions/tasks";
import type { KanbanColumn as KanbanColumnType, KanbanTask, ColumnKey, Priority } from "./kanban-types";

const STATUS_TO_COLUMN: Record<string, ColumnKey> = {
  TODO: "todo",
  IN_PROGRESS: "inprogress",
  IN_REVIEW: "review",
  DONE: "done",
};

const COLUMN_TO_NEXT_STATUS: Record<ColumnKey, "IN_PROGRESS" | "IN_REVIEW" | "DONE" | null> = {
  todo: "IN_PROGRESS",
  inprogress: "IN_REVIEW",
  review: "DONE",
  done: null,
};

const PRIORITY_MAP: Record<string, Priority> = {
  HIGH: "High",
  MEDIUM: "Medium",
  LOW: "Low",
};

const COLUMN_CONFIG: { key: ColumnKey; label: string; headerColor: string; dotColor: string }[] = [
  { key: "todo",      label: "To Do",       headerColor: "border-gray-4",       dotColor: "bg-gray-4" },
  { key: "inprogress",label: "In Progress", headerColor: "border-primary-600",  dotColor: "bg-primary-600" },
  { key: "review",    label: "Review",      headerColor: "border-amber-dark",   dotColor: "bg-amber-dark" },
  { key: "done",      label: "Done",        headerColor: "border-emerald-dark", dotColor: "bg-emerald-dark" },
];

const todayStart = new Date();
todayStart.setHours(0, 0, 0, 0);

function toKanbanTask(t: SerializedTask): KanbanTask {
  const due = t.dueDate ? new Date(t.dueDate) : null;
  return {
    id: t.id,
    title: t.title,
    project: t.project?.name ?? "General",
    projectColor: "indigo",
    priority: PRIORITY_MAP[t.priority] ?? "Medium",
    dueDate: due ? due.toLocaleDateString("en-US", { month: "short", day: "numeric" }) : "No due date",
    overdue: due ? due < todayStart && t.status !== "DONE" : false,
    avatar: t.assignee?.avatarUrl ?? "/images/user/user-01.png",
    comments: 0,
    attachments: 0,
  };
}

interface Props {
  tasks: SerializedTask[];
}

export function KanbanPageClient({ tasks }: Readonly<Props>) {
  const router = useRouter();
  const { toast, setToast } = useToast();
  const [openMenu, setOpenMenu] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [addColumn, setAddColumn] = useState<ColumnKey>("todo");
  const [editTask, setEditTask] = useState<SerializedTask | null>(null);
  const [isPending, startTransition] = useTransition();

  const columns: KanbanColumnType[] = COLUMN_CONFIG.map((cfg) => ({
    ...cfg,
    tasks: tasks.filter((t) => STATUS_TO_COLUMN[t.status] === cfg.key).map(toKanbanTask),
  }));

  function openAddModal(col: ColumnKey) {
    setAddColumn(col);
    setShowAddModal(true);
  }

  function handleMoveNext(taskId: string, colKey: ColumnKey) {
    const nextStatus = COLUMN_TO_NEXT_STATUS[colKey];
    if (!nextStatus) return;
    startTransition(async () => {
      try {
        await updateTaskStatus(taskId, nextStatus);
        setToast("Task moved to next stage!");
        router.refresh();
      } catch (err) {
        setToast(err instanceof Error ? err.message : "Failed to move task");
      }
    });
  }

  function handleDelete(taskId: string) {
    startTransition(async () => {
      try {
        await deleteTask(taskId);
        setToast("Task deleted.");
        router.refresh();
      } catch (err) {
        setToast(err instanceof Error ? err.message : "Failed to delete task");
      }
    });
  }

  function handleEdit(taskId: string) {
    const found = tasks.find((t) => t.id === taskId) ?? null;
    setEditTask(found);
  }

  function handleAddTask(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    startTransition(async () => {
      try {
        await createTask({
          title: fd.get("title") as string,
          priority: (fd.get("priority") as "HIGH" | "MEDIUM" | "LOW") || "MEDIUM",
          dueDate: (fd.get("dueDate") as string) || undefined,
        });
        setShowAddModal(false);
        setToast("Task added to board!");
        router.refresh();
      } catch (err) {
        setToast(err instanceof Error ? err.message : "Failed to create task");
      }
    });
  }

  function handleEditTask(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!editTask) return;
    const fd = new FormData(e.currentTarget);
    startTransition(async () => {
      try {
        await updateTask(editTask.id, {
          title: fd.get("title") as string,
          priority: fd.get("priority") as "HIGH" | "MEDIUM" | "LOW",
          dueDate: (fd.get("dueDate") as string) || undefined,
        });
        setEditTask(null);
        setToast("Task updated!");
        router.refresh();
      } catch (err) {
        setToast(err instanceof Error ? err.message : "Failed to update task");
      }
    });
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <h1 className="page-title">Kanban Board</h1>
          <p className="text-muted">Visualize and manage your workflow</p>
        </div>
        <button onClick={() => openAddModal("todo")} className="btn-primary">+ Add Task</button>
      </div>

      <div className="overflow-x-auto pb-4">
        <div className="flex min-w-max gap-4">
          {columns.map((col) => (
            <KanbanColumn
              key={col.key}
              col={col}
              openMenu={openMenu}
              setOpenMenu={setOpenMenu}
              onAddTask={openAddModal}
              onMoveNext={handleMoveNext}
              onDelete={handleDelete}
              onEdit={handleEdit}
            />
          ))}
        </div>
      </div>

      {/* Add Task Modal */}
      {showAddModal && (
        <div className="modal-overlay">
          <div className="modal-panel max-w-md p-6">
            <div className="mb-5 flex items-center justify-between">
              <h2 className="section-title">Add Task</h2>
              <button onClick={() => setShowAddModal(false)} className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
                <svg className="size-4" viewBox="0 0 24 24" fill="none">
                  <path d="M6 18L18 6M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                </svg>
              </button>
            </div>
            <form onSubmit={handleAddTask} className="space-y-4">
              <div>
                <label className="label-field mb-1">Title <span className="text-rose-dark">*</span></label>
                <input name="title" type="text" required placeholder="Task title" className="input-field" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label-field mb-1">Priority</label>
                  <select name="priority" defaultValue="MEDIUM" className="input-field">
                    <option value="HIGH">High</option>
                    <option value="MEDIUM">Medium</option>
                    <option value="LOW">Low</option>
                  </select>
                </div>
                <div>
                  <label className="label-field mb-1">Due Date</label>
                  <input name="dueDate" type="date" className="input-field" />
                </div>
              </div>
              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowAddModal(false)} className="btn-secondary">Cancel</button>
                <button type="submit" disabled={isPending} className="btn-primary disabled:opacity-60">
                  {isPending ? "Adding…" : "Add Task"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Edit Task Modal */}
      {editTask && (
        <div className="modal-overlay">
          <div className="modal-panel max-w-md p-6">
            <div className="mb-5 flex items-center justify-between">
              <h2 className="section-title">Edit Task</h2>
              <button onClick={() => setEditTask(null)} className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
                <svg className="size-4" viewBox="0 0 24 24" fill="none">
                  <path d="M6 18L18 6M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                </svg>
              </button>
            </div>
            <form onSubmit={handleEditTask} className="space-y-4">
              <div>
                <label className="label-field mb-1">Title <span className="text-rose-dark">*</span></label>
                <input name="title" type="text" required defaultValue={editTask.title} className="input-field" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label-field mb-1">Priority</label>
                  <select name="priority" defaultValue={editTask.priority} className="input-field">
                    <option value="HIGH">High</option>
                    <option value="MEDIUM">Medium</option>
                    <option value="LOW">Low</option>
                  </select>
                </div>
                <div>
                  <label className="label-field mb-1">Due Date</label>
                  <input
                    name="dueDate"
                    type="date"
                    defaultValue={editTask.dueDate ? editTask.dueDate.slice(0, 10) : ""}
                    className="input-field"
                  />
                </div>
              </div>
              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setEditTask(null)} className="btn-secondary">Cancel</button>
                <button type="submit" disabled={isPending} className="btn-primary disabled:opacity-60">
                  {isPending ? "Saving…" : "Save Changes"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Toast } from "@/components/ui/toast";
import { createProject } from "@/lib/actions/tasks";
import type { SerializedProject } from "@/lib/actions/tasks";

const STATUS_STYLES: Record<string, string> = {
  ACTIVE: "rounded-full bg-primary-50 px-2.5 py-0.5 text-xs font-medium text-primary-600 dark:bg-primary-900/20 dark:text-primary-300",
  COMPLETED: "rounded-full bg-emerald-light px-2.5 py-0.5 text-xs font-medium text-emerald-dark dark:bg-emerald-dark/20 dark:text-emerald",
  ON_HOLD: "rounded-full bg-amber-light px-2.5 py-0.5 text-xs font-medium text-amber-dark",
  CANCELLED: "rounded-full bg-rose-light px-2.5 py-0.5 text-xs font-medium text-rose-dark",
};

const PROGRESS_STYLES: Record<string, string> = {
  ACTIVE: "bg-primary-600",
  COMPLETED: "bg-emerald-dark",
  ON_HOLD: "bg-amber-dark",
  CANCELLED: "bg-rose-dark",
};

function formatDueDate(iso: string | null) {
  if (!iso) return "No due date";
  return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

interface Props {
  projects: SerializedProject[];
}

export function ProjectsPageClient({ projects }: Readonly<Props>) {
  const router = useRouter();
  const { toast, setToast } = useToast();
  const [showModal, setShowModal] = useState(false);
  const [isPending, startTransition] = useTransition();

  const active = projects.filter((p) => p.status === "ACTIVE").length;
  const completed = projects.filter((p) => p.status === "COMPLETED").length;
  const onHold = projects.filter((p) => p.status === "ON_HOLD").length;

  const stats = [
    { label: "Active", value: active, color: "text-primary-600 dark:text-primary-300" },
    { label: "Completed", value: completed, color: "text-emerald-dark dark:text-emerald" },
    { label: "On Hold", value: onHold, color: "text-amber-dark" },
    { label: "Total", value: projects.length, color: "text-dark dark:text-white" },
  ];

  function handleCreate(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    startTransition(async () => {
      try {
        await createProject({
          name: fd.get("name") as string,
          description: (fd.get("description") as string) || undefined,
          startDate: (fd.get("startDate") as string) || undefined,
          dueDate: (fd.get("dueDate") as string) || undefined,
        });
        setShowModal(false);
        setToast("Project created successfully!");
        router.refresh();
      } catch (err) {
        setToast(err instanceof Error ? err.message : "Failed to create project");
      }
    });
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <h1 className="page-title">Projects</h1>
          <p className="text-muted">Track all HR initiatives and projects</p>
        </div>
        <button onClick={() => setShowModal(true)} className="btn-primary">+ New Project</button>
      </div>

      <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
        {stats.map((s) => (
          <div key={s.label} className="card-p">
            <p className="stat-label">{s.label}</p>
            <p className={`mt-1 text-2xl font-bold ${s.color}`}>{s.value}</p>
          </div>
        ))}
      </div>

      {projects.length === 0 ? (
        <div className="card empty-state">
          <p className="text-body-medium">No projects yet</p>
          <p className="empty-state-text">Create your first project to get started.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
          {projects.map((project) => (
            <div key={project.id} className="card overflow-hidden">
              <div className={`h-1.5 w-full ${PROGRESS_STYLES[project.status] ?? "bg-primary-600"}`} />
              <div className="p-5">
                <div className="mb-2 flex items-start justify-between gap-2">
                  <h3 className="section-title">{project.name}</h3>
                  <span className={STATUS_STYLES[project.status] ?? STATUS_STYLES.ACTIVE}>
                    {project.status.charAt(0) + project.status.slice(1).toLowerCase().replace("_", " ")}
                  </span>
                </div>
                <p className="text-muted mb-4 line-clamp-1">{project.description ?? "No description"}</p>

                <div className="mb-1 flex items-center justify-between">
                  <span className="text-muted">Progress</span>
                  <span className="text-xs font-semibold text-dark dark:text-white">{project.progress}%</span>
                </div>
                <div className="mb-4 h-1.5 w-full overflow-hidden rounded-full bg-gray-3 dark:bg-dark-3">
                  <div
                    className={`h-full rounded-full ${PROGRESS_STYLES[project.status] ?? "bg-primary-600"}`}
                    style={{ width: `${project.progress}%` }}
                  />
                </div>

                <div className="flex items-center justify-between">
                  <div className="text-muted flex items-center gap-1 text-xs">
                    <svg className="size-3.5" viewBox="0 0 24 24" fill="none">
                      <path d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                    {formatDueDate(project.dueDate)}
                  </div>
                  <span className="text-muted text-xs">{project.doneTasks}/{project.totalTasks} tasks</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {showModal && (
        <div className="modal-overlay">
          <div className="modal-panel w-full max-w-md p-6">
            <div className="mb-5 flex items-center justify-between">
              <h2 className="section-title">New Project</h2>
              <button onClick={() => setShowModal(false)} className="flex size-8 items-center justify-center rounded-lg text-dark-5 hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3">
                <svg className="size-4" viewBox="0 0 24 24" fill="none">
                  <path d="M6 18L18 6M6 6l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                </svg>
              </button>
            </div>
            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="label-field mb-1.5">Project Name <span className="text-rose-dark">*</span></label>
                <input name="name" type="text" required placeholder="Enter project name" className="input-field w-full" />
              </div>
              <div>
                <label className="label-field mb-1.5">Description</label>
                <textarea name="description" placeholder="Brief project description" rows={3} className="input-field w-full resize-none" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label-field mb-1.5">Start Date</label>
                  <input name="startDate" type="date" className="input-field w-full" />
                </div>
                <div>
                  <label className="label-field mb-1.5">End Date</label>
                  <input name="dueDate" type="date" className="input-field w-full" />
                </div>
              </div>
              <div className="flex items-center justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)} className="btn-secondary">Cancel</button>
                <button type="submit" disabled={isPending} className="btn-primary disabled:opacity-60">
                  {isPending ? "Creating…" : "Create Project"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <Toast message={toast} />
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";

type Plan = "BASIC" | "PRO" | "PRO_PLUS" | "PRO_MAX";

const PLANS: {
