﻿"use client";

import Image from "next/image";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useSidebarContext } from "../sidebar/sidebar-context";
import { Notification } from "./notification";
import { ThemeToggleSwitch } from "./theme-toggle";
import { UserInfo } from "./user-info";
import { GlobalSearch } from "./global-search";

const PAGE_TITLES: Record<string, { title: string; subtitle: string }> = {
  "/": { title: "Dashboard", subtitle: "Overview" },
  "/employees": { title: "Employees", subtitle: "Directory & profiles" },
  "/attendance": { title: "Attendance", subtitle: "Track & manage time" },
  "/leave": { title: "Leave", subtitle: "Manage time off" },
  "/payroll": { title: "Payroll", subtitle: "Salary & compensation" },
  "/recruitment": { title: "Recruitment", subtitle: "Hiring pipeline" },
  "/onboarding": { title: "Onboarding", subtitle: "Employee journeys" },
  "/collaboration": { title: "Collaboration", subtitle: "Channels & messages" },
  "/tasks": { title: "Tasks & Projects", subtitle: "Work management" },
  "/performance": { title: "Performance", subtitle: "KPIs & reviews" },
  "/learning": { title: "Learning", subtitle: "Courses & certifications" },
  "/reports": { title: "Reports", subtitle: "Analytics & insights" },
  "/ai": { title: "AI Assistant", subtitle: "Powered by Monja AI" },
  "/admin": { title: "Admin", subtitle: "System configuration" },
};

function getPageMeta(pathname: string) {
  const exact = PAGE_TITLES[pathname];
  if (exact) return exact;
  const prefix = Object.keys(PAGE_TITLES).find(
    (k) => k !== "/" && pathname.startsWith(k),
  );
  return prefix ? PAGE_TITLES[prefix] : { title: "Dashboard", subtitle: "" };
}

export function Header() {
  const { toggleSidebar, isMobile } = useSidebarContext();
  const pathname = usePathname();
  const meta = getPageMeta(pathname);

  return (
    <header className="sticky top-0 z-30 flex h-16 items-center border-b border-gray-3 bg-white/95 backdrop-blur-sm dark:border-dark-3 dark:bg-dark-2/95">
      <div className="flex w-full items-center gap-3 px-4 md:px-6">

        {/* ── Left: toggle + title ── */}
        <div className="flex items-center gap-3">
          <button
            onClick={toggleSidebar}
            className="rounded-lg p-2 text-dark-5 transition-colors hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3 lg:hidden"
            aria-label="Toggle sidebar"
          >
            <svg width={18} height={18} viewBox="0 0 24 24" fill="none">
              <path d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
            </svg>
          </button>

          {isMobile && (
            <Link href="/dashboard" className="max-[430px]:hidden">
              <Image
                src="/images/logo/logo-icon.svg"
                width={28}
                height={28}
                alt=""
                role="presentation"
              />
            </Link>
          )}

          <div className="hidden lg:block">
            <h1 className="text-sm font-semibold leading-none text-dark dark:text-white">
              {meta.title}
            </h1>
            {meta.subtitle && (
              <p className="mt-0.5 text-xs text-dark-5 dark:text-dark-6">
                {meta.subtitle}
              </p>
            )}
          </div>
        </div>

        {/* ── Center: global search ── */}
        <GlobalSearch />

        {/* ── Right: actions ── */}
        <div className="flex shrink-0 items-center gap-1">

          {/* AI Assistant */}
          <Link
            href="/ai"
            className="hidden items-center gap-1.5 rounded-lg bg-gradient-ai px-3 py-1.5 text-xs font-semibold text-white shadow-indigo-glow transition-opacity hover:opacity-90 sm:flex"
            aria-label="Open AI Assistant"
          >
            <svg className="size-3.5" viewBox="0 0 24 24" fill="none">
              <path d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
            Ask AI
          </Link>

          {/* Calendar shortcut */}
          <Link
            href="/calendar"
            className="grid size-9 place-items-center rounded-lg text-dark-5 transition-colors hover:bg-gray-2 dark:text-dark-6 dark:hover:bg-dark-3"
            aria-label="Calendar"
          >
            <svg className="size-4.5" viewBox="0 0 24 24" fill="none">
              <path d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </Link>

          <ThemeToggleSwitch />

          <Notification />

          <UserInfo />
        </div>
      </div>
    </header>
  );
}

"use client";

import { Dropdown, DropdownContent, DropdownTrigger } from "@/components/ui/dropdown";
import { useIsMobile } from "@/hooks/use-mobile";
import { useSocket } from "@/hooks/use-socket";
import { cn } from "@/lib/utils";
import Link from "next/link";
import { useCallback, useEffect, useState } from "react";
import { useSession } from "next-auth/react";
import { BellIcon } from "./icons";
import { getNotifications, type NotificationItem } from "@/lib/actions/notifications";

const TYPE_ICONS: Record<string, string> = {
  leave: "🏖️",
  task: "📋",
  performance: "🎯",
  onboarding: "👋",
  payroll: "💰",
  dm: "💬",
  channel: "📢",
  call: "📞",
};

type RtNotif = {
  id: string;
  type: "dm" | "channel" | "call";
  title: string;
  description: string;
  href: string;
  time: string;
  read: boolean;
};

type DisplayNotif = {
  id: string;
  type: string;
  title: string;
  description: string;
  time: string;
  read: boolean;
  href: string;
};

export function Notification() {
  const { data: session } = useSession();
  const currentUserId = session?.user?.id;
  const [isOpen, setIsOpen] = useState(false);
  const [sysNotifs, setSysNotifs] = useState<NotificationItem[]>([]);
  const [rtNotifs, setRtNotifs] = useState<RtNotif[]>([]);
  const [loaded, setLoaded] = useState(false);
  const isMobile = useIsMobile();

  useEffect(() => {
    getNotifications()
      .then(setSysNotifs)
      .catch(() => null)
      .finally(() => setLoaded(true));
  }, []);

  // ─── Real-time handlers ───────────────────────────────────────────────────────

  const handleDmNew = useCallback((data: unknown) => {
    const p = data as { senderId: string; senderName: string; content: string; conversationId: string };
    if (p.senderId === currentUserId) return;
    if (p.content.startsWith('{"__call__"')) return;
    setRtNotifs((prev) => [
      {
        id: `dm-${Date.now()}`,
        type: "dm",
        title: p.senderName,
        description: p.content.length > 70 ? p.content.slice(0, 70) + "…" : p.content,
        href: `/collaboration/messages?dm=${p.conversationId}`,
        time: "Just now",
        read: false,
      },
      ...prev.slice(0, 9),
    ]);
  }, [currentUserId]);

  const handleMessageNew = useCallback((data: unknown) => {
    const p = data as { senderId: string; senderName: string; content: string; channelName?: string; channelId: string };
    if (p.senderId === currentUserId) return;
    const preview = p.content.length > 55 ? p.content.slice(0, 55) + "…" : p.content;
    setRtNotifs((prev) => [
      {
        id: `ch-${Date.now()}`,
        type: "channel",
        title: `#${p.channelName ?? "channel"}`,
        description: `${p.senderName}: ${preview}`,
        href: `/collaboration/messages?channel=${p.channelId}`,
        time: "Just now",
        read: false,
      },
      ...prev.slice(0, 9),
    ]);
  }, [currentUserId]);

  const handleCallInvite = useCallback((data: unknown) => {
    const p = data as { callerName: string; type: "audio" | "video"; conversationId?: string };
    setRtNotifs((prev) => [
      {
        id: `call-${Date.now()}`,
        type: "call",
        title: `Incoming ${p.type} call`,
        description: `from ${p.callerName}`,
        href: p.conversationId ? `/collaboration/messages?dm=${p.conversationId}` : "/collaboration/messages",
        time: "Just now",
        read: false,
      },
      ...prev.slice(0, 9),
    ]);
  }, []);

  useSocket({
    "dm:new": handleDmNew,
    "message:new": handleMessageNew,
    "call:invite": handleCallInvite,
  });

  // ─── Derived state ────────────────────────────────────────────────────────────

  const allNotifs: DisplayNotif[] = [
    ...rtNotifs,
    ...sysNotifs.map((n) => ({ ...n, description: n.description })),
  ];
  const unreadCount = allNotifs.filter((n) => !n.read).length;

  return (
    <Dropdown
      isOpen={isOpen}
      setIsOpen={(value) => {
        const next = typeof value === "function" ? value(isOpen) : value;
        if (next && !isOpen) {
          setRtNotifs((prev) => prev.map((n) => ({ ...n, read: true })));
        }
        setIsOpen(next);
      }}
    >
      <DropdownTrigger
        className="grid size-12 place-items-center rounded-full border bg-gray-2 text-dark outline-none hover:text-primary focus-visible:border-primary focus-visible:text-primary dark:border-dark-4 dark:bg-dark-3 dark:text-white dark:focus-visible:border-primary"
        aria-label="View Notifications"
      >
        <span className="relative">
          <BellIcon />
          {unreadCount > 0 && (
            <span className={cn("absolute right-0 top-0 z-1 size-2 rounded-full bg-red-light ring-2 ring-gray-2 dark:ring-dark-3")}>
              <span className="absolute inset-0 -z-1 animate-ping rounded-full bg-red-light opacity-75" />
            </span>
          )}
        </span>
      </DropdownTrigger>

      <DropdownContent
        align={isMobile ? "end" : "center"}
        className="border border-stroke bg-white px-3.5 py-3 shadow-md dark:border-dark-3 dark:bg-gray-dark min-[350px]:min-w-[20rem]"
      >
        <div className="mb-1 flex items-center justify-between px-2 py-1.5">
          <span className="text-lg font-medium text-dark dark:text-white">Notifications</span>
          {unreadCount > 0 && (
            <span className="rounded-md bg-primary px-[9px] py-0.5 text-xs font-medium text-white">
              {unreadCount} new
            </span>
          )}
        </div>

        <ul className="mb-3 max-h-[23rem] space-y-1.5 overflow-y-auto">
          {!loaded && rtNotifs.length === 0 ? (
            <li className="px-2 py-4 text-center text-sm text-dark-5 dark:text-dark-6">Loading…</li>
          ) : allNotifs.length === 0 ? (
            <li className="px-2 py-4 text-center text-sm text-dark-5 dark:text-dark-6">All caught up!</li>
          ) : (
            allNotifs.map((item) => (
              <li key={item.id} role="menuitem">
                <Link
                  href={item.href}
                  onClick={() => setIsOpen(false)}
                  className="flex items-start gap-3 rounded-lg px-2 py-2 outline-none hover:bg-gray-2 focus-visible:bg-gray-2 dark:hover:bg-dark-3 dark:focus-visible:bg-dark-3"
                >
                  <span className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gray-100 text-lg dark:bg-dark-3">
                    {TYPE_ICONS[item.type] ?? "🔔"}
                  </span>
                  <div className="min-w-0 flex-1">
                    <strong className={`block text-sm font-medium ${item.read ? "text-dark-5 dark:text-dark-6" : "text-dark dark:text-white"}`}>
                      {item.title}
                    </strong>
                    <span className="block truncate text-xs text-dark-5 dark:text-dark-6">
                      {item.description}
                    </span>
                    <span className="text-xs text-dark-5 dark:text-dark-6">{item.time}</span>
                  </div>
                  {!item.read && (
                    <span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-primary-500" />
                  )}
                </Link>
              </li>
            ))
          )}
        </ul>

        <Link
          href="/collaboration/messages"
          onClick={() => setIsOpen(false)}
          className="block rounded-lg border border-primary p-2 text-center text-sm font-medium tracking-wide text-primary outline-none transition-colors hover:bg-blue-light-5 focus:bg-blue-light-5 dark:border-dark-3 dark:text-dark-6 dark:hover:border-dark-5 dark:hover:bg-dark-3 dark:hover:text-dark-7"
        >
          Go to Messages
        </Link>
      </DropdownContent>
    </Dropdown>
  );
}

